-- =====================================================================
-- MIGRAZIONE 026 — La guerra degli Eroi: 30 nuovi dungeon (26–55) con SCELTE
--   * 30 dungeon in più dopo i 25 classici, ognuno più difficile del precedente (livello consigliato da 114 a 403).
--   * Si entra come prima (lobby, ruoli, 20 energie), ma qui il dungeon NON si risolve in un colpo: il gruppo avanza a bivi.
--     Il capo gruppo sceglie a ogni bivio: ogni scelta cambia strada, bonus/malus alla potenza (%), PV e oggetti-chiave.
--     Alcune scelte sono sbagliate e portano subito al fallimento; altre sono giuste solo se si è letto bene gli indizi.
--   * Ogni dungeon ha più finali: 3 di vittoria (che pagano di più o di meno: da 85% a 140% di BC e XP, e il finale «amaro»
--     dei patti) e 3-4 di fallimento. Si tengono i finali già scoperti, per rigiocarli.
--   * Premi come i classici (oggetto esclusivo alla prima vittoria, un epico/leggendario ogni 5 dungeon, repliche ridotte).
--   * I percorsi (effetti ed esiti) sono in una tabella SENZA accesso dal browser: non si possono leggere in anticipo.
--   * Se nessuno decide più per `game_dng_path_minutes` (120) il dungeon è dato per fallito, con la consolazione prevista.
--   * I dungeon classici 1–25 non cambiano: la loro funzione di partenza è semplicemente rinominata (_game_dng_start_classic).
-- Da eseguire in Supabase (SQL Editor) DOPO la 025. Si può rieseguire. Non tocca saldi o registro già scritti.
-- Nessun nuovo tipo di movimento BC: si usa game_dungeon_reward (solo entrate, come i dungeon classici).
-- =====================================================================
begin;


-- ---------- impostazioni, tabelle e regole nuove ----------
insert into public.system_settings (key, value_int, description) values
 ('game_dng_path_minutes', 120, 'Dungeon a scelte: minuti di inattività dopo i quali un dungeon iniziato e abbandonato viene dato per fallito')
on conflict (key) do nothing;

alter table public.game_dungeons add column if not exists kind text not null default 'classic';
alter table public.game_dungeons drop constraint if exists game_dungeons_kind_chk;
alter table public.game_dungeons add constraint game_dungeons_kind_chk check (kind in ('classic','path'));
alter table public.game_runs add column if not exists state jsonb;
alter table public.game_runs add column if not exists last_move_at timestamptz;
do $$
declare c record;
begin
  for c in select conname from pg_constraint where contype = 'c' and conrelid = 'public.game_runs'::regclass and pg_get_constraintdef(oid) like '%cleared%' loop
    execute format('alter table public.game_runs drop constraint %I', c.conname);
  end loop;
end $$;
alter table public.game_runs drop constraint if exists game_runs_status_chk;
alter table public.game_runs add constraint game_runs_status_chk check (status in ('lobby','active','cleared','failed','cancelled'));
create index if not exists game_runs_active_idx on public.game_runs (status, last_move_at);

-- i percorsi (con effetti ed esiti delle scelte) restano SEGRETI: nessun accesso dal browser, li legge solo il server
create table if not exists public.game_dungeon_graphs (
  dungeon_no smallint primary key references public.game_dungeons(no),
  graph jsonb not null
);
-- i finali scoperti da ogni eroe (uno per esito), per il gusto di rigiocare
create table if not exists public.game_dungeon_endings (
  user_id uuid not null references public.profiles(id) on delete restrict,
  dungeon_no smallint not null references public.game_dungeons(no),
  ending text not null,
  found_at timestamptz not null default now(),
  primary key (user_id, dungeon_no, ending)
);


-- ---------- catalogo: 30 dungeon a scelte ----------
insert into public.game_dungeons (no, name, emoji, lore, boss_name, boss_emoji, boss_lore, rooms, ref_level, min_level, bc, xp, diff, kind, item_id) values
(26, 'Cripta del Re Lich', '⚰️', 'Sotto il vecchio cimitero dorme un re che ha rifiutato la morte: le sue cripte sono una trappola dopo l’altra.', 'Lich Re', '👑', 'Un sovrano scheletrico che ha venduto l’anima in cambio di un potere senza fine.', $j$[{"name":"Scheletri Guardiani","emoji":"💀","boss":false},{"name":"Cavaliere Spettrale","emoji":"👻","boss":false},{"name":"Lich Re","emoji":"👑","boss":true}]$j$::jsonb, 114, 112, 2650, 1536, 1.04, 'path', 'd26'),
(27, 'Giungla degli Insetti', '🐛', 'Una foresta ronzante dove ogni foglia nasconde un artiglio e ogni fiore un veleno.', 'Regina Falena Suprema', '🦋', 'La sovrana dello sciame: le sue ali spargono polvere che addormenta anche i più coraggiosi.', $j$[{"name":"Formiche Soldato","emoji":"🐜","boss":false},{"name":"Mantidi Spettro","emoji":"🦗","boss":false},{"name":"Regina Falena Suprema","emoji":"🦋","boss":true}]$j$::jsonb, 121, 119, 2745, 1616, 1.047, 'path', 'd27'),
(28, 'Torre dell’Orologio Spezzato', '⏰', 'Una torre dove il tempo gira a scatti: ogni lancetta è una promessa, ogni rintocco un debito.', 'Custode del Tempo', '⌛', 'Un guardiano d’ottone che pretende il pagamento di ogni istante sprecato.', $j$[{"name":"Lancette Assassine","emoji":"🗡️","boss":false},{"name":"Ingranaggi Viventi","emoji":"⚙️","boss":false},{"name":"Custode del Tempo","emoji":"⌛","boss":true}]$j$::jsonb, 127, 125, 2840, 1696, 1.054, 'path', 'd28'),
(29, 'Teatro delle Marionette', '🎭', 'Il sipario è sempre aperto: gli spettatori applaudono finché hai voce, poi ti prendono il posto.', 'Burattinaio Folle', '🎪', 'Un artista dai mille fili: ogni eroe che cade diventa una nuova marionetta del suo spettacolo.', $j$[{"name":"Marionette Danzanti","emoji":"🪆","boss":false},{"name":"Arlecchino d’Ombra","emoji":"🃏","boss":false},{"name":"Burattinaio Folle","emoji":"🎪","boss":true}]$j$::jsonb, 135, 133, 2935, 1776, 1.061, 'path', 'd29'),
(30, 'Castello del Drago Imperiale', '🏯', 'Un castello di lacca nera e oro: ogni stanza custodisce un’offerta e ogni offerta ha un prezzo.', 'Drago Imperiale Nero', '🐲', 'Un drago antico che governa il castello da mille anni: pretende rispetto, e lo ottiene col fuoco.', $j$[{"name":"Guardie Imperiali","emoji":"🛡️","boss":false},{"name":"Generale Ombra","emoji":"🥷","boss":false},{"name":"Drago Imperiale Nero","emoji":"🐲","boss":true}]$j$::jsonb, 142, 140, 3030, 1856, 1.068, 'path', 'd30'),
(31, 'Laboratorio Alchemico', '⚗️', 'Alambicchi, vapori e creature nate da errori di calcolo: il laboratorio di un genio che non ha mai ammesso un fallimento.', 'Chimera Alchemica', '🧪', 'Una creatura fatta di mille esperimenti: cambia forma a ogni attacco.', $j$[{"name":"Omuncoli di Vetro","emoji":"🧫","boss":false},{"name":"Golem Fumante","emoji":"💨","boss":false},{"name":"Chimera Alchemica","emoji":"🧪","boss":true}]$j$::jsonb, 150, 148, 3125, 1936, 1.075, 'path', 'd31'),
(32, 'Deserto dei Miraggi', '🏜️', 'Sabbia dorata, acqua che non c’è, città che appaiono e scompaiono: nel deserto nessuna promessa è sicura.', 'Sfinge degli Enigmi', '🐱', 'Una sfinge dagli occhi d’ambra che divora chi sbaglia risposta.', $j$[{"name":"Mummie del Miraggio","emoji":"🧟","boss":false},{"name":"Scorpioni di Cristallo","emoji":"🦂","boss":false},{"name":"Sfinge degli Enigmi","emoji":"🐱","boss":true}]$j$::jsonb, 157, 155, 3220, 2016, 1.082, 'path', 'd32'),
(33, 'Arena dei Gladiatori Infernali', '🏟️', 'Sabbia rossa, folla di demoni: qui si combatte per la gloria, e chi perde regala l’anima agli spettatori.', 'Campione Infernale', '🔱', 'Il gladiatore invitto: ha vinto mille combattimenti e non ricorda il sapore della sconfitta.', $j$[{"name":"Gladiatori Demoniaci","emoji":"⚔️","boss":false},{"name":"Belva dell’Arena","emoji":"🦁","boss":false},{"name":"Campione Infernale","emoji":"🔱","boss":true}]$j$::jsonb, 165, 163, 3315, 2096, 1.089, 'path', 'd33'),
(34, 'Bosco delle Fate Oscure', '🧚', 'Un bosco che canta di notte: le fate sembrano gentili, ma ogni dono nasconde un inganno.', 'Regina Fata Oscura', '🧚‍♀️', 'Una regina che ruba i nomi: chi ne perde uno non sa più chi è.', $j$[{"name":"Folletti Dispettosi","emoji":"🧝","boss":false},{"name":"Cervo di Spine","emoji":"🦌","boss":false},{"name":"Regina Fata Oscura","emoji":"🧚‍♀️","boss":true}]$j$::jsonb, 174, 172, 3410, 2176, 1.096, 'path', 'd34'),
(35, 'Fortezza Meccanica Antica', '⚙️', 'Una fortezza di ferro e vapore costruita da un popolo scomparso: le sue macchine non sanno di aver perso i padroni.', 'Gigante d’Ingranaggi', '🤖', 'Un colosso di bronzo e ruote dentate: si ripara da solo e non dorme mai.', $j$[{"name":"Sentinelle di Ferro","emoji":"🔩","boss":false},{"name":"Ragno Meccanico","emoji":"🕷️","boss":false},{"name":"Gigante d’Ingranaggi","emoji":"🤖","boss":true}]$j$::jsonb, 182, 180, 3505, 2256, 1.103, 'path', 'd35'),
(36, 'Isola dei Pirati Spettrali', '🏴‍☠️', 'Una nebbia che non si alza mai, una nave che non affonda mai, un equipaggio che non muore mai.', 'Capitan Fantasma', '☠️', 'Il capitano di una ciurma maledetta: comanda i morti con un’unica parola, «Ormeggiare».', $j$[{"name":"Quartiermastro Spettrale","emoji":"👻","boss":false},{"name":"Marinai Scheletro","emoji":"💀","boss":false},{"name":"Capitan Fantasma","emoji":"☠️","boss":true}]$j$::jsonb, 191, 189, 3600, 2336, 1.11, 'path', 'd36'),
(37, 'Sala del Trono dei Demoni', '😈', 'Un palazzo di brace e specchi neri: i demoni giudicano ogni ospite in base a ciò che teme.', 'Arcidemone Sovrano', '👿', 'Il re dei demoni: sa sempre cosa temi, e te lo mostra prima di colpirti.', $j$[{"name":"Imp Infuocati","emoji":"😈","boss":false},{"name":"Demone Giudice","emoji":"⚖️","boss":false},{"name":"Arcidemone Sovrano","emoji":"👿","boss":true}]$j$::jsonb, 200, 198, 3695, 2416, 1.117, 'path', 'd37'),
(38, 'Santuario della Luna Nera', '🌙', 'Un tempio di marmo scuro dove la luna non tramonta: le sacerdotesse custodiscono un segreto che brilla.', 'Dea della Luna Nera', '🌑', 'Una dea d’argento e notte: governa le maree e i sogni, e ricorda ogni nome.', $j$[{"name":"Sacerdotesse d’Ombra","emoji":"🕯️","boss":false},{"name":"Lupo d’Argento","emoji":"🐺","boss":false},{"name":"Dea della Luna Nera","emoji":"🌑","boss":true}]$j$::jsonb, 209, 207, 3790, 2496, 1.124, 'path', 'd38'),
(39, 'Villaggio dei Ninja', '🥷', 'Case di carta, tetti silenziosi, ombre che si muovono senza vento: qui nessuno è mai solo.', 'Maestro delle Ombre', '🌑', 'Un ninja leggendario che attacca solo dove non guardi.', $j$[{"name":"Ninja Apprendisti","emoji":"🥷","boss":false},{"name":"Shinobi Veterani","emoji":"🗡️","boss":false},{"name":"Maestro delle Ombre","emoji":"🌑","boss":true}]$j$::jsonb, 219, 217, 3885, 2576, 1.131, 'path', 'd39'),
(40, 'Cittadella dei Samurai', '⛩️', 'Mura di legno scuro e giardini di sabbia: qui l’onore pesa più dell’acciaio.', 'Shogun Corazzato', '🏯', 'Il signore della cittadella: la sua armatura è la più antica del paese, e la sua parola non si spezza.', $j$[{"name":"Ronin Furioso","emoji":"🥷","boss":false},{"name":"Samurai di Guardia","emoji":"⚔️","boss":false},{"name":"Shogun Corazzato","emoji":"🏯","boss":true}]$j$::jsonb, 229, 227, 3980, 2656, 1.138, 'path', 'd40'),
(41, 'Biblioteca dei Sogni', '💤', 'Scaffali che respirano, libri che russano: ogni volume è il sogno di qualcuno che non si è mai svegliato.', 'Signore degli Incubi', '🌫️', 'Un’ombra senza volto che si nutre dei peggiori sogni di chi osa entrare.', $j$[{"name":"Libri Sognanti","emoji":"📖","boss":false},{"name":"Bibliotecario Sonnambulo","emoji":"🧙","boss":false},{"name":"Signore degli Incubi","emoji":"🌫️","boss":true}]$j$::jsonb, 238, 236, 4075, 2736, 1.145, 'path', 'd41'),
(42, 'Cratere dei Meteoriti', '☄️', 'Una valle di vetro e roccia fusa dove cadono stelle: ogni cristallo custodisce l’eco di un cielo lontano.', 'Drago Meteora', '🌠', 'Un drago nato da una stella cadente: le sue scaglie sono roccia incandescente.', $j$[{"name":"Frammenti Vaganti","emoji":"🪨","boss":false},{"name":"Golem di Roccia Stellare","emoji":"💫","boss":false},{"name":"Drago Meteora","emoji":"🌠","boss":true}]$j$::jsonb, 249, 247, 4170, 2816, 1.152, 'path', 'd42'),
(43, 'Bastione dei Titani', '🏔️', 'Una fortezza scolpita nella roccia viva, costruita da giganti che non hanno mai pensato di avere visitatori.', 'Titano di Roccia Celeste', '🗿', 'Un gigante di pietra e cielo: ogni suo passo è un terremoto.', $j$[{"name":"Giganti di Pietra","emoji":"🗿","boss":false},{"name":"Aquile di Roccia","emoji":"🦅","boss":false},{"name":"Titano di Roccia Celeste","emoji":"🗿","boss":true}]$j$::jsonb, 259, 257, 4265, 2896, 1.159, 'path', 'd43'),
(44, 'Fabbrica dei Giocattoli Maledetti', '🧸', 'Orsacchiotti con occhi di vetro, trenini che non si fermano mai, bambole che sussurrano nomi: la fabbrica non ha mai chiuso.', 'Re dei Giocattoli', '🤡', 'Un pupazzo coronato di cartone e rotelle: crede che ogni visitatore sia un nuovo giocattolo.', $j$[{"name":"Clown a Molla","emoji":"🤡","boss":false},{"name":"Orsacchiotti d’Acciaio","emoji":"🧸","boss":false},{"name":"Re dei Giocattoli","emoji":"🤡","boss":true}]$j$::jsonb, 270, 268, 4360, 2976, 1.166, 'path', 'd44'),
(45, 'Reliquario del Drago Bianco', '🐉', 'Un tempio di marmo bianco dove ogni reliquia custodisce un frammento del drago che ha fondato la leggenda.', 'Drago Bianco Antico', '🤍', 'Il primo e il più nobile dei draghi: i suoi occhi blu leggono l’anima.', $j$[{"name":"Custodi di Marmo","emoji":"🗽","boss":false},{"name":"Guardiano delle Reliquie","emoji":"🛡️","boss":false},{"name":"Drago Bianco Antico","emoji":"🤍","boss":true}]$j$::jsonb, 281, 279, 4455, 3056, 1.173, 'path', 'd45'),
(46, 'Palazzo di Specchi', '🪞', 'Mille sale identiche, mille riflessi che sorridono con un attimo di ritardo: chi si smarrisce qui, resta qui.', 'Il Doppio Perfetto', '🪞', 'Un duellante identico a chi lo sfida, ma senza dubbi e senza paura.', $j$[{"name":"Riflessi Ribelli","emoji":"👥","boss":false},{"name":"Sovrano Rovesciato","emoji":"🎭","boss":false},{"name":"Il Doppio Perfetto","emoji":"🪞","boss":true}]$j$::jsonb, 292, 290, 4550, 3136, 1.18, 'path', 'd46'),
(47, 'Giardino Cosmico delle Stelle', '✨', 'Fiori di luce, sentieri di polvere stellare: un giardino sospeso nel vuoto, curato da un giardiniere che non dorme mai.', 'Astromante Supremo', '🔭', 'Un mago cosmico che legge le stelle e piega il destino a suo piacimento.', $j$[{"name":"Guardiani di Luce","emoji":"💫","boss":false},{"name":"Fiori Carnivori Cosmici","emoji":"🌸","boss":false},{"name":"Astromante Supremo","emoji":"🔭","boss":true}]$j$::jsonb, 303, 301, 4645, 3216, 1.187, 'path', 'd47'),
(48, 'Fucina degli Dèi Minori', '🔨', 'Martelli che battono da soli, forni che bruciano ricordi: in questa fucina si forgiano le armi degli dèi più piccoli.', 'Fabbro Divino', '⚒️', 'Un dio dal braccio d’acciaio che forgia armi con il fiato delle stelle.', $j$[{"name":"Salamandra del Forno","emoji":"🦎","boss":false},{"name":"Automi d’Incudine","emoji":"🔩","boss":false},{"name":"Fabbro Divino","emoji":"⚒️","boss":true}]$j$::jsonb, 315, 313, 4740, 3296, 1.194, 'path', 'd48'),
(49, 'Oceano di Nebbia', '🌫️', 'Un mare senza orizzonte: la nebbia inghiotte i suoni, le navi, i nomi. Solo chi sa leggere le onde ritrova la strada.', 'Kraken Spettrale', '🦑', 'Un mostro d’ombra e tentacoli: emerge solo dove la nebbia è più fitta.', $j$[{"name":"Sirene Mute","emoji":"🧜","boss":false},{"name":"Squalo Fantasma","emoji":"🦈","boss":false},{"name":"Kraken Spettrale","emoji":"🦑","boss":true}]$j$::jsonb, 327, 325, 4835, 3376, 1.201, 'path', 'd49'),
(50, 'Altare del Faraone Dimenticato', '🏛️', 'Un tempio sepolto sotto millenni di sabbia: il faraone che lo abita ha cancellato il proprio nome dalla storia, ma non dalla vendetta.', 'Faraone Immortale', '👑', 'Un re senza nome che ha sconfitto la morte e ora pretende sudditi.', $j$[{"name":"Sacerdoti Mummificati","emoji":"🧟","boss":false},{"name":"Sciacalli di Anubi","emoji":"🐺","boss":false},{"name":"Faraone Immortale","emoji":"👑","boss":true}]$j$::jsonb, 339, 337, 4930, 3456, 1.208, 'path', 'd50'),
(51, 'Valle delle Fenici', '🔥', 'Una valle di ceneri e braci dove le fenici muoiono e rinascono ogni giorno, in un ciclo che non perdona i distratti.', 'Fenice Imperitura', '🔥', 'Una fenice che non è mai morta: il suo canto brucia e la sua cenere resuscita.', $j$[{"name":"Pulcini Ardenti","emoji":"🐣","boss":false},{"name":"Salamandre di Cenere","emoji":"🦎","boss":false},{"name":"Fenice Imperitura","emoji":"🔥","boss":true}]$j$::jsonb, 352, 350, 5025, 3536, 1.215, 'path', 'd51'),
(52, 'Gola dei Draghi Antichi', '🏞️', 'Un canyon scavato dal fiato di draghi morti da millenni: le loro ossa formano ponti, e le loro voci ancora lo attraversano.', 'Anziano dei Draghi', '🐲', 'L’ultimo dei draghi antichi: non ricorda la sconfitta, solo la saggezza.', $j$[{"name":"Custode d’Ossa","emoji":"🦴","boss":false},{"name":"Wyrm di Roccia","emoji":"🐍","boss":false},{"name":"Anziano dei Draghi","emoji":"🐲","boss":true}]$j$::jsonb, 364, 362, 5120, 3616, 1.222, 'path', 'd52'),
(53, 'Fortezza del Vuoto', '🕳️', 'Una roccaforte che non esiste: i suoi corridoi si piegano, le sue porte portano altrove, e il suo signore è fatto di assenza.', 'Sentinella del Vuoto', '🌌', 'Un guardiano di niente: ogni colpo che riceve lo rende più vuoto, e quindi più forte.', $j$[{"name":"Ombre Dimenticate","emoji":"🌫️","boss":false},{"name":"Cavalieri Assenti","emoji":"🛡️","boss":false},{"name":"Sentinella del Vuoto","emoji":"🌌","boss":true}]$j$::jsonb, 377, 375, 5215, 3696, 1.229, 'path', 'd53'),
(54, 'Biblioteca del Destino', '📖', 'Ogni vita è un libro in questi scaffali, e qualcuno li riscrive mentre dormi: stai leggendo il tuo, oppure lo stai vivendo?', 'Tessitore del Fato', '🕸️', 'Un’entità che intreccia i fili di ogni destino e ride quando uno si spezza.', $j$[{"name":"Pagine Vaganti","emoji":"📜","boss":false},{"name":"Cronista Senza Volto","emoji":"🖋️","boss":false},{"name":"Tessitore del Fato","emoji":"🕸️","boss":true}]$j$::jsonb, 390, 388, 5310, 3776, 1.236, 'path', 'd54'),
(55, 'Il Cuore della Partita Finale', '🃏', 'L’ultima stanza di ogni duello: qui si decide chi ha davvero giocato, e chi si è limitato a pescare.', 'Il Duellante Primordiale', '🎴', 'Il primo duellante, l’ultimo avversario: ha già visto ogni vostra mossa, e le ha sempre superate.', $j$[{"name":"Carte Evocate","emoji":"🃏","boss":false},{"name":"Campione dei Mille Mazzi","emoji":"🎴","boss":false},{"name":"Il Duellante Primordiale","emoji":"🎴","boss":true}]$j$::jsonb, 403, 401, 5405, 3856, 1.243, 'path', 'd55')
on conflict (no) do update set name = excluded.name, emoji = excluded.emoji, lore = excluded.lore, boss_name = excluded.boss_name, boss_emoji = excluded.boss_emoji, boss_lore = excluded.boss_lore,
  rooms = excluded.rooms, ref_level = excluded.ref_level, min_level = excluded.min_level, bc = excluded.bc, xp = excluded.xp, diff = excluded.diff, kind = excluded.kind, item_id = excluded.item_id;

