 ('d26', 'Lama di Lich Re', 'weapon', 0, 'raro', 112, 57, 28, 0, 0, 0, 0, 0, 'Bottino del dungeon «Cripta del Re Lich».', 'dungeon', 26),
 ('d27', 'Corazza di Regina Falena Suprema', 'armor', 0, 'raro', 119, 0, 0, 59, 0, 30, 0, 0, 'Bottino del dungeon «Giungla degli Insetti».', 'dungeon', 27),
 ('d28', 'Elmo di Custode del Tempo', 'helm', 0, 'raro', 125, 0, 0, 31, 62, 0, 0, 0, 'Bottino del dungeon «Torre dell’Orologio Spezzato».', 'dungeon', 28),
 ('d29', 'Amuleto di Burattinaio Folle', 'amulet', 0, 'raro', 133, 0, 32, 0, 0, 64, 0, 0, 'Bottino del dungeon «Teatro delle Marionette».', 'dungeon', 29),
