 ('d32', 'Corazza di Sfinge degli Enigmi', 'armor', 0, 'raro', 155, 0, 0, 70, 0, 35, 0, 0, 'Bottino del dungeon «Deserto dei Miraggi».', 'dungeon', 32),
 ('d33', 'Elmo di Campione Infernale', 'helm', 0, 'raro', 163, 0, 0, 36, 73, 0, 0, 0, 'Bottino del dungeon «Arena dei Gladiatori Infernali».', 'dungeon', 33),
