 (26, $j${"_start":"s1","s1":{"t":"scene","n":"Ingresso","x":"Il corridoio d’ingresso è cosparso di ossa. Il pavimento ha lastre di due tipi: alcune scure e intatte, altre chiare e consumate dai passi di chi è passato prima di voi.","o":[{"l":"Strappare la torcia d’osso dalla parete","r":"","to":"eF1","id":"a"},{"l":"Camminare solo sulle lastre chiare e consumate","r":"Il gruppo attraversa il corridoio senza far scattare nulla e nota un’incisione sul muro.","to":"s2","fx":{"pow":8,"flag":"indizio"},"id":"b"},{"l":"Correre dritti sulle lastre scure","r":"Una raffica di lame esce dal muro: ferite, ma la via è libera… e un guardiano si desta.","to":"f1e","fx":{"hp":-20,"pow":6},"id":"c"}]},"s2":{"t":"scene","n":"La chiave","x":"L’incisione dice: «Il sigillo riposa dove la fiamma è morta». Davanti a voi tre nicchie: un teschio sorridente, una candela spenta, uno scrigno incatenato.","o":[{"l":"Frugare nella nicchia con la candela spenta","r":"Sotto la cera fredda trovate il Sigillo d’Osso. Gli scheletri vi hanno sentiti, ma siete pronti.","to":"f1w","fx":{"pow":8,"flag":"key"},"id":"a"},{"l":"Aprire lo scrigno incatenato","r":"","to":"eF2","id":"b"},{"l":"Ignorare le nicchie e proseguire","r":"Avanzate senza sigillo: il tempo perso costa fatica.","to":"f1","fx":{"hp":-12},"id":"c"}]},"f1w":{"t":"fight","e":"Scheletri Guardiani","em":"💀","m":0.85,"k":"n","w":"s3","l":"eDef"},"f1":{"t":"fight","e":"Scheletri Guardiani","em":"💀","m":1.0,"k":"n","w":"s3","l":"eDef"},"f1e":{"t":"fight","e":"Cavaliere Spettrale","em":"👻","m":1.3,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Il bivio finale","x":"La sala del trono. Il Lich Re medita sul suo scranno. A sinistra un sarcofago sigillato, a destra una fontana di anime, davanti a voi un lungo tappeto nero.","o":[{"l":"Usare il Sigillo d’Osso sul sarcofago sigillato","r":"Il sarcofago custodisce la fonte del potere del Lich: spezzarla lo indebolisce di colpo.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"a"},{"l":"Riposare accanto alla fontana di anime","r":"Le anime curano le ferite, ma il Lich sente l’intrusione e si rafforza.","to":"fb","fx":{"hp":35,"pow":-12},"id":"b"},{"l":"Avanzare lungo il tappeto nero","r":"Il Lich alza il capo: vi aspettava.","to":"fb","id":"c"},{"l":"Bere dalla fontana di anime","r":"","to":"eF3","id":"d"}]},"fb":{"t":"fight","e":"Lich Re","em":"👑","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"La polvere dei re","x":"Con il sarcofago spezzato il Lich invecchia di mille anni in un istante e si sbriciola. Il silenzio della cripta è finalmente vero.","text":"Con il sarcofago spezzato il Lich invecchia di mille anni in un istante e si sbriciola. Il silenzio della cripta è finalmente vero.","m":140},"eGood":{"t":"end","win":true,"title":"Il re ha perso il trono","x":"Il Lich cade, ma il suo scettro continua a vibrare per un po’. Avete vinto, e avete anche imparato a rispettare i morti.","text":"Il Lich cade, ma il suo scettro continua a vibrare per un po’. Avete vinto, e avete anche imparato a rispettare i morti.","m":115},"eOk":{"t":"end","win":true,"title":"Vittoria sul filo","x":"Il Lich si disfa quando le forze quasi vi abbandonano. Uscite zoppicando, vivi per un soffio.","text":"Il Lich si disfa quando le forze quasi vi abbandonano. Uscite zoppicando, vivi per un soffio.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Era il meccanismo della trappola: il pavimento cede e il gruppo precipita nel pozzo dei defunti. La spedizione finisce qui.","text":"Era il meccanismo della trappola: il pavimento cede e il gruppo precipita nel pozzo dei defunti. La spedizione finisce qui.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Lo scrigno era un cadavere-mimico: si chiude sul gruppo e non si apre più.","text":"Lo scrigno era un cadavere-mimico: si chiude sul gruppo e non si apre più.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Le anime vi trascinano nel loro coro: la mente del gruppo si spegne tra i sussurri.","text":"Le anime vi trascinano nel loro coro: la mente del gruppo si spegne tra i sussurri.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Le forze vi abbandonano: il Lich vi proclama suoi nuovi servitori. La spedizione è fallita.","text":"Le forze vi abbandonano: il Lich vi proclama suoi nuovi servitori. La spedizione è fallita.","m":100},"_flags":{"indizio":"Indizio","key":"Sigillo d’Osso","sigillo":"Sigillo spezzato"}}$j$::jsonb),
 (27, $j${"_start":"s1","s1":{"t":"scene","n":"Due strade","x":"La giungla è un muro di foglie. Il sentiero principale è largo e battuto da mille zampe. Poco più in là, dietro un velo di ragnatele, si intravede un passaggio stretto tra i rami.","o":[{"l":"Seguire il sentiero largo e affrontare gli insetti","r":"Il gruppo avanza a testa alta: sciami in arrivo.","to":"f1","fx":{"flag":"forza"},"id":"a"},{"l":"Tuffarsi nello stagno ronzante della radura","r":"","to":"eF1","id":"b"},{"l":"Infilarsi nel passaggio dietro le ragnatele","r":"Tra i rami il rumore dei passi si perde: nessuno vi ha visti.","to":"sp","id":"c"}]},"f1":{"t":"fight","e":"Formiche Soldato","em":"🐜","m":1.1,"k":"n","w":"f2","l":"eDef"},"f2":{"t":"fight","e":"Mantidi Spettro","em":"🦗","m":1.2,"k":"e","w":"ss","l":"eDef"},"ss":{"t":"scene","n":"Il bottino","x":"Fra i gusci dei nemici abbattuti brilla un’ala di cristallo affilata. Poco lontano un bozzolo di miele tiepido pulsa piano. Più in alto, un fiore enorme splende di polline nero.","o":[{"l":"Impugnare l’ala di cristallo come arma","r":"L’ala taglia l’aria: il gruppo si sente più letale.","to":"s3","fx":{"pow":15},"id":"a"},{"l":"Annusare il fiore di polline nero","r":"","to":"eF3","id":"b"},{"l":"Riposare nel miele del bozzolo","r":"Il miele cura le ferite e dà nuova lena.","to":"s3","fx":{"hp":30},"id":"c"}]},"sp":{"t":"scene","n":"Il passaggio nascosto","x":"Il passaggio sbuca in una grotta di bozzoli. Tre fori nella parete: uno emette un ronzio basso, uno è colmo di miele, uno sibila vapore scuro. Una scritta dice: «L’ape non dorme dove sale il vapore: cerca il dolce».","o":[{"l":"Ascoltare il foro che ronza","r":"Ne escono formiche furiose: toccherà respingerle.","to":"f3","fx":{"hp":-25},"id":"a"},{"l":"Soffiare dentro il foro del vapore scuro","r":"","to":"eF2","id":"b"},{"l":"Infilare la mano nel foro colmo di miele","r":"Trovate il Nettare Narcotico: una boccetta capace di far dormire anche la regina.","to":"s3","fx":{"hp":10,"flag":"key"},"id":"c"}]},"f3":{"t":"fight","e":"Formiche Soldato","em":"🐜","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al covo","x":"Davanti al nido della Regina Falena: un portone di cera dura. Il suolo è coperto da un tappeto di polline e, a lato, braci sempre accese.","o":[{"l":"Accamparsi nel polline per riprendere fiato","r":"Il polline cura, ma i battiti d’ala della regina arrivano più rabbiosi.","to":"fb","fx":{"hp":25,"pow":-8},"id":"a"},{"l":"Sfondare il portone di cera","r":"La regina si sveglia con un sibilo acuto.","to":"fb","id":"b"},{"l":"Versare il nettare narcotico nelle braci del nido","r":"Il fumo dolciastro avvolge la regina: i suoi battiti d’ala rallentano.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"}]},"fb":{"t":"fight","e":"Regina Falena Suprema","em":"🦋","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["forza"],"to":"eGood"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"La regina addormentata","x":"La Regina Falena crolla in un sonno senza sogni mentre il suo sciame si disperde. La giungla tace e vi lascia passare.","text":"La Regina Falena crolla in un sonno senza sogni mentre il suo sciame si disperde. La giungla tace e vi lascia passare.","m":140},"eGood":{"t":"end","win":true,"title":"Lo sciame è sconfitto","x":"Dopo una lotta serrata la regina cade. Lo sciame si disperde senza una guida: la giungla è vostra.","text":"Dopo una lotta serrata la regina cade. Lo sciame si disperde senza una guida: la giungla è vostra.","m":115},"eOk":{"t":"end","win":true,"title":"Fuga con un trofeo","x":"La regina cede quando ormai quasi non avete forze: portate via il bottino e un sacco di punture.","text":"La regina cede quando ormai quasi non avete forze: portate via il bottino e un sacco di punture.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Lo stagno era un nido: migliaia di larve vi coprono prima che possiate gridare.","text":"Lo stagno era un nido: migliaia di larve vi coprono prima che possiate gridare.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il vapore scuro è un gas paralizzante: il gruppo cade a terra e gli insetti iniziano il loro banchetto.","text":"Il vapore scuro è un gas paralizzante: il gruppo cade a terra e gli insetti iniziano il loro banchetto.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il polline è un veleno soporifero: il gruppo si addormenta per sempre tra i fiori.","text":"Il polline è un veleno soporifero: il gruppo si addormenta per sempre tra i fiori.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Gli artigli e le ali vi sopraffanno: la giungla vi inghiotte. La spedizione è fallita.","text":"Gli artigli e le ali vi sopraffanno: la giungla vi inghiotte. La spedizione è fallita.","m":100},"_flags":{"forza":"Via dei mostri","key":"Nettare Narcotico","sigillo":"Accesso segreto"}}$j$::jsonb),
 (28, $j${"_start":"s1","s1":{"t":"scene","n":"Un incontro","x":"Alla base della torre un vecchio orologiaio dagli occhi cavi vi sbarra la scala: «Posso fermare le lancette per voi, ma il tempo ha un prezzo: la vostra forza vitale.»","o":[{"l":"Attaccare il vecchio per passare","r":"","to":"f0","id":"a"},{"l":"Rifiutare con garbo e salire da soli","r":"L’orologiaio annuisce, quasi deluso: «Gli onesti sono rari». Vi lascia passare.","to":"s2","fx":{"pow":6,"flag":"onore"},"id":"b"},{"l":"Accettare il patto: pagare con la forza vitale","r":"Il gruppo sente una fitta di stanchezza. L’orologiaio sorride e si fa da parte.","to":"s2","fx":{"hp":-30,"flag":"patto"},"id":"c"}]},"f0":{"t":"fight","e":"Lancette Assassine","em":"🗡️","m":1.9,"k":"e","w":"s2","l":"eDef","wfx":{"pow":12}},"s2":{"t":"scene","n":"Il santuario","x":"A metà torre una gabbia di ingranaggi tiene prigioniero un apprendista. Poco più in là, un quadrante d’oro massiccio brilla sull’altare, senza nessuno a sorvegliarlo.","o":[{"l":"Spaccare il meccanismo dell’altare","r":"","to":"eF1","id":"a"},{"l":"Proseguire senza fermarsi","r":"Non c’è tempo da perdere. Salite.","to":"f1","id":"b"},{"l":"Prendere il quadrante d’oro dall’altare","r":"Il quadrante è pesante ma vi dà una carica nuova. Qualcosa, nelle pareti, si muove.","to":"f1","fx":{"pow":10},"id":"c"},{"l":"Liberare l’apprendista","r":"L’apprendista, tremando, giura di aiutarvi quando servirà. Il lavoro vi costa un po’ di fiato.","to":"f1","fx":{"hp":-10,"pow":15,"flag":"alleato"},"id":"d"}]},"f1":{"t":"fight","e":"Ingranaggi Viventi","em":"⚙️","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al signore del luogo","x":"In cima alla torre il Custode del Tempo attende, sospeso tra due pendoli giganti. I suoi occhi sono clessidre.","o":[{"l":"Salire i gradini e affrontarlo senza trucchi","r":"Il Custode non fa sconti.","to":"fb","id":"a"},{"l":"Chiamare l’apprendista: conosce il punto debole dei pendoli","r":"L’apprendista fa deragliare un pendolo: il Custode vacilla.","to":"fb","fx":{"pow":20},"only":["alleato"],"id":"b"},{"l":"Presentarsi a testa alta e senza debiti","r":"Il Custode riconosce chi non gli deve nulla e concede un duello onesto, senza trucchi.","to":"fb","fx":{"pow":20,"flag":"puro"},"only":["onore"],"id":"c"},{"l":"Rompere il patto e sfidarlo comunque","r":"Il patto infranto brucia: il Custode lo sente e vi colpisce con rabbia.","to":"fb","fx":{"pow":-20,"hp":-15},"only":["patto"],"id":"d"},{"l":"Onorare il patto: consegnare la forza vitale promessa","r":"Il Custode accetta il pagamento e rallenta il suo stesso tempo: i colpi del gruppo diventano più rapidi.","to":"fb","fx":{"pow":35,"flag":"oscuro"},"only":["patto"],"id":"e"},{"l":"Fermare a mani nude uno dei pendoli","r":"","to":"eF2","id":"f"}]},"fb":{"t":"fight","e":"Custode del Tempo","em":"⌛","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["oscuro"],"to":"eDark"},{"if":["puro"],"to":"eBest"},{"if":["alleato"],"to":"eGood"}],"d":"eOk"},"eDark":{"t":"end","win":true,"title":"Il prezzo del tempo","x":"Il Custode cade, ma il patto è onorato fino in fondo: un pezzo del vostro tempo resta nell’orologio. Vittoria amara, e potente.","text":"Il Custode cade, ma il patto è onorato fino in fondo: un pezzo del vostro tempo resta nell’orologio. Vittoria amara, e potente.","m":125},"eBest":{"t":"end","win":true,"title":"Nessun debito","x":"Chi non deve nulla al tempo lo domina: il Custode si ferma, e con lui tutto l’orologio, in un rintocco di pace.","text":"Chi non deve nulla al tempo lo domina: il Custode si ferma, e con lui tutto l’orologio, in un rintocco di pace.","m":140},"eGood":{"t":"end","win":true,"title":"Il tempo ringrazia","x":"L’apprendista ricostruisce le lancette. Il Custode, sconfitto, lascia che il tempo riparta a scorrere.","text":"L’apprendista ricostruisce le lancette. Il Custode, sconfitto, lascia che il tempo riparta a scorrere.","m":115},"eOk":{"t":"end","win":true,"title":"Un rintocco di troppo","x":"Il Custode si arrende, ma l’orologio resta storto. Uscite con l’affanno di chi ha corso contro il tempo.","text":"Il Custode si arrende, ma l’orologio resta storto. Uscite con l’affanno di chi ha corso contro il tempo.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il meccanismo dell’altare era una ghigliottina d’ingranaggi: il gruppo viene stritolato in un istante.","text":"Il meccanismo dell’altare era una ghigliottina d’ingranaggi: il gruppo viene stritolato in un istante.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"I pendoli ruotano, l’aria si ferma: il gruppo resta congelato nel tempo per sempre.","text":"I pendoli ruotano, l’aria si ferma: il gruppo resta congelato nel tempo per sempre.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Custode sospende il vostro tempo: la spedizione si ferma, per sempre, a un rintocco dalla vittoria.","text":"Il Custode sospende il vostro tempo: la spedizione si ferma, per sempre, a un rintocco dalla vittoria.","m":100},"_flags":{"patto":"Patto stretto","onore":"Parola d’onore","alleato":"Alleato liberato","oscuro":"Patto onorato","puro":"Fiducia ripagata"}}$j$::jsonb),
 (29, $j${"_start":"s1","s1":{"t":"scene","n":"Prima prova","x":"Il sipario si alza sulla prima prova. Sul palco, un cartello: «Il Burattinaio non ama la luce: i suoi fili brillano solo al buio». In platea, una serie di candelabri spenti e una botola nel pavimento.","o":[{"l":"Studiare i fili e il cartello prima di muoversi","r":"Notate che i fili sono sottilissimi e si spezzano con una luce intensa. Un dettaglio che potrebbe servire.","to":"f1","fx":{"flag":"indizio","pow":5},"id":"a"},{"l":"Prendere le scorte dalla platea e andare avanti","r":"Trovate pane e acqua. Il sipario si richiude alle vostre spalle.","to":"f1","fx":{"hp":15},"id":"b"},{"l":"Aprire la botola nel pavimento","r":"","to":"eF1","id":"c"}]},"f1":{"t":"fight","e":"Marionette Danzanti","em":"🪆","m":1.0,"k":"n","w":"s2","l":"eDef"},"s2":{"t":"scene","n":"Seconda prova","x":"La seconda prova: un corridoio di quinte dipinte. Da un lato una scala di corda, dall’altro un tendone che nasconde una luce intensa, davanti a voi un ponte di assi sospeso su un baratro.","o":[{"l":"Attraversare il ponte di assi sospeso","r":"","to":"eF2","id":"a"},{"l":"Muoversi con cautela tra le quinte","r":"Evitate il peggio, ma non il sudore freddo.","to":"f2","fx":{"hp":-5},"id":"b"},{"l":"Affrontare il corridoio di petto, a viso aperto","r":"Le marionette vi assalgono, ma voi combattete con furia. Ne uscite stanchi ma carichi.","to":"f2","fx":{"pow":12,"hp":-20},"id":"c"}]},"f2":{"t":"fight","e":"Arlecchino d’Ombra","em":"🃏","m":1.15,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"La prova finale","x":"Il Burattinaio sta in cima alla scena, i fili che pendono dalle sue dita fino al soffitto. Dietro di lui, quattro grandi fari da palcoscenico.","o":[{"l":"Spegnere i fari per sorprenderlo al buio","r":"È il suo terreno preferito: i fili brillano più forti.","to":"fb","fx":{"pow":-25},"id":"a"},{"l":"Accendere tutti i fari di scena sul Burattinaio","r":"La luce inonda il palco: i fili si spezzano in un lampo e il Burattinaio barcolla.","to":"fb","fx":{"pow":35,"flag":"punto"},"id":"b"},{"l":"Tagliare i fili a colpi di spada","r":"I fili sono troppi: il Burattinaio li rinnova ad ogni colpo.","to":"fb","fx":{"pow":-25},"id":"c"},{"l":"Tirare uno dei fili che pendono dal soffitto","r":"","to":"eF3","id":"d"}],"h":{"if":"indizio","t":"Ricordate il cartello: i suoi fili brillano solo al buio. Un faro puntato sul suo spettacolo potrebbe tagliarli tutti."}},"fb":{"t":"fight","e":"Burattinaio Folle","em":"🎪","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["punto","indizio"],"to":"eBest"},{"if":["punto"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Gran finale","x":"I fili si spezzano e le marionette cadono. Il Burattinaio, finalmente solo sul palco, si inchina alla platea vuota e svanisce.","text":"I fili si spezzano e le marionette cadono. Il Burattinaio, finalmente solo sul palco, si inchina alla platea vuota e svanisce.","m":140},"eGood":{"t":"end","win":true,"title":"Applausi finali","x":"Il Burattinaio crolla tra i suoi fili tagliati. La platea applaude: forse la prima volta senza paura.","text":"Il Burattinaio crolla tra i suoi fili tagliati. La platea applaude: forse la prima volta senza paura.","m":115},"eOk":{"t":"end","win":true,"title":"Sipario!","x":"Lo spettacolo finisce quasi a sorpresa: il Burattinaio si ritira, e voi con lui, feriti ma vivi.","text":"Lo spettacolo finisce quasi a sorpresa: il Burattinaio si ritira, e voi con lui, feriti ma vivi.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Dalla botola emerge una mano di legno che vi trascina nel sottopalco. Lo spettacolo continua senza di voi.","text":"Dalla botola emerge una mano di legno che vi trascina nel sottopalco. Lo spettacolo continua senza di voi.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il ponte di assi si spezza sotto il gruppo: il baratro è senza fondo.","text":"Il ponte di assi si spezza sotto il gruppo: il baratro è senza fondo.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il filo è collegato al tuo cuore: ti aggrega allo spettacolo come nuova marionetta.","text":"Il filo è collegato al tuo cuore: ti aggrega allo spettacolo come nuova marionetta.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Burattinaio vi fa danzare fino all’ultimo respiro: la spedizione è fallita.","text":"Il Burattinaio vi fa danzare fino all’ultimo respiro: la spedizione è fallita.","m":100},"_flags":{"indizio":"Indizio decifrato","punto":"Punto debole colpito"}}$j$::jsonb),
 (30, $j${"_start":"s1","s1":{"t":"scene","n":"Ingresso","x":"Il portone del castello è aperto. Nel cortile, un lungo tappeto rosso porta alla scalinata, ma ai lati stanno statue di guerrieri con le lance puntate verso il centro. Un vecchio scrivano mormora: «Chi entra deve inchinarsi».","o":[{"l":"Attraversare il cortile inchinandosi come a corte","r":"Le lance restano ferme: il gruppo passa tra le statue. Lo scrivano vi consegna una pergamena di cortesia.","to":"s2","fx":{"pow":8,"flag":"indizio"},"id":"a"},{"l":"Estrarre la lancia dalla statua più vicina","r":"","to":"eF1","id":"b"},{"l":"Correre lungo il bordo, fuori dal tappeto","r":"Una lancia vi sfiora e un generale si accorge di voi.","to":"f1e","fx":{"hp":-20,"pow":6},"id":"c"}]},"s2":{"t":"scene","n":"La chiave","x":"Nella sala degli archivi la pergamena si illumina: «Il sigillo del drago è nella lacca che non riflette». Davanti a voi, tre grandi paraventi laccati: uno specchiante, uno opaco e uno dorato.","o":[{"l":"Esaminare il paravento di lacca opaca","r":"Dietro la lacca opaca trovate il Sigillo Imperiale. Alle vostre spalle, le guardie sentono il rumore.","to":"f1w","fx":{"pow":8,"flag":"key"},"id":"a"},{"l":"Lasciare gli archivi e proseguire","r":"Senza il sigillo, ma con un po’ di fiato risparmiato, proseguite.","to":"f1","fx":{"hp":-12},"id":"b"},{"l":"Rompere il paravento dorato","r":"","to":"eF2","id":"c"}]},"f1w":{"t":"fight","e":"Guardie Imperiali","em":"🛡️","m":0.85,"k":"n","w":"s3","l":"eDef"},"f1":{"t":"fight","e":"Guardie Imperiali","em":"🛡️","m":1.0,"k":"n","w":"s3","l":"eDef"},"f1e":{"t":"fight","e":"Generale Ombra","em":"🥷","m":1.3,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Il bivio finale","x":"La sala del trono del Drago: un trono di ossa, un incensiere gigante, una lunga cortina di seta rossa. Il drago, avvolto nel fumo, vi guarda.","o":[{"l":"Sfidare il drago a viso aperto","r":"Il drago ride, e le fiamme riempiono la sala.","to":"fb","id":"a"},{"l":"Sostare davanti all’incensiere per ritemprarvi","r":"Il fumo cura, ma il drago è già in piedi quando riaprite gli occhi.","to":"fb","fx":{"hp":35,"pow":-12},"id":"b"},{"l":"Strappare la cortina di seta rossa","r":"","to":"eF3","id":"c"},{"l":"Presentare il Sigillo Imperiale al drago","r":"Il drago riconosce il sigillo del suo ordine e, per un istante, esita: il suo scudo di fiamme si abbassa.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"d"}]},"fb":{"t":"fight","e":"Drago Imperiale Nero","em":"🐲","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il drago riconosce il suo erede","x":"Il drago abbassa il capo davanti al sigillo e, prima di cadere, vi riconosce. Il castello vi saluta con mille lanterne.","text":"Il drago abbassa il capo davanti al sigillo e, prima di cadere, vi riconosce. Il castello vi saluta con mille lanterne.","m":140},"eGood":{"t":"end","win":true,"title":"Il castello cade","x":"Il drago crolla tra le fiamme e la lacca si scioglie in pioggia nera. Il castello è vostro.","text":"Il drago crolla tra le fiamme e la lacca si scioglie in pioggia nera. Il castello è vostro.","m":115},"eOk":{"t":"end","win":true,"title":"Una vittoria sudata","x":"Il drago si ritira ferito. Le lanterne del castello si spengono a una a una, in segno di rispetto.","text":"Il drago si ritira ferito. Le lanterne del castello si spengono a una a una, in segno di rispetto.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La lancia della statua è la chiave di una trappola: il cortile si chiude e le altre statue vi infilzano.","text":"La lancia della statua è la chiave di una trappola: il cortile si chiude e le altre statue vi infilzano.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il paravento dorato era una trappola di fuoco: la sala si incendia e non c’è via d’uscita.","text":"Il paravento dorato era una trappola di fuoco: la sala si incendia e non c’è via d’uscita.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"La cortina nasconde un baratro: il gruppo precipita nelle cucine del drago.","text":"La cortina nasconde un baratro: il gruppo precipita nelle cucine del drago.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il drago vi riduce in cenere: la spedizione è fallita, e il castello torna a dormire.","text":"Il drago vi riduce in cenere: la spedizione è fallita, e il castello torna a dormire.","m":100},"_flags":{"indizio":"Indizio","key":"Sigillo Imperiale","sigillo":"Sigillo spezzato"}}$j$::jsonb),
 (31, $j${"_start":"s1","s1":{"t":"scene","n":"Due strade","x":"L’ingresso del laboratorio si divide in due. A sinistra la sala dei test, dove si sentono esplosioni e ruggiti. A destra, una porta stretta con un cartello: «Solo i prudenti guardano la parete».","o":[{"l":"Entrare nella sala dei test e combattere le creature","r":"Gli esperimenti sono scatenati, ma avete l’energia per affrontarli.","to":"f1","fx":{"flag":"forza"},"id":"a"},{"l":"Bere dalla fiala luminosa sul bancone","r":"","to":"eF1","id":"b"},{"l":"Aprire la porta stretta e leggere la parete","r":"Sulla parete, schemi chimici dettagliati: qualcuno vuole che li leggiate.","to":"sp","id":"c"}]},"f1":{"t":"fight","e":"Omuncoli di Vetro","em":"🧫","m":1.1,"k":"n","w":"f2","l":"eDef"},"f2":{"t":"fight","e":"Golem Fumante","em":"💨","m":1.2,"k":"e","w":"ss","l":"eDef"},"ss":{"t":"scene","n":"Il bottino","x":"Tra i cocci degli omuncoli, tre oggetti: un guanto da forgiatore ancora caldo, una bolla di antidoto fluttuante e un barile con la scritta «NON APRIRE».","o":[{"l":"Bere l’antidoto fluttuante","r":"Il liquido pulisce le ferite e ridà vigore.","to":"s3","fx":{"hp":30},"id":"a"},{"l":"Infilare il guanto da forgiatore","r":"Il guanto vibra di energia: ogni colpo del gruppo è più potente.","to":"s3","fx":{"pow":15},"id":"b"},{"l":"Aprire il barile con la scritta «NON APRIRE»","r":"","to":"eF3","id":"c"}]},"sp":{"t":"scene","n":"Il passaggio nascosto","x":"Gli schemi sulla parete mostrano tre ampolle: una verde che fuma, una blu che gorgoglia, una trasparente e silenziosa. Sotto, una nota: «Per fermare il mutevole serve ciò che non muta: la quieta».","o":[{"l":"Prendere l’ampolla blu che gorgoglia","r":"L’ampolla esplode in una nube di schiuma: dovete scappare combattendo contro i prodotti del suo vapore.","to":"f3","fx":{"hp":-25},"id":"a"},{"l":"Prendere l’ampolla trasparente e silenziosa","r":"La Fiala di Neutralizzazione è vostra: potrà bloccare le trasformazioni della chimera.","to":"s3","fx":{"hp":10,"flag":"key"},"id":"b"},{"l":"Bere l’ampolla verde che fuma","r":"","to":"eF2","id":"c"}]},"f3":{"t":"fight","e":"Omuncoli di Vetro","em":"🧫","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al covo","x":"Il covo della Chimera: una grande camera di vetro piena di vapori. Al centro un calderone fumante, ai lati due leve, e davanti alla bestia una pedana d’ottone.","o":[{"l":"Riposare tra i vapori curativi vicino alla leva","r":"I vapori curano, ma la Chimera cambia e si adatta.","to":"fb","fx":{"hp":25,"pow":-8},"id":"a"},{"l":"Attaccare direttamente la Chimera","r":"La Chimera cambia forma: ora ha artigli, ora squame.","to":"fb","id":"b"},{"l":"Gettare la Fiala di Neutralizzazione nel calderone","r":"La reazione blocca ogni trasformazione: la Chimera è ora intrappolata in un’unica forma.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"}]},"fb":{"t":"fight","e":"Chimera Alchemica","em":"🧪","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["forza"],"to":"eGood"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"La formula perfetta","x":"Bloccata in un’unica forma, la Chimera si spegne come una fiamma senza ossigeno. Il laboratorio, finalmente, tace.","text":"Bloccata in un’unica forma, la Chimera si spegne come una fiamma senza ossigeno. Il laboratorio, finalmente, tace.","m":140},"eGood":{"t":"end","win":true,"title":"Esperimento concluso","x":"La Chimera cade, travolta da mille trasformazioni. Raccogliete i campioni e uscite dalla porta principale.","text":"La Chimera cade, travolta da mille trasformazioni. Raccogliete i campioni e uscite dalla porta principale.","m":115},"eOk":{"t":"end","win":true,"title":"Reazione a catena","x":"La Chimera si dissolve in un’esplosione. Uscite pieni di bruciature, ma in piedi.","text":"La Chimera si dissolve in un’esplosione. Uscite pieni di bruciature, ma in piedi.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La fiala luminosa è un veleno a effetto lento: il gruppo si accascia prima ancora di capire.","text":"La fiala luminosa è un veleno a effetto lento: il gruppo si accascia prima ancora di capire.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’ampolla verde è una polvere che trasforma: il gruppo diventa parte del prossimo esperimento.","text":"L’ampolla verde è una polvere che trasforma: il gruppo diventa parte del prossimo esperimento.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il barile contiene vapori infiammabili: la sala esplode in un lampo bianco.","text":"Il barile contiene vapori infiammabili: la sala esplode in un lampo bianco.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"La Chimera si trasforma in un incubo di mille armi: il gruppo viene sopraffatto. Spedizione fallita.","text":"La Chimera si trasforma in un incubo di mille armi: il gruppo viene sopraffatto. Spedizione fallita.","m":100},"_flags":{"forza":"Via dei mostri","key":"Fiala di Neutralizzazione","sigillo":"Accesso segreto"}}$j$::jsonb),
 (32, $j${"_start":"s1","s1":{"t":"scene","n":"Un incontro","x":"Un mercante dalla pelle bruciata vi ferma sotto una tenda: «Vi do acqua e una guida, ma voglio in cambio una parte delle vostre forze: il sole mi ha prosciugato».","o":[{"l":"Accettare il patto: cedergli parte delle forze","r":"Il mercante beve la vostra stanchezza e vi dona una borraccia fresca. Il passo è più pesante.","to":"s2","fx":{"hp":-30,"flag":"patto"},"id":"a"},{"l":"Rubare l’acqua al mercante","r":"","to":"f0","id":"b"},{"l":"Rifiutare e proseguire con le proprie scorte","r":"Il mercante si ritira. «Gli orgogliosi trovano sempre la strada», mormora.","to":"s2","fx":{"pow":6,"flag":"onore"},"id":"c"}]},"f0":{"t":"fight","e":"Mummie del Miraggio","em":"🧟","m":1.9,"k":"e","w":"s2","l":"eDef","wfx":{"pow":12}},"s2":{"t":"scene","n":"Il santuario","x":"Un’oasi appare davanti a voi, circondata da palme. Nella sabbia, una carovana abbandonata con una persona in catene. Poco lontano, un piccolo altare d’oro riflette il sole.","o":[{"l":"Passare oltre senza fermarsi","r":"Il vento cancella le impronte. Proseguite.","to":"f1","id":"a"},{"l":"Prendere le monete d’oro dall’altare","r":"Il bottino è pesante ma vi dà nuova baldanza. Un rumore di scaglie vi segue.","to":"f1","fx":{"pow":10},"id":"b"},{"l":"Liberare il prigioniero incatenato","r":"Il prigioniero, un’antica guida, giura di ricambiare l’aiuto. Il tempo perso vi stanca.","to":"f1","fx":{"hp":-10,"pow":15,"flag":"alleato"},"id":"c"},{"l":"Bere dalle acque dell’oasi senza esitare","r":"","to":"eF1","id":"d"}]},"f1":{"t":"fight","e":"Scorpioni di Cristallo","em":"🦂","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al signore del luogo","x":"La Sfinge vi attende in una valle di dune sospese. Sul suo petto una scritta: «Chi risponde bene passa, chi risponde male resta».","o":[{"l":"Sfidarla in un combattimento aperto","r":"La Sfinge sorride e mostra gli artigli.","to":"fb","id":"a"},{"l":"Chiedere alla guida liberata di suggerire la risposta","r":"La guida sussurra l’enigma risolto: la Sfinge, offesa, perde la sua calma.","to":"fb","fx":{"pow":20},"only":["alleato"],"id":"b"},{"l":"Rispondere con onestà, senza trucchi","r":"La Sfinge, sorpresa dalla sincerità, abbassa la guardia e accetta un duello leale.","to":"fb","fx":{"pow":20,"flag":"puro"},"only":["onore"],"id":"c"},{"l":"Rompere il patto e sfidarla con la forza","r":"Il patto infranto richiama una tempesta di sabbia contro di voi.","to":"fb","fx":{"pow":-20,"hp":-15},"only":["patto"],"id":"d"},{"l":"Onorare il patto del mercante: pronunciare la parola segreta che vi ha dato","r":"La Sfinge sussulta: la parola era il nome di un suo antico padrone. Il suo potere vacilla.","to":"fb","fx":{"pow":35,"flag":"oscuro"},"only":["patto"],"id":"e"},{"l":"Rispondere a caso all’enigma","r":"","to":"eF2","id":"f"}]},"fb":{"t":"fight","e":"Sfinge degli Enigmi","em":"🐱","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["oscuro"],"to":"eDark"},{"if":["puro"],"to":"eBest"},{"if":["alleato"],"to":"eGood"}],"d":"eOk"},"eDark":{"t":"end","win":true,"title":"Il nome del padrone","x":"La parola pronunciata spezza il giuramento della Sfinge: cade, e con lei un pezzo del miraggio. Una vittoria amara, nata da un patto.","text":"La parola pronunciata spezza il giuramento della Sfinge: cade, e con lei un pezzo del miraggio. Una vittoria amara, nata da un patto.","m":125},"eBest":{"t":"end","win":true,"title":"Onestà nel deserto","x":"La Sfinge cade senza rancore e dona al gruppo la sua ultima lacrima d’ambra. Il deserto, per un istante, fiorisce.","text":"La Sfinge cade senza rancore e dona al gruppo la sua ultima lacrima d’ambra. Il deserto, per un istante, fiorisce.","m":140},"eGood":{"t":"end","win":true,"title":"La via delle dune","x":"La guida vi riporta indietro dalla via più breve. Il deserto vi lascia andare.","text":"La guida vi riporta indietro dalla via più breve. Il deserto vi lascia andare.","m":115},"eOk":{"t":"end","win":true,"title":"Fuga dalle dune","x":"La Sfinge crolla in una pioggia di sabbia. Uscite assetati e stremati, ma liberi.","text":"La Sfinge crolla in una pioggia di sabbia. Uscite assetati e stremati, ma liberi.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il mercante non scherza: il suo bastone è un artefatto che trasforma il gruppo in sabbia.","text":"Il mercante non scherza: il suo bastone è un artefatto che trasforma il gruppo in sabbia.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La risposta sbagliata è mortale: la Sfinge vi divora in un solo boccone.","text":"La risposta sbagliata è mortale: la Sfinge vi divora in un solo boccone.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Le dune si chiudono sopra di voi: la spedizione è fallita.","text":"Le dune si chiudono sopra di voi: la spedizione è fallita.","m":100},"_flags":{"patto":"Patto stretto","onore":"Parola d’onore","alleato":"Alleato liberato","oscuro":"Patto onorato","puro":"Fiducia ripagata"}}$j$::jsonb),
 (33, $j${"_start":"s1","s1":{"t":"scene","n":"Prima prova","x":"La prima prova: un banditore annuncia le regole dalla balconata. «Il Campione indossa un’armatura invincibile… ma un tempo è caduto una volta, sul fianco sinistro». In arena, uno scudo, una lancia e un pugnale.","o":[{"l":"Ascoltare con attenzione il banditore e memorizzare il fianco sinistro","r":"Un’informazione preziosa: il Campione ha un punto debole sul fianco sinistro.","to":"f1","fx":{"flag":"indizio","pow":5},"id":"a"},{"l":"Prendere lo scudo e ripararsi dalla folla","r":"Lo scudo vi protegge dai proiettili e vi dà respiro.","to":"f1","fx":{"hp":15},"id":"b"},{"l":"Gettare la lancia verso il banditore","r":"","to":"eF1","id":"c"}]},"f1":{"t":"fight","e":"Gladiatori Demoniaci","em":"⚔️","m":1.0,"k":"n","w":"s2","l":"eDef"},"s2":{"t":"scene","n":"Seconda prova","x":"La seconda prova: una belva è stata liberata nel centro dell’arena. Da un lato un cancello aperto, dall’altro una fossa di spuntoni, e al centro un anello di fuoco.","o":[{"l":"Saltare nella fossa di spuntoni","r":"","to":"eF2","id":"a"},{"l":"Farla inseguire e schivarla con calma","r":"La belva si stanca e si calma, ma il sudore vi gela.","to":"f2","fx":{"hp":-5},"id":"b"},{"l":"Sfidare la belva nell’anello di fuoco","r":"La folla esulta: il fuoco vi rende più carichi, anche se vi brucia.","to":"f2","fx":{"pow":12,"hp":-20},"id":"c"}]},"f2":{"t":"fight","e":"Belva dell’Arena","em":"🦁","m":1.15,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"La prova finale","x":"La prova finale. Il Campione Infernale entra tra gli applausi. L’armatura è completa, ma il fianco sinistro mostra una vecchia crepa. A terra, quattro armi: spada, ascia, lancia, martello.","o":[{"l":"Rifiutare il combattimento e uscire dall’arena","r":"","to":"eF3","id":"a"},{"l":"Scegliere la lancia e mirare al fianco sinistro","r":"La lancia trafigge la crepa: il Campione grida per la prima volta in mille anni.","to":"fb","fx":{"pow":35,"flag":"punto"},"id":"b"},{"l":"Impugnare l’ascia e colpire l’elmo","r":"L’elmo è la parte più forte dell’armatura: l’ascia rimbalza.","to":"fb","fx":{"pow":-25},"id":"c"},{"l":"Impugnare il martello e colpire il petto","r":"Il petto non cede: il martello vibra, e voi con lui.","to":"fb","fx":{"pow":-25},"id":"d"}],"h":{"if":"indizio","t":"Il banditore lo aveva detto: il Campione è vulnerabile sul fianco sinistro. Una lancia, lunga e precisa, potrebbe colpire in quel punto."}},"fb":{"t":"fight","e":"Campione Infernale","em":"🔱","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["punto","indizio"],"to":"eBest"},{"if":["punto"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il Campione cade","x":"Il fianco sinistro cede e il Campione crolla per la prima volta. La folla, muta, si inchina: siete voi i nuovi campioni.","text":"Il fianco sinistro cede e il Campione crolla per la prima volta. La folla, muta, si inchina: siete voi i nuovi campioni.","m":140},"eGood":{"t":"end","win":true,"title":"Un colpo fortunato","x":"Un solo colpo nel punto giusto ribalta l’incontro. La folla vi acclama, anche se non sa perché.","text":"Un solo colpo nel punto giusto ribalta l’incontro. La folla vi acclama, anche se non sa perché.","m":115},"eOk":{"t":"end","win":true,"title":"Il verdetto della folla","x":"Il Campione si ritira ferito. La folla è divisa, ma la vittoria è vostra.","text":"Il Campione si ritira ferito. La folla è divisa, ma la vittoria è vostra.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La lancia colpisce la balconata e scatena la furia della folla: un nugolo di demoni vi travolge.","text":"La lancia colpisce la balconata e scatena la furia della folla: un nugolo di demoni vi travolge.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La fossa di spuntoni è profonda e senza uscita: la spedizione finisce prima di cominciare.","text":"La fossa di spuntoni è profonda e senza uscita: la spedizione finisce prima di cominciare.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il patto con l’arena non ammette rifiuti: il cancello si chiude e vi imprigiona per sempre.","text":"Il patto con l’arena non ammette rifiuti: il cancello si chiude e vi imprigiona per sempre.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Campione vi umilia davanti alla folla: l’arena si chiude su di voi. Spedizione fallita.","text":"Il Campione vi umilia davanti alla folla: l’arena si chiude su di voi. Spedizione fallita.","m":100},"_flags":{"indizio":"Indizio decifrato","punto":"Punto debole colpito"}}$j$::jsonb),
 (34, $j${"_start":"s1","s1":{"t":"scene","n":"Ingresso","x":"All’ingresso del bosco due sentieri: uno cosparso di petali profumati, l’altro coperto di foglie secche. Un coro sussurra: «Seguite i fiori, seguite i fiori…». Sugli alberi, nastri neri.","o":[{"l":"Ignorare i fiori e seguire il sentiero di foglie secche","r":"Il sussurro si spegne: il gruppo non cade nell’incanto e nota una foglia d’argento sul tronco più vecchio.","to":"s2","fx":{"pow":8,"flag":"indizio"},"id":"a"},{"l":"Seguire i petali, ma tappandosi le orecchie","r":"Il canto vi sfiora la mente e vi stanca, ma la via è breve.","to":"f1e","fx":{"hp":-20,"pow":6},"id":"b"},{"l":"Prendere un nastro nero da un albero","r":"","to":"eF1","id":"c"}]},"s2":{"t":"scene","n":"La chiave","x":"Nella radura la foglia d’argento brilla: «Dove nasce la luce senza sole, nasce la protezione». Tre alberi: uno con frutti rossi, uno con funghi luminosi, uno con una cavità piena di lucciole.","o":[{"l":"Ignorare gli alberi e proseguire","r":"Senza protezione, proseguite: la foresta vi osserva.","to":"f1","fx":{"hp":-12},"id":"a"},{"l":"Mangiare i frutti rossi dell’albero","r":"","to":"eF2","id":"b"},{"l":"Cercare nella cavità piena di lucciole","r":"Tra le lucciole trovate la Foglia d’Argento, l’unico antidoto contro il canto della regina.","to":"f1w","fx":{"pow":8,"flag":"key"},"id":"c"}]},"f1w":{"t":"fight","e":"Folletti Dispettosi","em":"🧝","m":0.85,"k":"n","w":"s3","l":"eDef"},"f1":{"t":"fight","e":"Folletti Dispettosi","em":"🧝","m":1.0,"k":"n","w":"s3","l":"eDef"},"f1e":{"t":"fight","e":"Cervo di Spine","em":"🦌","m":1.3,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Il bivio finale","x":"Il trono della Regina Fata Oscura: un cerchio di funghi giganti nel quale la regina danza lenta. In mezzo, un laghetto di luce, e dietro di lei un albero vecchissimo.","o":[{"l":"Immergersi nel laghetto di luce per curarsi","r":"La luce cura, ma l’acqua attira l’attenzione della regina e la rende più forte.","to":"fb","fx":{"hp":35,"pow":-12},"id":"a"},{"l":"Usare la Foglia d’Argento per proteggere i sensi del gruppo","r":"La foglia protegge dal canto: la regina, furiosa, perde il controllo sulla vostra mente.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"b"},{"l":"Tagliare un ramo dell’albero vecchissimo","r":"","to":"eF3","id":"c"},{"l":"Avanzare dritti verso la regina","r":"La regina sorride: vi stava aspettando.","to":"fb","id":"d"}]},"fb":{"t":"fight","e":"Regina Fata Oscura","em":"🧚‍♀️","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il nome ritrovato","x":"La regina perde il suo potere sui nomi e cade in ginocchio. Il bosco canta una canzone nuova, per voi.","text":"La regina perde il suo potere sui nomi e cade in ginocchio. Il bosco canta una canzone nuova, per voi.","m":140},"eGood":{"t":"end","win":true,"title":"Il canto si spegne","x":"La regina cade e le fate tornano a ridere piano. Il bosco vi lascia andare con una corona di foglie.","text":"La regina cade e le fate tornano a ridere piano. Il bosco vi lascia andare con una corona di foglie.","m":115},"eOk":{"t":"end","win":true,"title":"Fuga tra i rami","x":"La regina si dissolve in una nube di petali neri. Uscite storditi dal canto, ma con il vostro nome intero.","text":"La regina si dissolve in una nube di petali neri. Uscite storditi dal canto, ma con il vostro nome intero.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il nastro nero è un segno di cattura: il bosco si richiude su di voi e nessuno vi ritrova.","text":"Il nastro nero è un segno di cattura: il bosco si richiude su di voi e nessuno vi ritrova.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"I frutti rossi cancellano la memoria: il gruppo dimentica chi è e si perde nel bosco per sempre.","text":"I frutti rossi cancellano la memoria: il gruppo dimentica chi è e si perde nel bosco per sempre.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il ramo è la spina dorsale della regina: ella ride, e il bosco intero si abbatte su di voi.","text":"Il ramo è la spina dorsale della regina: ella ride, e il bosco intero si abbatte su di voi.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il canto della regina vi domina: il gruppo diventa parte del bosco. Spedizione fallita.","text":"Il canto della regina vi domina: il gruppo diventa parte del bosco. Spedizione fallita.","m":100},"_flags":{"indizio":"Indizio","key":"Foglia d’Argento","sigillo":"Sigillo spezzato"}}$j$::jsonb),
 (35, $j${"_start":"s1","s1":{"t":"scene","n":"Due strade","x":"La fortezza ha due ingressi. Il portone principale è sbarrato da ingranaggi che girano a fatica. Un condotto di manutenzione, aperto e più stretto, scende sotto le mura. Una targa dice: «L’officina conosce chi la serve».","o":[{"l":"Forzare il portone principale e sfidare le sentinelle","r":"Il portone cede con un gemito: le sentinelle vi puntano.","to":"f1","fx":{"flag":"forza"},"id":"a"},{"l":"Scendere nel condotto di manutenzione","r":"L’aria odora di olio e di ruggine: il condotto porta in profondità.","to":"sp","id":"b"},{"l":"Tirare la grossa leva rossa accanto al portone","r":"","to":"eF1","id":"c"}]},"f1":{"t":"fight","e":"Sentinelle di Ferro","em":"🔩","m":1.1,"k":"n","w":"f2","l":"eDef"},"f2":{"t":"fight","e":"Ragno Meccanico","em":"🕷️","m":1.2,"k":"e","w":"ss","l":"eDef"},"ss":{"t":"scene","n":"Il bottino","x":"Nell’armeria distrutta restano un cannone portatile ancora carico, una cassetta di pezzi di ricambio e una grossa leva dorata appesa al muro.","o":[{"l":"Tirare la leva dorata appesa al muro","r":"","to":"eF3","id":"a"},{"l":"Caricare il cannone portatile","r":"Il cannone aumenta la potenza di fuoco del gruppo.","to":"s3","fx":{"pow":15},"id":"b"},{"l":"Usare i pezzi di ricambio per rattoppare l’equipaggiamento","r":"Con gli attrezzi giusti riparate armature e ferite.","to":"s3","fx":{"hp":30},"id":"c"}]},"sp":{"t":"scene","n":"Il passaggio nascosto","x":"Il condotto sbocca in un’officina buia. Tre cassetti nel banco: uno con ingranaggi neri, uno con un martello bruciato, uno con una chiave a stella lucida. Un biglietto: «Per aprire le viscere della bestia serve la chiave che nessuno ha toccato».","o":[{"l":"Prendere gli ingranaggi neri","r":"Gli ingranaggi sono trappole: scatta un allarme e un ragno d’acciaio vi insegue.","to":"f3","fx":{"hp":-25},"id":"a"},{"l":"Prendere il martello bruciato","r":"","to":"eF2","id":"b"},{"l":"Prendere la chiave a stella lucida","r":"La Chiave a Stella è intatta: potrà aprire il pannello segreto del Gigante.","to":"s3","fx":{"hp":10,"flag":"key"},"id":"c"}]},"f3":{"t":"fight","e":"Sentinelle di Ferro","em":"🔩","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al covo","x":"La sala del Gigante d’Ingranaggi: un colosso immobile al centro. Sul suo dorso un pannello chiuso da un incavo a stella. Le sue ruote girano piano.","o":[{"l":"Attaccare frontalmente il Gigante","r":"Il Gigante si anima con un fragore di ingranaggi.","to":"fb","id":"a"},{"l":"Fermarsi a riparare le ferite con l’olio caldo","r":"L’olio cura, ma il Gigante si carica a ogni secondo che perdete.","to":"fb","fx":{"hp":25,"pow":-8},"id":"b"},{"l":"Usare la Chiave a Stella sul pannello del dorso","r":"Il pannello si apre: una leva d’emergenza rallenta tutti i suoi movimenti.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"}]},"fb":{"t":"fight","e":"Gigante d’Ingranaggi","em":"🤖","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["forza"],"to":"eGood"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Spegnimento d’emergenza","x":"Il Gigante si ferma a metà movimento, le ruote che girano a vuoto. La fortezza spegne una luce dopo l’altra.","text":"Il Gigante si ferma a metà movimento, le ruote che girano a vuoto. La fortezza spegne una luce dopo l’altra.","m":140},"eGood":{"t":"end","win":true,"title":"Meccanismi in frantumi","x":"Il Gigante cade in pezzi, come un castello di ruote. L’officina, finalmente, riposa.","text":"Il Gigante cade in pezzi, come un castello di ruote. L’officina, finalmente, riposa.","m":115},"eOk":{"t":"end","win":true,"title":"Riparazione di fortuna","x":"Il Gigante si ferma con un ultimo cigolio. Uscite stanchi, con la mente piena di ingranaggi.","text":"Il Gigante si ferma con un ultimo cigolio. Uscite stanchi, con la mente piena di ingranaggi.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La leva rossa è un allarme: le sentinelle si sollevano a centinaia e vi travolgono.","text":"La leva rossa è un allarme: le sentinelle si sollevano a centinaia e vi travolgono.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il martello bruciato è un detonatore: l’officina esplode.","text":"Il martello bruciato è un detonatore: l’officina esplode.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"La leva dorata apre una botola sotto i vostri piedi: il gruppo precipita nel forno della fortezza.","text":"La leva dorata apre una botola sotto i vostri piedi: il gruppo precipita nel forno della fortezza.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Gli ingranaggi del Gigante vi stritolano: la fortezza non ha nemmeno bisogno di riparare i danni. Spedizione fallita.","text":"Gli ingranaggi del Gigante vi stritolano: la fortezza non ha nemmeno bisogno di riparare i danni. Spedizione fallita.","m":100},"_flags":{"forza":"Via dei mostri","key":"Chiave a Stella","sigillo":"Accesso segreto"}}$j$::jsonb),
 (36, $j${"_start":"s1","s1":{"t":"scene","n":"Un incontro","x":"Sul molo un vecchio marinaio trasparente srotola una mappa: «Vi porto fino al Capitano, ma il viaggio costa. Pagate con un po’ del vostro sangue, e la nave vi lascerà passare».","o":[{"l":"Rifiutare e cercare da soli un passaggio","r":"Il marinaio sorride storto: «Gli onesti arrivano sempre dove non vogliono». Vi lascia andare.","to":"s2","fx":{"pow":6,"flag":"onore"},"id":"a"},{"l":"Accettare il patto: pagare con un po’ di sangue","r":"Una goccia di sangue basta a cementare il patto. Il gruppo sente un freddo improvviso.","to":"s2","fx":{"hp":-30,"flag":"patto"},"id":"b"},{"l":"Strappare la mappa di mano al marinaio","r":"","to":"f0","id":"c"}]},"f0":{"t":"fight","e":"Quartiermastro Spettrale","em":"👻","m":1.9,"k":"e","w":"s2","l":"eDef","wfx":{"pow":12}},"s2":{"t":"scene","n":"Il santuario","x":"Nella stiva della nave fantasma un mozzo è legato a un albero di trinchetto. Su un barile, un forziere di monete brilla senza guardie. Il ponte scricchiola sopra di voi.","o":[{"l":"Accendere la lanterna al centro della stiva","r":"","to":"eF1","id":"a"},{"l":"Ignorare e proseguire","r":"Il silenzio della stiva vi accompagna fino alla scala.","to":"f1","id":"b"},{"l":"Liberare il mozzo legato","r":"Il mozzo, ancora vivo, giura che vi aiuterà con il Capitano. Il lavoro vi stanca un po’.","to":"f1","fx":{"hp":-10,"pow":15,"flag":"alleato"},"id":"c"},{"l":"Prendere le monete dal forziere","r":"Le monete sono pesanti ma vi riempiono di baldanza. Una risata lontana vi segue.","to":"f1","fx":{"pow":10},"id":"d"}]},"f1":{"t":"fight","e":"Marinai Scheletro","em":"💀","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al signore del luogo","x":"Il Capitan Fantasma vi attende sul cassero, il timone tra le mani scheletriche. Le nuvole si squarciano e la luna illumina la scena.","o":[{"l":"Presentarsi con la propria parola e a mani vuote","r":"Il Capitano rispetta chi non ha mentito e abbassa la lama, in attesa di un duello alla pari.","to":"fb","fx":{"pow":20,"flag":"puro"},"only":["onore"],"id":"a"},{"l":"Salire sul cassero e sfidarlo in duello","r":"Il Capitano sguaina la lama.","to":"fb","id":"b"},{"l":"Far parlare il mozzo: conosce il punto debole del timone","r":"Il mozzo grida una parola, e il timone gira da solo: il Capitano perde l’equilibrio.","to":"fb","fx":{"pow":20},"only":["alleato"],"id":"c"},{"l":"Spezzare il timone con un colpo","r":"","to":"eF2","id":"d"},{"l":"Mantenere il patto: consegnare la mappa al Capitano","r":"Il Capitano la afferra con avidità e, per un istante, abbassa la guardia: il vostro attacco lo coglie scoperto.","to":"fb","fx":{"pow":35,"flag":"oscuro"},"only":["patto"],"id":"e"},{"l":"Spezzare il patto: bruciare la mappa davanti a lui","r":"Il Capitano ulula di rabbia: il patto infranto lo rende furibondo.","to":"fb","fx":{"pow":-20,"hp":-15},"only":["patto"],"id":"f"}]},"fb":{"t":"fight","e":"Capitan Fantasma","em":"☠️","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["oscuro"],"to":"eDark"},{"if":["puro"],"to":"eBest"},{"if":["alleato"],"to":"eGood"}],"d":"eOk"},"eDark":{"t":"end","win":true,"title":"Il debito pagato","x":"Il Capitano cade stringendo la mappa. Il patto è compiuto e una parte della ciurma si unisce a voi. Vittoria amara, ma potente.","text":"Il Capitano cade stringendo la mappa. Il patto è compiuto e una parte della ciurma si unisce a voi. Vittoria amara, ma potente.","m":125},"eBest":{"t":"end","win":true,"title":"La parola d’onore","x":"Il Capitano, commosso dalla vostra lealtà, svanisce con un sorriso. La nebbia si alza per la prima volta in secoli.","text":"Il Capitano, commosso dalla vostra lealtà, svanisce con un sorriso. La nebbia si alza per la prima volta in secoli.","m":140},"eGood":{"t":"end","win":true,"title":"La ciurma liberata","x":"Il mozzo e i marinai liberati salutano il vostro ritorno. L’isola, dopo secoli, vede il sole.","text":"Il mozzo e i marinai liberati salutano il vostro ritorno. L’isola, dopo secoli, vede il sole.","m":115},"eOk":{"t":"end","win":true,"title":"A remi, nella nebbia","x":"Il Capitano cade, ma la nave resta a pezzi. Remate via con le ultime forze, certi di aver vinto.","text":"Il Capitano cade, ma la nave resta a pezzi. Remate via con le ultime forze, certi di aver vinto.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La lanterna è un faro maledetto: la nave si anima e vi trascina negli abissi.","text":"La lanterna è un faro maledetto: la nave si anima e vi trascina negli abissi.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il timone spezzato fa girare la nave su sé stessa: il gruppo cade in mare tra le fauci dei mostri.","text":"Il timone spezzato fa girare la nave su sé stessa: il gruppo cade in mare tra le fauci dei mostri.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Capitano comanda alla sua ciurma «Ormeggiare»: la spedizione si ferma, per sempre, sul fondale.","text":"Il Capitano comanda alla sua ciurma «Ormeggiare»: la spedizione si ferma, per sempre, sul fondale.","m":100},"_flags":{"patto":"Patto stretto","onore":"Parola d’onore","alleato":"Alleato liberato","oscuro":"Patto onorato","puro":"Fiducia ripagata"}}$j$::jsonb),
 (37, $j${"_start":"s1","s1":{"t":"scene","n":"Prima prova","x":"La prima prova è un lungo corridoio di specchi neri. Una voce dice: «Il Sovrano non teme il fuoco né l’acciaio. Teme solo ciò che ha nascosto in fondo al suo specchio». Davanti a voi, tre specchi: uno rotto, uno appannato, uno perfetto.","o":[{"l":"Fissare lo specchio appannato e pulirlo con la manica","r":"Dietro l’appannatura appare un simbolo: un’aquila d’argento. Probabilmente conta.","to":"f1","fx":{"flag":"indizio","pow":5},"id":"a"},{"l":"Rompere lo specchio perfetto","r":"","to":"eF1","id":"b"},{"l":"Prendere una pozione dalla nicchia accanto allo specchio rotto","r":"La pozione restituisce un po’ di forze.","to":"f1","fx":{"hp":15},"id":"c"}]},"f1":{"t":"fight","e":"Imp Infuocati","em":"😈","m":1.0,"k":"n","w":"s2","l":"eDef"},"s2":{"t":"scene","n":"Seconda prova","x":"La seconda prova: una sala di brace. Davanti a voi, un ponte di lava con corde tese e, al centro, un demone giudice con una bilancia nera.","o":[{"l":"Gettare il piatto della bilancia nella lava","r":"","to":"eF2","id":"a"},{"l":"Attraversare il ponte piano, evitando le corde","r":"Cammino lento e calcolato, qualche scintilla e nessun danno vero.","to":"f2","fx":{"hp":-5},"id":"b"},{"l":"Sfidare il demone giudice in duello leale","r":"Il demone si infuria, ma voi combattete con furia: ne uscite ammaccati ma carichi di ardore.","to":"f2","fx":{"pow":12,"hp":-20},"id":"c"}]},"f2":{"t":"fight","e":"Demone Giudice","em":"⚖️","m":1.15,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"La prova finale","x":"Il Sovrano siede sul trono di brace, circondato da specchi neri. Davanti a lui un tavolo con quattro oggetti: un’aquila d’argento, una spada di brace, un calice di ossidiana, una corona di spine.","o":[{"l":"Offrirgli il calice di ossidiana","r":"Il calice è suo: lo beve e si rafforza.","to":"fb","fx":{"pow":-25},"id":"a"},{"l":"Incoronarlo con la corona di spine","r":"La corona è il simbolo del suo potere: il Sovrano ride e vi colpisce.","to":"fb","fx":{"pow":-25},"id":"b"},{"l":"Sfidarlo toccando la spada di brace","r":"","to":"eF3","id":"c"},{"l":"Mostrare l’aquila d’argento al Sovrano","r":"Il Sovrano urla e si ritrae: l’aquila era il simbolo del suo nemico di sempre.","to":"fb","fx":{"pow":35,"flag":"punto"},"id":"d"}],"h":{"if":"indizio","t":"Ricordate lo specchio appannato: un’aquila d’argento. È l’unica cosa che il Sovrano teme."}},"fb":{"t":"fight","e":"Arcidemone Sovrano","em":"👿","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["punto","indizio"],"to":"eBest"},{"if":["punto"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il simbolo temuto","x":"Il Sovrano cade in ginocchio davanti all’aquila. Gli specchi neri si crepano uno dopo l’altro e la sala si spegne.","text":"Il Sovrano cade in ginocchio davanti all’aquila. Gli specchi neri si crepano uno dopo l’altro e la sala si spegne.","m":140},"eGood":{"t":"end","win":true,"title":"Il trono è vuoto","x":"Il Sovrano crolla e i demoni si inchinano all’uscita del vincitore. Il palazzo smette di bruciare.","text":"Il Sovrano crolla e i demoni si inchinano all’uscita del vincitore. Il palazzo smette di bruciare.","m":115},"eOk":{"t":"end","win":true,"title":"Brace e cenere","x":"Il Sovrano si dissolve in cenere mentre voi quasi crollate. La sala tace.","text":"Il Sovrano si dissolve in cenere mentre voi quasi crollate. La sala tace.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Lo specchio perfetto si infrange e una lama di vetro nero vi trapassa tutti.","text":"Lo specchio perfetto si infrange e una lama di vetro nero vi trapassa tutti.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La lava risale lungo le corde e vi avvolge: il demone giudice ride mentre bruciate.","text":"La lava risale lungo le corde e vi avvolge: il demone giudice ride mentre bruciate.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"La spada è il cuore del Sovrano: lui sorride e vi consuma in un lampo.","text":"La spada è il cuore del Sovrano: lui sorride e vi consuma in un lampo.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Sovrano vi mostra le vostre paure più profonde e vi sconfigge prima del primo colpo. Spedizione fallita.","text":"Il Sovrano vi mostra le vostre paure più profonde e vi sconfigge prima del primo colpo. Spedizione fallita.","m":100},"_flags":{"indizio":"Indizio decifrato","punto":"Punto debole colpito"}}$j$::jsonb),
 (38, $j${"_start":"s1","s1":{"t":"scene","n":"Ingresso","x":"Alle porte del santuario, una scalinata di marmo nero porta a un portico. I gradini sono incisi con fasi lunari: crescente, piena, calante, nuova. Una scritta dice: «Sali come sale la luna».","o":[{"l":"Salire i gradini in ordine, dalla luna nuova alla piena","r":"I gradini si illuminano a uno a uno. Un’incisione sul portico indica una via.","to":"s2","fx":{"pow":8,"flag":"indizio"},"id":"a"},{"l":"Calpestare la fase nuova per ultima","r":"","to":"eF1","id":"b"},{"l":"Salire di corsa saltando i gradini","r":"Il marmo gela i piedi e una sacerdotessa si accorge della vostra fretta.","to":"f1e","fx":{"hp":-20,"pow":6},"id":"c"}]},"s2":{"t":"scene","n":"La chiave","x":"L’incisione recita: «La pietra del ricordo dorme dove l’acqua è ferma e scura». In fondo al portico, tre vasche: una piena d’acqua agitata, una di acqua ferma e nera, una completamente prosciugata.","o":[{"l":"Bere dalla vasca d’acqua agitata","r":"","to":"eF2","id":"a"},{"l":"Passare oltre senza toccare l’acqua","r":"Il silenzio del santuario vi accompagna.","to":"f1","fx":{"hp":-12},"id":"b"},{"l":"Immergere la mano nella vasca d’acqua ferma e nera","r":"Sul fondo trovate la Pietra Lunare, fredda e luminosa. Il suo bagliore attira un lupo d’argento.","to":"f1w","fx":{"pow":8,"flag":"key"},"id":"c"}]},"f1w":{"t":"fight","e":"Sacerdotesse d’Ombra","em":"🕯️","m":0.85,"k":"n","w":"s3","l":"eDef"},"f1":{"t":"fight","e":"Sacerdotesse d’Ombra","em":"🕯️","m":1.0,"k":"n","w":"s3","l":"eDef"},"f1e":{"t":"fight","e":"Lupo d’Argento","em":"🐺","m":1.3,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Il bivio finale","x":"La Dea della Luna Nera siede su un trono di argento e notte. Dietro di lei, un grande specchio d’acqua riflette la luna. A destra, un’arpa d’ossidiana. A sinistra, un braciere spento.","o":[{"l":"Sfidare la Dea senza altri aiuti","r":"La Dea vi guarda con occhi color argento e lascia che la sfida cominci.","to":"fb","id":"a"},{"l":"Sostare accanto allo specchio d’acqua per guarire","r":"L’acqua cura, ma la Dea sente il vostro riposo e si rinvigorisce.","to":"fb","fx":{"hp":35,"pow":-12},"id":"b"},{"l":"Mostrare la Pietra Lunare alla Dea","r":"La Dea riconosce la sua stessa luce nella pietra: la sua forza oscilla come una marea in ritirata.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"},{"l":"Suonare l’arpa d’ossidiana","r":"","to":"eF3","id":"d"}]},"fb":{"t":"fight","e":"Dea della Luna Nera","em":"🌑","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il ritorno della luce","x":"La Pietra Lunare risveglia la Dea dal suo torpore: si ritira nel firmamento. Per la prima volta, il santuario vede l’alba.","text":"La Pietra Lunare risveglia la Dea dal suo torpore: si ritira nel firmamento. Per la prima volta, il santuario vede l’alba.","m":140},"eGood":{"t":"end","win":true,"title":"La luna si ritira","x":"La Dea cade e le maree si placano. Il santuario respira piano.","text":"La Dea cade e le maree si placano. Il santuario respira piano.","m":115},"eOk":{"t":"end","win":true,"title":"Alba sul filo","x":"La Dea si ritira nell’ombra. Uscite ammaccati, ma vivi, con la prima luce.","text":"La Dea si ritira nell’ombra. Uscite ammaccati, ma vivi, con la prima luce.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"L’ultima fase si chiude come una trappola: i gradini si ribaltano e il gruppo precipita nel vuoto.","text":"L’ultima fase si chiude come una trappola: i gradini si ribaltano e il gruppo precipita nel vuoto.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’acqua agitata è una pozione di follia: il gruppo si perde nei propri ricordi.","text":"L’acqua agitata è una pozione di follia: il gruppo si perde nei propri ricordi.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"L’arpa suona da sola, e la Dea canta con lei: un coro funebre che spegne ogni forza.","text":"L’arpa suona da sola, e la Dea canta con lei: un coro funebre che spegne ogni forza.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"La Dea vi accoglie nel suo abbraccio freddo: la spedizione si spegne, come una luna calante.","text":"La Dea vi accoglie nel suo abbraccio freddo: la spedizione si spegne, come una luna calante.","m":100},"_flags":{"indizio":"Indizio","key":"Pietra Lunare","sigillo":"Sigillo spezzato"}}$j$::jsonb),
 (39, $j${"_start":"s1","s1":{"t":"scene","n":"Due strade","x":"Il villaggio si apre su due strade. La via maestra è larga e lastricata, con ninja che vi osservano dai tetti. Un vicolo stretto tra due case di carta porta verso un giardino nascosto. Un cartello dice: «Chi cammina nell’ombra non è visto».","o":[{"l":"Attraversare la piazza principale di corsa","r":"","to":"eF1","id":"a"},{"l":"Percorrere la via maestra e sfidare i ninja","r":"Le ombre sui tetti si muovono: lo scontro è inevitabile.","to":"f1","fx":{"flag":"forza"},"id":"b"},{"l":"Imboccare il vicolo e scivolare nell’ombra","r":"Il vicolo è silenzioso e vi nasconde bene.","to":"sp","id":"c"}]},"f1":{"t":"fight","e":"Ninja Apprendisti","em":"🥷","m":1.1,"k":"n","w":"f2","l":"eDef"},"f2":{"t":"fight","e":"Shinobi Veterani","em":"🗡️","m":1.2,"k":"e","w":"ss","l":"eDef"},"ss":{"t":"scene","n":"Il bottino","x":"Tra i ninja caduti: una katana dal filo perfetto, una tisana fumante in una tazza e un rotolo con scritto «PRIVATO».","o":[{"l":"Afferrare la katana dal filo perfetto","r":"La lama è perfetta: ogni colpo del gruppo è più mortale.","to":"s3","fx":{"pow":15},"id":"a"},{"l":"Bere la tisana fumante","r":"La tisana è curativa: le ferite si calmano.","to":"s3","fx":{"hp":30},"id":"b"},{"l":"Aprire il rotolo con scritto «PRIVATO»","r":"","to":"eF3","id":"c"}]},"sp":{"t":"scene","n":"Il passaggio nascosto","x":"Nel giardino nascosto, tre lanterne di carta: una rossa, una bianca, una nera. Su un sasso è inciso un haiku: «Il maestro dorme dove la luce non è luce».","o":[{"l":"Aprire la lanterna nera","r":"Dentro c’è la Pergamena del Sigillo, che può spegnere le ombre del Maestro.","to":"s3","fx":{"hp":10,"flag":"key"},"id":"a"},{"l":"Aprire la lanterna bianca","r":"","to":"eF2","id":"b"},{"l":"Aprire la lanterna rossa","r":"Dalla lanterna escono degli shinobi di guardia: è un’imboscata.","to":"f3","fx":{"hp":-25},"id":"c"}]},"f3":{"t":"fight","e":"Ninja Apprendisti","em":"🥷","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al covo","x":"Il dojo del Maestro delle Ombre. Le pareti sono di carta, e sul pavimento ci sono tatami disposti in uno schema preciso. Al centro, un’ombra sembra respirare.","o":[{"l":"Entrare nel dojo e sfidare il Maestro","r":"Il Maestro compare e scompare tra le ombre.","to":"fb","id":"a"},{"l":"Sedersi in meditazione per recuperare forze","r":"La calma cura, ma il Maestro sfrutta il silenzio per prepararsi.","to":"fb","fx":{"hp":25,"pow":-8},"id":"b"},{"l":"Srotolare la Pergamena del Sigillo sul tatami centrale","r":"Le ombre del Maestro si bloccano: non può più sparire.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"}]},"fb":{"t":"fight","e":"Maestro delle Ombre","em":"🌑","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["forza"],"to":"eGood"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Nessuna ombra","x":"Con le ombre bloccate, il Maestro non può più fuggire: si inchina e cade. Il villaggio si illumina per la prima volta.","text":"Con le ombre bloccate, il Maestro non può più fuggire: si inchina e cade. Il villaggio si illumina per la prima volta.","m":140},"eGood":{"t":"end","win":true,"title":"La via del guerriero","x":"Il Maestro cade con onore. I ninja del villaggio vi salutano dai tetti, in silenzio.","text":"Il Maestro cade con onore. I ninja del villaggio vi salutano dai tetti, in silenzio.","m":115},"eOk":{"t":"end","win":true,"title":"L’ultimo colpo","x":"Il Maestro cade, ma voi vi reggete a stento. Il villaggio vi saluta con un inchino.","text":"Il Maestro cade, ma voi vi reggete a stento. Il villaggio vi saluta con un inchino.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La piazza è un campo minato di shuriken: il gruppo cade tra mille lame.","text":"La piazza è un campo minato di shuriken: il gruppo cade tra mille lame.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La lanterna bianca sprigiona un gas paralizzante: i ninja fanno il resto.","text":"La lanterna bianca sprigiona un gas paralizzante: i ninja fanno il resto.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il rotolo è una trappola: la casa di carta si richiude su di voi.","text":"Il rotolo è una trappola: la casa di carta si richiude su di voi.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Maestro attacca dove non guardate: il gruppo cade senza nemmeno vederlo. Spedizione fallita.","text":"Il Maestro attacca dove non guardate: il gruppo cade senza nemmeno vederlo. Spedizione fallita.","m":100},"_flags":{"forza":"Via dei mostri","key":"Pergamena del Sigillo","sigillo":"Accesso segreto"}}$j$::jsonb),
 (40, $j${"_start":"s1","s1":{"t":"scene","n":"Un incontro","x":"Alla porta della cittadella, un anziano samurai vi ferma: «Vi lascio passare se giurate di consegnare allo Shogun un pezzo del vostro onore: la metà delle vostre forze. Il patto va onorato a fine strada».","o":[{"l":"Sfidare l’anziano a duello","r":"","to":"f0","id":"a"},{"l":"Accettare il giuramento: offrire metà delle forze","r":"La sua spada sfiora la vostra spalla: sentite scivolare via parte del vostro vigore, ma il portone si apre.","to":"s2","fx":{"hp":-30,"flag":"patto"},"id":"b"},{"l":"Rifiutare cortesemente e chiedere solo il passaggio","r":"L’anziano si inchina: «Un rifiuto onesto vale più di un giuramento falso». Vi apre il portone.","to":"s2","fx":{"pow":6,"flag":"onore"},"id":"c"}]},"f0":{"t":"fight","e":"Ronin Furioso","em":"🥷","m":1.9,"k":"e","w":"s2","l":"eDef","wfx":{"pow":12}},"s2":{"t":"scene","n":"Il santuario","x":"Nel giardino di sabbia, un giovane samurai legato a un ciliegio mormora: «Pietà». Su un altare, un’urna d’oro con il sigillo dello Shogun. Dietro, un gong gigante.","o":[{"l":"Prendere l’urna con il sigillo","r":"Il sigillo è pesante, ma vi riempie di baldanza. Qualcuno, dietro i muri, ha sentito il rumore.","to":"f1","fx":{"pow":10},"id":"a"},{"l":"Proseguire senza fermarvi","r":"Il giardino scivola via, calmo e silenzioso.","to":"f1","id":"b"},{"l":"Liberare il giovane samurai","r":"Il samurai giura fedeltà: sa come entrare nel dojo dello Shogun. Vi costa un po’ di fiato.","to":"f1","fx":{"hp":-10,"pow":15,"flag":"alleato"},"id":"c"},{"l":"Suonare il gong gigante","r":"","to":"eF1","id":"d"}]},"f1":{"t":"fight","e":"Samurai di Guardia","em":"⚔️","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al signore del luogo","x":"Lo Shogun Corazzato siede su un trono di legno nero, con la spada sulle ginocchia. Al suo fianco due statue di guardia. Il dojo è silenzioso.","o":[{"l":"Toccare la spada appoggiata sul trono","r":"","to":"eF2","id":"a"},{"l":"Far entrare il samurai liberato: conosce la sua debolezza","r":"Il giovane indica il punto in cui l’armatura è più sottile: il colpo del gruppo è letale.","to":"fb","fx":{"pow":20},"only":["alleato"],"id":"b"},{"l":"Onorare il giuramento: consegnargli la metà delle forze promessa","r":"Lo Shogun accetta, e in cambio ti offre il fianco di una sfida pulita: la sua armatura si allenta.","to":"fb","fx":{"pow":35,"flag":"oscuro"},"only":["patto"],"id":"c"},{"l":"Inchinarsi e proporre un duello leale","r":"Lo Shogun, colpito dal vostro rispetto, rinuncia a un vantaggio: un duello equo.","to":"fb","fx":{"pow":20,"flag":"puro"},"only":["onore"],"id":"d"},{"l":"Sfidare lo Shogun senza alcun accordo","r":"Lo Shogun si alza lentamente e sguaina la spada.","to":"fb","id":"e"},{"l":"Spezzare il giuramento e attaccarlo a sorpresa","r":"Lo Shogun, tradito, vi colpisce senza pietà.","to":"fb","fx":{"pow":-20,"hp":-15},"only":["patto"],"id":"f"}]},"fb":{"t":"fight","e":"Shogun Corazzato","em":"🏯","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["oscuro"],"to":"eDark"},{"if":["puro"],"to":"eBest"},{"if":["alleato"],"to":"eGood"}],"d":"eOk"},"eDark":{"t":"end","win":true,"title":"Il prezzo dell’onore","x":"Lo Shogun cade, ma il giuramento è onorato e voi lo portate con voi. Una vittoria amara, leale e potente.","text":"Lo Shogun cade, ma il giuramento è onorato e voi lo portate con voi. Una vittoria amara, leale e potente.","m":125},"eBest":{"t":"end","win":true,"title":"Inchino finale","x":"Il duello leale finisce con un inchino: lo Shogun, sconfitto, vi consegna la sua spada. Il vostro onore è intatto.","text":"Il duello leale finisce con un inchino: lo Shogun, sconfitto, vi consegna la sua spada. Il vostro onore è intatto.","m":140},"eGood":{"t":"end","win":true,"title":"La cittadella rispetta il vostro coraggio","x":"Il giovane samurai vi guida fino all’uscita tra mille inchini. La cittadella vi riconosce come ospiti d’onore.","text":"Il giovane samurai vi guida fino all’uscita tra mille inchini. La cittadella vi riconosce come ospiti d’onore.","m":115},"eOk":{"t":"end","win":true,"title":"Una vittoria senza cerimonie","x":"Lo Shogun cade nella polvere. Uscite senza applausi, ma a testa alta.","text":"Lo Shogun cade nella polvere. Uscite senza applausi, ma a testa alta.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il gong risveglia l’intera cittadella: mille lame vi circondano.","text":"Il gong risveglia l’intera cittadella: mille lame vi circondano.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La spada appoggiata è una trappola mortale: il dojo si chiude e le statue si animano.","text":"La spada appoggiata è una trappola mortale: il dojo si chiude e le statue si animano.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Lo Shogun vi sconfigge con un solo fendente: la spedizione finisce qui, con onore e senza gloria.","text":"Lo Shogun vi sconfigge con un solo fendente: la spedizione finisce qui, con onore e senza gloria.","m":100},"_flags":{"patto":"Patto stretto","onore":"Parola d’onore","alleato":"Alleato liberato","oscuro":"Patto onorato","puro":"Fiducia ripagata"}}$j$::jsonb),
 (41, $j${"_start":"s1","s1":{"t":"scene","n":"Prima prova","x":"La prima prova: un lungo corridoio di scaffali nel buio. Una voce sussurra: «Il Signore degli Incubi si nutre di paura, ma teme il suono di una campana d’argento». Su un tavolo: una campanella, una candela, una lente.","o":[{"l":"Prendere la candela e illuminare la strada","r":"La luce calda vi dà conforto e cura la stanchezza.","to":"f1","fx":{"hp":15},"id":"a"},{"l":"Aprire il libro più grande dello scaffale","r":"","to":"eF1","id":"b"},{"l":"Prendere la campanella d’argento e ascoltarne il suono","r":"La campanella ha un suono chiarissimo: ora capite perché il Signore degli Incubi la teme.","to":"f1","fx":{"flag":"indizio","pow":5},"id":"c"}]},"f1":{"t":"fight","e":"Libri Sognanti","em":"📖","m":1.0,"k":"n","w":"s2","l":"eDef"},"s2":{"t":"scene","n":"Seconda prova","x":"La seconda prova: una sala di leggio con un bibliotecario che dorme in piedi. Davanti a voi, un tappeto di fogli sparsi, un lampadario di candele e una scala a pioli.","o":[{"l":"Salire la scala a pioli fino al lampadario","r":"","to":"eF2","id":"a"},{"l":"Svegliare il bibliotecario e sfidarlo in duello","r":"Il bibliotecario si risveglia furioso, ma la lotta vi scalda i muscoli.","to":"f2","fx":{"pow":12,"hp":-20},"id":"b"},{"l":"Passare in punta di piedi tra i fogli","r":"Superate la sala senza svegliare nessuno, con qualche brivido.","to":"f2","fx":{"hp":-5},"id":"c"}]},"f2":{"t":"fight","e":"Bibliotecario Sonnambulo","em":"🧙","m":1.15,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"La prova finale","x":"La sala dell’Incubo. Il Signore degli Incubi è una nube nera nel cuore della biblioteca. Intorno, un cerchio di oggetti: una campana d’argento, una piuma, uno specchio e un orologio.","o":[{"l":"Accarezzare la piuma","r":"La piuma è il suo oggetto preferito: i sogni si fanno più cupi.","to":"fb","fx":{"pow":-25},"id":"a"},{"l":"Girare l’orologio al contrario","r":"Il tempo si inverte e con lui anche i vostri incubi peggiori.","to":"fb","fx":{"pow":-25},"id":"b"},{"l":"Suonare la campana d’argento","r":"Il suono taglia la nube come una lama: il Signore degli Incubi urla e si ritrae.","to":"fb","fx":{"pow":35,"flag":"punto"},"id":"c"},{"l":"Guardare nello specchio","r":"","to":"eF3","id":"d"}],"h":{"if":"indizio","t":"Ricordate la voce: il Signore degli Incubi teme la campana d’argento."}},"fb":{"t":"fight","e":"Signore degli Incubi","em":"🌫️","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["punto","indizio"],"to":"eBest"},{"if":["punto"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il risveglio","x":"Il Signore degli Incubi si dissolve nel suono d’argento. La biblioteca si sveglia, e con lei ogni sognatore intrappolato.","text":"Il Signore degli Incubi si dissolve nel suono d’argento. La biblioteca si sveglia, e con lei ogni sognatore intrappolato.","m":140},"eGood":{"t":"end","win":true,"title":"Sogni più leggeri","x":"Il Signore degli Incubi cade e i volumi riprendono a respirare piano. Potete uscire tra gli scaffali silenziosi.","text":"Il Signore degli Incubi cade e i volumi riprendono a respirare piano. Potete uscire tra gli scaffali silenziosi.","m":115},"eOk":{"t":"end","win":true,"title":"Un risveglio faticoso","x":"L’Incubo si dissolve, ma portate con voi un po’ della sua ombra. Uscite al mattino.","text":"L’Incubo si dissolve, ma portate con voi un po’ della sua ombra. Uscite al mattino.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il libro è un portale: vi risucchia dentro un incubo da cui non si esce.","text":"Il libro è un portale: vi risucchia dentro un incubo da cui non si esce.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il lampadario è una trappola: cade e porta con sé l’intera sala.","text":"Il lampadario è una trappola: cade e porta con sé l’intera sala.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Lo specchio mostra la vostra paura più grande: il gruppo non si risveglia mai più.","text":"Lo specchio mostra la vostra paura più grande: il gruppo non si risveglia mai più.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"L’Incubo vi inghiotte: la spedizione si addormenta per sempre tra gli scaffali.","text":"L’Incubo vi inghiotte: la spedizione si addormenta per sempre tra gli scaffali.","m":100},"_flags":{"indizio":"Indizio decifrato","punto":"Punto debole colpito"}}$j$::jsonb),
 (42, $j${"_start":"s1","s1":{"t":"scene","n":"Ingresso","x":"Il bordo del cratere è un anello di rocce fuse. Il terreno scricchiola: lastre di vetro scuro alternate a rocce opache. Si sentono tonfi lontani: stanno cadendo altri meteoriti.","o":[{"l":"Camminare sulle rocce opache, evitando il vetro","r":"Le rocce reggono: attraversate il bordo in sicurezza e notate un cristallo che pulsa nel suolo.","to":"s2","fx":{"pow":8,"flag":"indizio"},"id":"a"},{"l":"Correre sul vetro scuro per fare presto","r":"Il vetro crepita e si scheggia: ferite lievi e un golem che vi ha sentiti.","to":"f1e","fx":{"hp":-20,"pow":6},"id":"b"},{"l":"Raccogliere un frammento incandescente da terra","r":"","to":"eF1","id":"c"}]},"s2":{"t":"scene","n":"La chiave","x":"Il cristallo pulsa a ritmo regolare: «Dove la stella cade, la sua luce rimane». Davanti a voi, tre crateri minori: uno fumante, uno con una pozza d’acqua, uno con un nucleo luminoso a metà sepolto.","o":[{"l":"Scavare nel cratere con il nucleo luminoso","r":"Estraete un Cristallo Stellare ancora tiepido. Il rumore attira un golem.","to":"f1w","fx":{"pow":8,"flag":"key"},"id":"a"},{"l":"Immergere la mano nella pozza d’acqua","r":"","to":"eF2","id":"b"},{"l":"Passare oltre e non indugiare","r":"Senza cristallo, ma con meno rischi, proseguite.","to":"f1","fx":{"hp":-12},"id":"c"}]},"f1w":{"t":"fight","e":"Frammenti Vaganti","em":"🪨","m":0.85,"k":"n","w":"s3","l":"eDef"},"f1":{"t":"fight","e":"Frammenti Vaganti","em":"🪨","m":1.0,"k":"n","w":"s3","l":"eDef"},"f1e":{"t":"fight","e":"Golem di Roccia Stellare","em":"💫","m":1.3,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Il bivio finale","x":"Il Drago Meteora dorme nel cuore del cratere, avvolto da un anello di fuoco. A destra, una spaccatura che emette luce fredda. A sinistra, una pozza d’acqua gelida.","o":[{"l":"Buttarsi nella spaccatura luminosa","r":"","to":"eF3","id":"a"},{"l":"Avanzare attraverso l’anello di fuoco","r":"Il drago apre un occhio: le fiamme vi avvolgono.","to":"fb","id":"b"},{"l":"Usare il Cristallo Stellare per spegnere l’anello di fuoco","r":"Il cristallo assorbe il calore: l’anello si spegne e il drago perde la sua armatura incandescente.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"},{"l":"Immergersi nella pozza gelida per curarsi","r":"L’acqua cura, ma il rumore sveglia il drago, ancora più furioso.","to":"fb","fx":{"hp":35,"pow":-12},"id":"d"}]},"fb":{"t":"fight","e":"Drago Meteora","em":"🌠","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"La stella si spegne","x":"Senza fuoco, il drago si raffredda e si trasforma in un cristallo immobile. Il cratere tace per la prima volta in mille anni.","text":"Senza fuoco, il drago si raffredda e si trasforma in un cristallo immobile. Il cratere tace per la prima volta in mille anni.","m":140},"eGood":{"t":"end","win":true,"title":"Un cielo più calmo","x":"Il drago cade tra fiamme e polvere. Il cratere smette di tremare.","text":"Il drago cade tra fiamme e polvere. Il cratere smette di tremare.","m":115},"eOk":{"t":"end","win":true,"title":"Cenere e stelle","x":"Il drago si dissolve come una cometa. Uscite bruciacchiati, ma vivi.","text":"Il drago si dissolve come una cometa. Uscite bruciacchiati, ma vivi.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il frammento incandescente è una bomba a orologeria: esplode in mano al gruppo.","text":"Il frammento incandescente è una bomba a orologeria: esplode in mano al gruppo.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La pozza è acido stellare: il gruppo si dissolve tra le bolle.","text":"La pozza è acido stellare: il gruppo si dissolve tra le bolle.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"La spaccatura è un vuoto senza fondo: il gruppo cade nel cuore della stella.","text":"La spaccatura è un vuoto senza fondo: il gruppo cade nel cuore della stella.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Drago Meteora vi spazza via con un’onda di fuoco: la spedizione è fallita.","text":"Il Drago Meteora vi spazza via con un’onda di fuoco: la spedizione è fallita.","m":100},"_flags":{"indizio":"Indizio","key":"Cristallo Stellare","sigillo":"Sigillo spezzato"}}$j$::jsonb),
 (43, $j${"_start":"s1","s1":{"t":"scene","n":"Due strade","x":"Il bastione si apre su due vie. La scalinata gigante, con gradini alti come case, è sorvegliata da statue animate. Un sentiero di capre, stretto e nascosto tra le rocce, sale lungo la parete. Una runa dice: «Il piccolo passa dove il grande non può».","o":[{"l":"Colpire la grande campana alla base della scalinata","r":"","to":"eF1","id":"a"},{"l":"Salire la scalinata gigante affrontando le statue","r":"Le statue si animano con un boato: dovrete combattere.","to":"f1","fx":{"flag":"forza"},"id":"b"},{"l":"Imboccare il sentiero di capre tra le rocce","r":"Il sentiero è stretto e ventoso, ma nessun gigante vi vede.","to":"sp","id":"c"}]},"f1":{"t":"fight","e":"Giganti di Pietra","em":"🗿","m":1.1,"k":"n","w":"f2","l":"eDef"},"f2":{"t":"fight","e":"Aquile di Roccia","em":"🦅","m":1.2,"k":"e","w":"ss","l":"eDef"},"ss":{"t":"scene","n":"Il bottino","x":"Tra i giganti caduti: una clava ancora piena di forza, un otre d’idromele e un enorme scudo con una scritta in rune.","o":[{"l":"Impugnare la clava gigante","r":"La clava è pesante, ma ogni colpo ora fa tremare l’aria.","to":"s3","fx":{"pow":15},"id":"a"},{"l":"Bere l’idromele dell’otre","r":"L’idromele scalda le ossa e cura le ferite.","to":"s3","fx":{"hp":30},"id":"b"},{"l":"Sollevare lo scudo con le rune","r":"","to":"eF3","id":"c"}]},"sp":{"t":"scene","n":"Il passaggio nascosto","x":"Il sentiero sbocca in una grotta di echi. Tre corni sono appesi alle pareti: uno d’ottone, uno d’osso, uno d’argento. Un’incisione: «Il gigante ama il canto che sale dalla valle, non il rombo che scende».","o":[{"l":"Prendere il corno d’osso","r":"","to":"eF2","id":"a"},{"l":"Prendere il corno d’ottone","r":"Suona un rombo basso: un’aquila di roccia, offesa, piomba su di voi.","to":"f3","fx":{"hp":-25},"id":"b"},{"l":"Prendere il corno d’argento","r":"Il Corno del Gigante ha un suono limpido: quello che i giganti amano.","to":"s3","fx":{"hp":10,"flag":"key"},"id":"c"}]},"f3":{"t":"fight","e":"Giganti di Pietra","em":"🗿","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al covo","x":"La sala del Titano di Roccia Celeste: una caverna immensa, con un trono di roccia e un enorme petto che si alza e si abbassa. In alto, sul soffitto, una grande campana di bronzo.","o":[{"l":"Riposare tra le rocce prima di affrontarlo","r":"Il riposo cura, ma il Titano si sveglia con un ringhio e vi sorprende.","to":"fb","fx":{"hp":25,"pow":-8},"id":"a"},{"l":"Suonare il Corno del Gigante davanti al Titano","r":"Il Titano ascolta con calma: il suo ruggito si smorza e il suo passo rallenta.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"b"},{"l":"Attaccare il Titano a viso aperto","r":"Il Titano si alza con un tonfo e inizia a muoversi.","to":"fb","id":"c"}]},"fb":{"t":"fight","e":"Titano di Roccia Celeste","em":"🗿","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["forza"],"to":"eGood"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il canto del gigante","x":"Il Titano, ammansito dal canto, si siede e si addormenta. La caverna vibra di un silenzio dolcissimo.","text":"Il Titano, ammansito dal canto, si siede e si addormenta. La caverna vibra di un silenzio dolcissimo.","m":140},"eGood":{"t":"end","win":true,"title":"Le montagne tremano","x":"Il Titano cade con un boato. Il bastione, per la prima volta, è silenzioso.","text":"Il Titano cade con un boato. Il bastione, per la prima volta, è silenzioso.","m":115},"eOk":{"t":"end","win":true,"title":"Fuga tra le rocce","x":"Il Titano si sbriciola in un cumulo di massi. Uscite con le ossa dolenti.","text":"Il Titano si sbriciola in un cumulo di massi. Uscite con le ossa dolenti.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La campana risveglia ogni gigante del bastione: la roccia vi seppellisce in un istante.","text":"La campana risveglia ogni gigante del bastione: la roccia vi seppellisce in un istante.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il corno d’osso è fatto delle ossa di uno dei giganti: l’eco scatena una frana.","text":"Il corno d’osso è fatto delle ossa di uno dei giganti: l’eco scatena una frana.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Lo scudo è il coperchio di una trappola: il pavimento si apre e il gruppo precipita.","text":"Lo scudo è il coperchio di una trappola: il pavimento si apre e il gruppo precipita.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Titano vi spazza via con un solo passo: la spedizione è fallita.","text":"Il Titano vi spazza via con un solo passo: la spedizione è fallita.","m":100},"_flags":{"forza":"Via dei mostri","key":"Corno del Gigante","sigillo":"Accesso segreto"}}$j$::jsonb),
 (44, $j${"_start":"s1","s1":{"t":"scene","n":"Un incontro","x":"Un vecchio giocattolaio dalle mani di legno vi accoglie all’ingresso: «Vi mostro la strada per il Re, ma voglio qualcosa in cambio: una parte della vostra energia per animare i miei ultimi pezzi».","o":[{"l":"Smontare il giocattolaio pezzo per pezzo","r":"","to":"f0","id":"a"},{"l":"Rifiutare e cercare da soli la strada","r":"Il giocattolaio sospira: «Come volete. Le fabbriche sono lunghe». Vi lascia salire.","to":"s2","fx":{"pow":6,"flag":"onore"},"id":"b"},{"l":"Accettare il patto: cedere parte dell’energia","r":"Il giocattolaio sorride mentre una scintilla di forza vi lascia. Vi indica la scala.","to":"s2","fx":{"hp":-30,"flag":"patto"},"id":"c"}]},"f0":{"t":"fight","e":"Clown a Molla","em":"🤡","m":1.9,"k":"e","w":"s2","l":"eDef","wfx":{"pow":12}},"s2":{"t":"scene","n":"Il santuario","x":"Nel reparto dei giochi, una bambola di porcellana legata a un nastro supplica con voce sottile. Sul bancone, una scatola musicale d’oro suona piano. Un trenino sfreccia in cerchio.","o":[{"l":"Liberare la bambola di porcellana","r":"La bambola si scioglie dal nastro: giura di aiutarvi. L’operazione vi stanca un po’.","to":"f1","fx":{"hp":-10,"pow":15,"flag":"alleato"},"id":"a"},{"l":"Salire sul trenino in corsa","r":"","to":"eF1","id":"b"},{"l":"Passare oltre senza distrarvi","r":"Il trenino vi saluta con un fischio mentre andate avanti.","to":"f1","id":"c"},{"l":"Prendere la scatola musicale d’oro","r":"La scatola suona un motivo che vi rinvigorisce: qualcosa nell’ombra si muove.","to":"f1","fx":{"pow":10},"id":"d"}]},"f1":{"t":"fight","e":"Orsacchiotti d’Acciaio","em":"🧸","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al signore del luogo","x":"Il Re dei Giocattoli siede su un trono di cubi colorati, circondato da pupazzi. Sul tavolo davanti a lui, un grande orologio a molla.","o":[{"l":"Sfidare il Re senza alcun accordo","r":"Il Re vi osserva con occhi di vetro.","to":"fb","id":"a"},{"l":"Chiedere alla bambola di suggerire il punto debole del Re","r":"La bambola indica la molla dietro la schiena: un colpo preciso la rompe.","to":"fb","fx":{"pow":20},"only":["alleato"],"id":"b"},{"l":"Caricare a fondo l’orologio a molla sul tavolo","r":"","to":"eF2","id":"c"},{"l":"Presentarvi educatamente, senza chiedere nulla","r":"Il Re, colpito dalla vostra gentilezza, rinuncia a metà dei suoi giocattoli per un duello leale.","to":"fb","fx":{"pow":20,"flag":"puro"},"only":["onore"],"id":"d"},{"l":"Onorare il patto: donargli l’energia promessa per animare il suo trono","r":"Il Re, felice del dono, si distrae: il suo meccanismo si allenta.","to":"fb","fx":{"pow":35,"flag":"oscuro"},"only":["patto"],"id":"e"},{"l":"Spezzare il patto e attaccarlo senza preavviso","r":"Il Re, tradito, urla di rabbia: i suoi giocattoli vi attaccano furiosi.","to":"fb","fx":{"pow":-20,"hp":-15},"only":["patto"],"id":"f"}]},"fb":{"t":"fight","e":"Re dei Giocattoli","em":"🤡","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["oscuro"],"to":"eDark"},{"if":["puro"],"to":"eBest"},{"if":["alleato"],"to":"eGood"}],"d":"eOk"},"eDark":{"t":"end","win":true,"title":"Il giocattolo più prezioso","x":"Il Re cade, ma una parte di voi resta nella fabbrica, ad animare nuovi giocattoli. Vittoria amara, e potente.","text":"Il Re cade, ma una parte di voi resta nella fabbrica, ad animare nuovi giocattoli. Vittoria amara, e potente.","m":125},"eBest":{"t":"end","win":true,"title":"Una partita leale","x":"Il Re, senza i suoi pupazzi, riconosce di aver perso e si accascia con un sorriso di cartone. La fabbrica smette di suonare.","text":"Il Re, senza i suoi pupazzi, riconosce di aver perso e si accascia con un sorriso di cartone. La fabbrica smette di suonare.","m":140},"eGood":{"t":"end","win":true,"title":"La bambola vi ringrazia","x":"Il Re cade e la bambola vi accompagna alla porta. Alle vostre spalle, i giocattoli tacciono.","text":"Il Re cade e la bambola vi accompagna alla porta. Alle vostre spalle, i giocattoli tacciono.","m":115},"eOk":{"t":"end","win":true,"title":"Fuori dalla scatola","x":"Il Re si ferma con un ultimo cigolio. Uscite storditi dalla musica, ma liberi.","text":"Il Re si ferma con un ultimo cigolio. Uscite storditi dalla musica, ma liberi.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il trenino corre dritto in una galleria senza uscita: il gruppo scompare nel buio.","text":"Il trenino corre dritto in una galleria senza uscita: il gruppo scompare nel buio.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’orologio a molla scatta e libera una marea di giocattoli: il gruppo viene sommerso.","text":"L’orologio a molla scatta e libera una marea di giocattoli: il gruppo viene sommerso.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Re vi trasforma in giocattoli: la spedizione è fallita, e il vostro nome resta in un cassetto.","text":"Il Re vi trasforma in giocattoli: la spedizione è fallita, e il vostro nome resta in un cassetto.","m":100},"_flags":{"patto":"Patto stretto","onore":"Parola d’onore","alleato":"Alleato liberato","oscuro":"Patto onorato","puro":"Fiducia ripagata"}}$j$::jsonb),
 (45, $j${"_start":"s1","s1":{"t":"scene","n":"Prima prova","x":"La prima prova: una sala di colonne bianche. Su un piedistallo, un’iscrizione: «Il Drago Bianco non teme l’acciaio, ma si inchina davanti a chi ha il suo stesso sguardo». Davanti a voi: uno specchio d’argento, una maschera, un cristallo azzurro.","o":[{"l":"Raccogliere le scorte nel reliquiario","r":"Trovate acqua e pane. Il marmo è fresco e ristora.","to":"f1","fx":{"hp":15},"id":"a"},{"l":"Indossare la maschera sul piedistallo","r":"","to":"eF1","id":"b"},{"l":"Studiare l’iscrizione e il cristallo azzurro","r":"Il cristallo è identico agli occhi del drago: forse un giorno vi servirà.","to":"f1","fx":{"flag":"indizio","pow":5},"id":"c"}]},"f1":{"t":"fight","e":"Custodi di Marmo","em":"🗽","m":1.0,"k":"n","w":"s2","l":"eDef"},"s2":{"t":"scene","n":"Seconda prova","x":"La seconda prova: un corridoio di statue con le spade levate. Un Guardiano delle Reliquie sbarra il passo. A destra una porta d’oro, a sinistra una scala che scende nel buio.","o":[{"l":"Sfidare il Guardiano in duello leale","r":"Il combattimento vi scalda i muscoli e vi dà nuovo ardore, anche se costa fatica.","to":"f2","fx":{"pow":12,"hp":-20},"id":"a"},{"l":"Aprire la porta d’oro senza sapere cosa ci sia","r":"","to":"eF2","id":"b"},{"l":"Aggirare il Guardiano con circospezione","r":"Il Guardiano non vi nota. Qualche goccia di sudore freddo.","to":"f2","fx":{"hp":-5},"id":"c"}]},"f2":{"t":"fight","e":"Guardiano delle Reliquie","em":"🛡️","m":1.15,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"La prova finale","x":"La camera del Drago Bianco Antico. Il drago si erge su un altare di marmo. Intorno, quattro piedistalli con oggetti sacri: un anello, una piuma d’argento, un cristallo azzurro, una spada spezzata.","o":[{"l":"Sollevare il cristallo azzurro davanti agli occhi del drago","r":"Il drago si ferma, con lo sguardo incrociato: per un istante, riconosce se stesso in voi.","to":"fb","fx":{"pow":35,"flag":"punto"},"id":"a"},{"l":"Offrire la piuma d’argento","r":"La piuma è un insulto per chi non ha ali di piuma: il drago ruggisce.","to":"fb","fx":{"pow":-25},"id":"b"},{"l":"Prendere la spada spezzata","r":"","to":"eF3","id":"c"},{"l":"Offrire l’anello al drago","r":"Il drago lo disprezza: i gioielli non lo hanno mai interessato.","to":"fb","fx":{"pow":-25},"id":"d"}],"h":{"if":"indizio","t":"Ricordate l’iscrizione: il drago si inchina davanti a chi ha il suo sguardo. Il cristallo azzurro è identico ai suoi occhi."}},"fb":{"t":"fight","e":"Drago Bianco Antico","em":"🤍","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["punto","indizio"],"to":"eBest"},{"if":["punto"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Lo sguardo del drago","x":"Il drago si inchina davanti al riflesso dei suoi stessi occhi e svanisce in un’aura di luce. Il tempio brilla come un’alba.","text":"Il drago si inchina davanti al riflesso dei suoi stessi occhi e svanisce in un’aura di luce. Il tempio brilla come un’alba.","m":140},"eGood":{"t":"end","win":true,"title":"La leggenda continua","x":"Il drago cade, ma i suoi occhi continuano a brillare nel cristallo. La leggenda vi ha scelto.","text":"Il drago cade, ma i suoi occhi continuano a brillare nel cristallo. La leggenda vi ha scelto.","m":115},"eOk":{"t":"end","win":true,"title":"Un frammento di leggenda","x":"Il drago si ritira stremato. Uscite con un frammento della sua luce.","text":"Il drago si ritira stremato. Uscite con un frammento della sua luce.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La maschera è un sigillo: una volta indossata, il gruppo si trasforma in statue di marmo.","text":"La maschera è un sigillo: una volta indossata, il gruppo si trasforma in statue di marmo.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La porta d’oro conduce a una camera di fuoco: il gruppo brucia in un istante.","text":"La porta d’oro conduce a una camera di fuoco: il gruppo brucia in un istante.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"La spada spezzata è una maledizione: il gruppo si dissolve in polvere bianca.","text":"La spada spezzata è una maledizione: il gruppo si dissolve in polvere bianca.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Drago Bianco vi legge l’anima e vi sconfigge in un lampo. Spedizione fallita.","text":"Il Drago Bianco vi legge l’anima e vi sconfigge in un lampo. Spedizione fallita.","m":100},"_flags":{"indizio":"Indizio decifrato","punto":"Punto debole colpito"}}$j$::jsonb),
 (46, $j${"_start":"s1","s1":{"t":"scene","n":"Ingresso","x":"Il salone d’ingresso è un cerchio di specchi. Ogni riflesso vi imita, tranne uno che resta immobile e vi guarda. Sul pavimento, una linea di mattonelle d’argento porta a una porta.","o":[{"l":"Seguire le mattonelle d’argento ignorando i riflessi","r":"Il riflesso immobile sparisce quando smettete di guardarlo. Sulla porta vedete un’incisione.","to":"s2","fx":{"pow":8,"flag":"indizio"},"id":"a"},{"l":"Avvicinarsi al riflesso immobile per capirlo","r":"Il riflesso sorride e vi colpisce con la sua mano di vetro: ferite, e un sovrano rovesciato si desta.","to":"f1e","fx":{"hp":-20,"pow":6},"id":"b"},{"l":"Toccare il riflesso immobile","r":"","to":"eF1","id":"c"}]},"s2":{"t":"scene","n":"La chiave","x":"L’incisione dice: «Il frammento che non riflette è il solo che non mente». Davanti a voi, tre cornici: una con uno specchio a mosaico, una con un vetro nero opaco, una con uno specchio dorato.","o":[{"l":"Ignorare le cornici e andare avanti","r":"Senza frammento, ma con meno rumore, proseguite.","to":"f1","fx":{"hp":-12},"id":"a"},{"l":"Staccare il vetro nero opaco dalla cornice","r":"Sotto il vetro nero trovate il Frammento Nero, che non riflette nulla. Il rumore sveglia i riflessi.","to":"f1w","fx":{"pow":8,"flag":"key"},"id":"b"},{"l":"Rompere lo specchio dorato","r":"","to":"eF2","id":"c"}]},"f1w":{"t":"fight","e":"Riflessi Ribelli","em":"👥","m":0.85,"k":"n","w":"s3","l":"eDef"},"f1":{"t":"fight","e":"Riflessi Ribelli","em":"👥","m":1.0,"k":"n","w":"s3","l":"eDef"},"f1e":{"t":"fight","e":"Sovrano Rovesciato","em":"🎭","m":1.3,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Il bivio finale","x":"La sala del Doppio Perfetto. Siete in cerchio: ognuno ha il proprio riflesso davanti. Al centro, un grande specchio spezzato; a destra una candela; a sinistra un pozzo di vetro.","o":[{"l":"Sedersi accanto alla candela per riposare","r":"La luce cura, ma ogni riflesso vi guarda e il Doppio si fa più sicuro.","to":"fb","fx":{"hp":35,"pow":-12},"id":"a"},{"l":"Usare il Frammento Nero sullo specchio spezzato","r":"Il frammento assorbe i riflessi: il Doppio perde le sue copie e la sua sicurezza.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"b"},{"l":"Gettarsi nel pozzo di vetro","r":"","to":"eF3","id":"c"},{"l":"Sfidare il Doppio Perfetto a viso aperto","r":"Il Doppio vi copia, mossa per mossa, con un ghigno.","to":"fb","id":"d"}]},"fb":{"t":"fight","e":"Il Doppio Perfetto","em":"🪞","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il vero io","x":"Senza specchi, il Doppio non ha più nulla da copiare: crolla in mille schegge. Il palazzo, per la prima volta, mostra la vera luce.","text":"Senza specchi, il Doppio non ha più nulla da copiare: crolla in mille schegge. Il palazzo, per la prima volta, mostra la vera luce.","m":140},"eGood":{"t":"end","win":true,"title":"Riflessi spezzati","x":"Il Doppio cade in frantumi. Il palazzo smette di imitare i vostri passi.","text":"Il Doppio cade in frantumi. Il palazzo smette di imitare i vostri passi.","m":115},"eOk":{"t":"end","win":true,"title":"Specchio per allodole","x":"Il Doppio si dissolve in schegge, ma lascia profonde ferite. Uscite zoppicando.","text":"Il Doppio si dissolve in schegge, ma lascia profonde ferite. Uscite zoppicando.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il riflesso afferra la vostra mano e vi trascina dentro lo specchio: il gruppo scompare.","text":"Il riflesso afferra la vostra mano e vi trascina dentro lo specchio: il gruppo scompare.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Lo specchio dorato è una trappola di fuoco riflesso: il palazzo si incendia da ogni lato.","text":"Lo specchio dorato è una trappola di fuoco riflesso: il palazzo si incendia da ogni lato.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il pozzo di vetro è un’illusione: il gruppo cade in un vuoto senza fondo.","text":"Il pozzo di vetro è un’illusione: il gruppo cade in un vuoto senza fondo.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Doppio Perfetto vi copia e vi supera: la spedizione si frantuma, come uno specchio.","text":"Il Doppio Perfetto vi copia e vi supera: la spedizione si frantuma, come uno specchio.","m":100},"_flags":{"indizio":"Indizio","key":"Frammento Nero","sigillo":"Sigillo spezzato"}}$j$::jsonb),
 (47, $j${"_start":"s1","s1":{"t":"scene","n":"Due strade","x":"Il giardino si apre su due sentieri. Il viale di luce, ampio e dorato, è sorvegliato da guardiani. Un sentiero di polvere, quasi invisibile, scende dietro una siepe di stelle. Un cartello dice: «Ai piccoli i segreti, ai grandi le battaglie».","o":[{"l":"Seguire il sentiero di polvere dietro la siepe","r":"Il sentiero è silenzioso, e i guardiani non vi vedono.","to":"sp","id":"a"},{"l":"Prendere il viale di luce e sfidare i guardiani","r":"I guardiani si accendono: una battaglia a viso aperto.","to":"f1","fx":{"flag":"forza"},"id":"b"},{"l":"Raccogliere il fiore più luminoso dell’aiuola","r":"","to":"eF1","id":"c"}]},"f1":{"t":"fight","e":"Guardiani di Luce","em":"💫","m":1.1,"k":"n","w":"f2","l":"eDef"},"f2":{"t":"fight","e":"Fiori Carnivori Cosmici","em":"🌸","m":1.2,"k":"e","w":"ss","l":"eDef"},"ss":{"t":"scene","n":"Il bottino","x":"Tra i fiori e i guardiani caduti: una lente di cristallo stellare, un bocciolo che sprigiona nettare, una campana di vetro che emette una nota.","o":[{"l":"Bere il nettare del bocciolo","r":"Il nettare è dolce e curativo: le ferite si richiudono.","to":"s3","fx":{"hp":30},"id":"a"},{"l":"Suonare la campana di vetro","r":"","to":"eF3","id":"b"},{"l":"Impugnare la lente di cristallo stellare","r":"La lente concentra la luce: ogni colpo diventa un raggio.","to":"s3","fx":{"pow":15},"id":"c"}]},"sp":{"t":"scene","n":"Il passaggio nascosto","x":"Il sentiero di polvere sbocca in una serra rotonda. Tre vasi: uno con un seme nero, uno con un seme dorato, uno con un seme trasparente. Una targhetta: «La stella più piccola illumina il buio più profondo».","o":[{"l":"Prendere il seme trasparente","r":"Il Seme di Stella è piccolo come una goccia: custodisce una luce capace di illuminare il buio.","to":"s3","fx":{"hp":10,"flag":"key"},"id":"a"},{"l":"Prendere il seme nero","r":"","to":"eF2","id":"b"},{"l":"Prendere il seme dorato","r":"Il seme germoglia all’istante in un fiore carnivoro: dovrete difendervi.","to":"f3","fx":{"hp":-25},"id":"c"}]},"f3":{"t":"fight","e":"Guardiani di Luce","em":"💫","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al covo","x":"La torre dell’Astromante Supremo. In cima, un osservatorio con una grande lente puntata sul cielo. Il mago mormora calcoli. A lato, una cupola buia e un cannocchiale rotto.","o":[{"l":"Attaccare l’Astromante frontalmente","r":"L’Astromante alza gli occhi, sorride, e il cielo cambia.","to":"fb","id":"a"},{"l":"Sedersi sotto l’osservatorio per riposare","r":"Il riposo cura, ma l’Astromante ha avuto il tempo di leggere le vostre mosse.","to":"fb","fx":{"hp":25,"pow":-8},"id":"b"},{"l":"Piantare il Seme di Stella nella cupola buia","r":"La luce del seme invade la cupola: l’Astromante perde ogni punto di riferimento e le sue previsioni si confondono.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"}]},"fb":{"t":"fight","e":"Astromante Supremo","em":"🔭","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["forza"],"to":"eGood"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"L’alba cosmica","x":"L’Astromante, senza stelle da leggere, resta muto e svanisce. Il giardino sboccia di mille luci nuove.","text":"L’Astromante, senza stelle da leggere, resta muto e svanisce. Il giardino sboccia di mille luci nuove.","m":140},"eGood":{"t":"end","win":true,"title":"Il destino riscritto","x":"L’Astromante cade, e le stelle tornano a brillare a caso, come devono. Il giardino vi saluta.","text":"L’Astromante cade, e le stelle tornano a brillare a caso, come devono. Il giardino vi saluta.","m":115},"eOk":{"t":"end","win":true,"title":"Un po’ di polvere di stelle","x":"L’Astromante si ritira nel cielo. Uscite con la testa piena di stelle.","text":"L’Astromante si ritira nel cielo. Uscite con la testa piena di stelle.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il fiore è un’esca: il giardino si chiude come una mano di luce e vi stritola.","text":"Il fiore è un’esca: il giardino si chiude come una mano di luce e vi stritola.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il seme nero è un buco nero in miniatura: tutto ciò che è vicino scompare.","text":"Il seme nero è un buco nero in miniatura: tutto ciò che è vicino scompare.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"La campana scatena un’eco cosmica che spezza ogni cosa vicina: il gruppo svanisce.","text":"La campana scatena un’eco cosmica che spezza ogni cosa vicina: il gruppo svanisce.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"L’Astromante legge il vostro destino e lo riscrive in un attimo: la spedizione è fallita.","text":"L’Astromante legge il vostro destino e lo riscrive in un attimo: la spedizione è fallita.","m":100},"_flags":{"forza":"Via dei mostri","key":"Seme di Stella","sigillo":"Accesso segreto"}}$j$::jsonb),
 (48, $j${"_start":"s1","s1":{"t":"scene","n":"Un incontro","x":"All’ingresso della fucina un apprendista dal volto annerito vi sussurra: «Posso portarvi dal Fabbro ma mi serve una parte della vostra forza per riaccendere il forno. In cambio vi darò un’arma temprata».","o":[{"l":"Accettare il patto: cedere parte della forza al forno","r":"Il forno si ravviva e voi vi sentite stanchi. L’apprendista vi indica una porta.","to":"s2","fx":{"hp":-30,"flag":"patto"},"id":"a"},{"l":"Rifiutare e cercare un’altra via","r":"L’apprendista abbassa il capo: «Come volete». Vi lascia entrare comunque.","to":"s2","fx":{"pow":6,"flag":"onore"},"id":"b"},{"l":"Spegnere il forno con un colpo di secchio","r":"","to":"f0","id":"c"}]},"f0":{"t":"fight","e":"Salamandra del Forno","em":"🦎","m":1.9,"k":"e","w":"s2","l":"eDef","wfx":{"pow":12}},"s2":{"t":"scene","n":"Il santuario","x":"Nel cuore della fucina, un nano è incatenato a un’incudine. Su un banco, una spada fumante e già temprata riposa senza guardie. Un grosso martello, appeso, oscilla da solo.","o":[{"l":"Colpire l’incudine con il martello appeso","r":"","to":"eF1","id":"a"},{"l":"Liberare il nano dall’incudine","r":"Il nano, grato, giura di aiutarvi. L’operazione vi costa un po’ di fiato.","to":"f1","fx":{"hp":-10,"pow":15,"flag":"alleato"},"id":"b"},{"l":"Passare avanti senza fermarvi","r":"Il martello batte sull’incudine, ma voi siete già oltre.","to":"f1","id":"c"},{"l":"Prendere la spada fumante dal banco","r":"La spada è ardente e vi dà nuovo vigore. Qualcosa, nella fucina, si è mosso.","to":"f1","fx":{"pow":10},"id":"d"}]},"f1":{"t":"fight","e":"Automi d’Incudine","em":"🔩","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al signore del luogo","x":"Il Fabbro Divino lavora a un’enorme forgia. Intorno a lui, armi appese al soffitto. Sull’incudine, un pezzo di metallo incandescente.","o":[{"l":"Chiamare il nano liberato: conosce l’unico punto debole del Fabbro","r":"Il nano indica una crepa nell’armatura: ora sapete dove colpire.","to":"fb","fx":{"pow":20},"only":["alleato"],"id":"a"},{"l":"Onorare il patto: consegnare la forza promessa al Fabbro","r":"Il Fabbro accetta il dono e lo mette nella forgia: l’arma che ne esce è tua, e il suo rumore lo distrae.","to":"fb","fx":{"pow":35,"flag":"oscuro"},"only":["patto"],"id":"b"},{"l":"Spezzare il patto e attaccare il Fabbro","r":"Il Fabbro, tradito, solleva il martello con rabbia.","to":"fb","fx":{"pow":-20,"hp":-15},"only":["patto"],"id":"c"},{"l":"Presentarsi umilmente chiedendo solo una sfida onesta","r":"Il Fabbro, colpito dall’umiltà, posa il martello e accetta una sfida alla pari.","to":"fb","fx":{"pow":20,"flag":"puro"},"only":["onore"],"id":"d"},{"l":"Infilare la mano nel metallo incandescente","r":"","to":"eF2","id":"e"},{"l":"Sfidare il Fabbro senza altri accordi","r":"Il Fabbro solleva il suo martello e sorride.","to":"fb","id":"f"}]},"fb":{"t":"fight","e":"Fabbro Divino","em":"⚒️","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["oscuro"],"to":"eDark"},{"if":["puro"],"to":"eBest"},{"if":["alleato"],"to":"eGood"}],"d":"eOk"},"eDark":{"t":"end","win":true,"title":"L’arma temprata","x":"Il Fabbro cade, ma l’arma forgiata con la vostra forza resta nelle vostre mani. Una vittoria amara, ma ardente.","text":"Il Fabbro cade, ma l’arma forgiata con la vostra forza resta nelle vostre mani. Una vittoria amara, ma ardente.","m":125},"eBest":{"t":"end","win":true,"title":"Il martello a terra","x":"Il Fabbro posa il martello e ride: nessuno prima di voi aveva osato chiedere solo una sfida. Cade con onore.","text":"Il Fabbro posa il martello e ride: nessuno prima di voi aveva osato chiedere solo una sfida. Cade con onore.","m":140},"eGood":{"t":"end","win":true,"title":"La fucina vi accoglie","x":"Il nano e il Fabbro, riconciliati, vi regalano un’arma. La fucina canta.","text":"Il nano e il Fabbro, riconciliati, vi regalano un’arma. La fucina canta.","m":115},"eOk":{"t":"end","win":true,"title":"Scintille e cenere","x":"Il Fabbro cade, la forgia si spegne. Uscite bruciacchiati e con il fiato corto.","text":"Il Fabbro cade, la forgia si spegne. Uscite bruciacchiati e con il fiato corto.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"L’incudine è l’altare di un rito: il martello si abbatte da solo e il gruppo viene schiacciato.","text":"L’incudine è l’altare di un rito: il martello si abbatte da solo e il gruppo viene schiacciato.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il metallo incandescente vi fonde la mano e con essa tutto il gruppo.","text":"Il metallo incandescente vi fonde la mano e con essa tutto il gruppo.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Fabbro vi forgia in un nuovo pezzo di metallo: la spedizione è fallita.","text":"Il Fabbro vi forgia in un nuovo pezzo di metallo: la spedizione è fallita.","m":100},"_flags":{"patto":"Patto stretto","onore":"Parola d’onore","alleato":"Alleato liberato","oscuro":"Patto onorato","puro":"Fiducia ripagata"}}$j$::jsonb),
 (49, $j${"_start":"s1","s1":{"t":"scene","n":"Prima prova","x":"La prima prova: una zattera in mezzo alla nebbia. Un vecchio faro lampeggia lontano. Una voce rauca: «Il Kraken teme solo il fuoco del faro rosso». Sulla zattera: un fanale rosso, uno verde, un remo.","o":[{"l":"Esaminare il fanale rosso e memorizzare la voce","r":"Il fanale rosso brilla di una luce sinistra: forse è il fuoco che il Kraken teme.","to":"f1","fx":{"flag":"indizio","pow":5},"id":"a"},{"l":"Gettare i fanali in mare","r":"","to":"eF1","id":"b"},{"l":"Prendere il remo e riposare un attimo","r":"Il ritmo del remo calma la mente e dà sollievo ai muscoli.","to":"f1","fx":{"hp":15},"id":"c"}]},"f1":{"t":"fight","e":"Sirene Mute","em":"🧜","m":1.0,"k":"n","w":"s2","l":"eDef"},"s2":{"t":"scene","n":"Seconda prova","x":"La seconda prova: sirene mute cantano in silenzio da una scogliera. Davanti a voi, una barca da pesca con una rete, un corno di conchiglia e un anello di corda.","o":[{"l":"Aggirare la scogliera con prudenza","r":"Il giro è lungo ma sicuro: la nebbia vi nasconde.","to":"f2","fx":{"hp":-5},"id":"a"},{"l":"Affrontare le sirene dirette, con la rete in mano","r":"Le sirene si sollevano e combattono con rabbia: ne uscite con fiato corto ma con nuova energia.","to":"f2","fx":{"pow":12,"hp":-20},"id":"b"},{"l":"Soffiare nel corno di conchiglia","r":"","to":"eF2","id":"c"}]},"f2":{"t":"fight","e":"Squalo Fantasma","em":"🦈","m":1.15,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"La prova finale","x":"Il Kraken Spettrale emerge dalla nebbia: tentacoli d’ombra attorno a una torre di scoglio. Sul bordo, quattro fuochi: uno rosso, uno verde, uno giallo, uno bianco.","o":[{"l":"Accendere il fuoco rosso sulla torre di scoglio","r":"Il fuoco rosso fa ritrarre i tentacoli: il Kraken ulula e perde la presa sulla nebbia.","to":"fb","fx":{"pow":35,"flag":"punto"},"id":"a"},{"l":"Accendere il fuoco verde","r":"Il verde è il colore della calma: il Kraken si rafforza.","to":"fb","fx":{"pow":-25},"id":"b"},{"l":"Tuffarsi in acqua per sfidarlo da vicino","r":"","to":"eF3","id":"c"},{"l":"Accendere il fuoco giallo","r":"Il giallo è il suo colore preferito: il Kraken ride.","to":"fb","fx":{"pow":-25},"id":"d"}],"h":{"if":"indizio","t":"Ricordate la voce rauca: il Kraken teme solo il fuoco rosso."}},"fb":{"t":"fight","e":"Kraken Spettrale","em":"🦑","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["punto","indizio"],"to":"eBest"},{"if":["punto"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il faro rosso","x":"Il Kraken si ritira nelle profondità davanti al fuoco rosso. La nebbia si dirada e l’orizzonte finalmente appare.","text":"Il Kraken si ritira nelle profondità davanti al fuoco rosso. La nebbia si dirada e l’orizzonte finalmente appare.","m":140},"eGood":{"t":"end","win":true,"title":"La nebbia si alza","x":"Il Kraken cade e le onde si calmano. Una brezza leggera riporta il sole.","text":"Il Kraken cade e le onde si calmano. Una brezza leggera riporta il sole.","m":115},"eOk":{"t":"end","win":true,"title":"Approdo incerto","x":"Il Kraken si ritira nella nebbia. Raggiungete la riva a fatica, bagnati e stanchi.","text":"Il Kraken si ritira nella nebbia. Raggiungete la riva a fatica, bagnati e stanchi.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Senza fanali, la zattera si perde nella nebbia: il gruppo vaga per sempre.","text":"Senza fanali, la zattera si perde nella nebbia: il gruppo vaga per sempre.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il corno di conchiglia evoca un’onda gigantesca: la scogliera crolla sul gruppo.","text":"Il corno di conchiglia evoca un’onda gigantesca: la scogliera crolla sul gruppo.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il Kraken afferra il gruppo in acqua: nessuno riemerge.","text":"Il Kraken afferra il gruppo in acqua: nessuno riemerge.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Kraken vi trascina in profondità: la spedizione si perde nella nebbia.","text":"Il Kraken vi trascina in profondità: la spedizione si perde nella nebbia.","m":100},"_flags":{"indizio":"Indizio decifrato","punto":"Punto debole colpito"}}$j$::jsonb),
 (50, $j${"_start":"s1","s1":{"t":"scene","n":"Ingresso","x":"L’ingresso è un corridoio di geroglifici. Le pareti sono incise con una sequenza di immagini: sole, serpente, occhio, mano. Il pavimento ha quattro lastre con gli stessi simboli. Una scritta: «Si cammina come si legge».","o":[{"l":"Calpestare le lastre nell’ordine dei geroglifici: sole, serpente, occhio, mano","r":"Le lastre si illuminano una dopo l’altra. Il corridoio si apre su una nicchia.","to":"s2","fx":{"pow":8,"flag":"indizio"},"id":"a"},{"l":"Attraversare il corridoio di corsa sulle lastre libere","r":"Una pioggia di frecce vi sfiora: ferite, e gli sciacalli di Anubi vi sentono.","to":"f1e","fx":{"hp":-20,"pow":6},"id":"b"},{"l":"Staccare un geroglifico dalla parete","r":"","to":"eF1","id":"c"}]},"s2":{"t":"scene","n":"La chiave","x":"Nella nicchia, un’iscrizione recita: «Il nome tolto si nasconde dove la sabbia non entra». Tre sarcofagi: uno aperto e pieno di sabbia, uno sigillato con la cera, uno decorato con un occhio d’oro.","o":[{"l":"Aprire il sarcofago sigillato con la cera","r":"Dentro, intatto, il Cartiglio Regale con il nome cancellato. Alle vostre spalle, i sacerdoti si destano.","to":"f1w","fx":{"pow":8,"flag":"key"},"id":"a"},{"l":"Ignorare i sarcofagi e proseguire","r":"Senza cartiglio, ma con meno rumore, proseguite.","to":"f1","fx":{"hp":-12},"id":"b"},{"l":"Toccare l’occhio d’oro","r":"","to":"eF2","id":"c"}]},"f1w":{"t":"fight","e":"Sacerdoti Mummificati","em":"🧟","m":0.85,"k":"n","w":"s3","l":"eDef"},"f1":{"t":"fight","e":"Sacerdoti Mummificati","em":"🧟","m":1.0,"k":"n","w":"s3","l":"eDef"},"f1e":{"t":"fight","e":"Sciacalli di Anubi","em":"🐺","m":1.3,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Il bivio finale","x":"La camera del Faraone Immortale. Sul trono, il re senza nome. Ai lati, due statue di Anubi. Davanti a lui, un altare con una bilancia, un incensiere e una brocca.","o":[{"l":"Sostare davanti all’incensiere per ritemprarvi","r":"Il fumo cura, ma il Faraone ha già alzato lo scettro.","to":"fb","fx":{"hp":35,"pow":-12},"id":"a"},{"l":"Versare la brocca sulla bilancia","r":"","to":"eF3","id":"b"},{"l":"Deporre il Cartiglio Regale sull’altare e pronunciare il nome","r":"Il faraone ricorda il proprio nome e vacilla: il suo potere oscilla come una fiamma senza ossigeno.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"},{"l":"Sfidare il faraone a viso aperto","r":"Il Faraone si alza lentamente, senza dire una parola.","to":"fb","id":"d"}]},"fb":{"t":"fight","e":"Faraone Immortale","em":"👑","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il nome restituito","x":"Il faraone, ricordato dal proprio nome, ritrova la pace e svanisce con un sospiro. Il tempio crolla in una luce dorata.","text":"Il faraone, ricordato dal proprio nome, ritrova la pace e svanisce con un sospiro. Il tempio crolla in una luce dorata.","m":140},"eGood":{"t":"end","win":true,"title":"La fine dell’eternità","x":"Il Faraone cade e con lui il suo regno di sabbia. Il tempio torna a essere una tomba silenziosa.","text":"Il Faraone cade e con lui il suo regno di sabbia. Il tempio torna a essere una tomba silenziosa.","m":115},"eOk":{"t":"end","win":true,"title":"Sabbia tra i denti","x":"Il Faraone si dissolve in polvere. Uscite al sole del deserto, stanchi e vivi.","text":"Il Faraone si dissolve in polvere. Uscite al sole del deserto, stanchi e vivi.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"Il geroglifico è la chiave di una trappola: il soffitto si abbassa e vi schiaccia.","text":"Il geroglifico è la chiave di una trappola: il soffitto si abbassa e vi schiaccia.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’occhio d’oro è una maledizione: il gruppo si secca come una mummia.","text":"L’occhio d’oro è una maledizione: il gruppo si secca come una mummia.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"La bilancia pesa i vostri cuori: troppo leggeri. Una voragine si apre e vi inghiotte.","text":"La bilancia pesa i vostri cuori: troppo leggeri. Una voragine si apre e vi inghiotte.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Faraone vi riduce in sabbia: la spedizione è fallita, e il vostro nome si perde con il vento.","text":"Il Faraone vi riduce in sabbia: la spedizione è fallita, e il vostro nome si perde con il vento.","m":100},"_flags":{"indizio":"Indizio","key":"Cartiglio Regale","sigillo":"Sigillo spezzato"}}$j$::jsonb),
 (51, $j${"_start":"s1","s1":{"t":"scene","n":"Due strade","x":"La valle si divide. Il sentiero principale, battuto e fumante, attraversa un campo di nidi. Una scorciatoia stretta sale tra le rocce bruciate. Una pietra incisa dice: «Dalla cenere si sale, dalle fiamme si cade».","o":[{"l":"Attraversare il lago di lava per accorciare","r":"","to":"eF1","id":"a"},{"l":"Salire per la scorciatoia tra le rocce bruciate","r":"Il sentiero è ripido ma quasi privo di nemici.","to":"sp","id":"b"},{"l":"Percorrere il sentiero principale tra i nidi","r":"I nidi si agitano: dovrete combattere gli abitanti della valle.","to":"f1","fx":{"flag":"forza"},"id":"c"}]},"f1":{"t":"fight","e":"Pulcini Ardenti","em":"🐣","m":1.1,"k":"n","w":"f2","l":"eDef"},"f2":{"t":"fight","e":"Salamandre di Cenere","em":"🦎","m":1.2,"k":"e","w":"ss","l":"eDef"},"ss":{"t":"scene","n":"Il bottino","x":"Tra le ceneri dei nemici: una lama ancora rovente, una pozza di acqua fresca in una conca di roccia, un uovo dorato che pulsa.","o":[{"l":"Rompere l’uovo dorato","r":"","to":"eF3","id":"a"},{"l":"Bagnarsi nella pozza di acqua fresca","r":"L’acqua spegne le bruciature e ridà vigore.","to":"s3","fx":{"hp":30},"id":"b"},{"l":"Impugnare la lama rovente","r":"La lama canta: ogni colpo del gruppo brucia più forte.","to":"s3","fx":{"pow":15},"id":"c"}]},"sp":{"t":"scene","n":"Il passaggio nascosto","x":"La scorciatoia sbocca in una grotta di braci spente. Tre mucchi di cenere: uno bianco, uno grigio, uno nero. Una frase sulla parete: «La piuma che non brucia giace sotto la cenere più fredda».","o":[{"l":"Frugare nel mucchio di cenere grigia","r":"La cenere si ravviva e ne escono salamandre furiose.","to":"f3","fx":{"hp":-25},"id":"a"},{"l":"Frugare nel mucchio di cenere nera","r":"","to":"eF2","id":"b"},{"l":"Frugare nel mucchio di cenere bianca","r":"Sotto la cenere bianca, gelida, trovate la Piuma di Cenere: l’unica che non brucia mai.","to":"s3","fx":{"hp":10,"flag":"key"},"id":"c"}]},"f3":{"t":"fight","e":"Pulcini Ardenti","em":"🐣","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al covo","x":"Il nido della Fenice Imperitura: un anfiteatro di fuoco. Al centro, la fenice dorme su un braciere. Sul bordo, una fontana di fuoco e una lunga pedana di pietra.","o":[{"l":"Bagnarsi nella fontana di fuoco per curarsi","r":"Il fuoco cura, ma sveglia la fenice con un canto rabbioso.","to":"fb","fx":{"hp":25,"pow":-8},"id":"a"},{"l":"Deporre la Piuma di Cenere sul braciere della fenice","r":"La piuma assorbe parte del fuoco: la fenice si risveglia più debole.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"b"},{"l":"Attaccare la fenice nel suo nido","r":"La fenice apre le ali e il fuoco riempie la valle.","to":"fb","id":"c"}]},"fb":{"t":"fight","e":"Fenice Imperitura","em":"🔥","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["forza"],"to":"eGood"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"La cenere che non risorge","x":"Senza fuoco, la fenice si spegne come un ultimo respiro. La valle, per la prima volta, vede la neve.","text":"Senza fuoco, la fenice si spegne come un ultimo respiro. La valle, per la prima volta, vede la neve.","m":140},"eGood":{"t":"end","win":true,"title":"Un nuovo ciclo","x":"La fenice cade e rinasce piccola e tranquilla. La valle accoglie il vostro passaggio.","text":"La fenice cade e rinasce piccola e tranquilla. La valle accoglie il vostro passaggio.","m":115},"eOk":{"t":"end","win":true,"title":"Brace sotto la cenere","x":"La fenice si dissolve in scintille. Uscite stanchi, con piume bruciate tra i capelli.","text":"La fenice si dissolve in scintille. Uscite stanchi, con piume bruciate tra i capelli.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La lava ribolle sotto i passi: il gruppo affonda nel lago di fuoco.","text":"La lava ribolle sotto i passi: il gruppo affonda nel lago di fuoco.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La cenere nera è la polvere dei morti della valle: il gruppo si unisce a loro.","text":"La cenere nera è la polvere dei morti della valle: il gruppo si unisce a loro.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"L’uovo dorato è il cuore della fenice: il suo grido incenerisce tutto.","text":"L’uovo dorato è il cuore della fenice: il suo grido incenerisce tutto.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"La fenice vi riduce in cenere: la spedizione è fallita, ma la valle ricorderà il vostro fuoco.","text":"La fenice vi riduce in cenere: la spedizione è fallita, ma la valle ricorderà il vostro fuoco.","m":100},"_flags":{"forza":"Via dei mostri","key":"Piuma di Cenere","sigillo":"Accesso segreto"}}$j$::jsonb),
 (52, $j${"_start":"s1","s1":{"t":"scene","n":"Un incontro","x":"Alla gola vi attende una vecchia dragonessa ferita: «Posso portarvi dall’Anziano, ma ho bisogno della vostra forza per guarire le mie ali. In cambio, vi presterò la mia parola».","o":[{"l":"Rifiutare con rispetto e proseguire","r":"La dragonessa inclina il capo: «Un rifiuto onesto è un dono». Vi lascia passare.","to":"s2","fx":{"pow":6,"flag":"onore"},"id":"a"},{"l":"Attaccare la dragonessa ferita","r":"","to":"f0","id":"b"},{"l":"Accettare il patto: cedere parte della forza alla dragonessa","r":"La dragonessa si risolleva, voi vi sentite spossati. Vi mostra un sentiero tra le ossa.","to":"s2","fx":{"hp":-30,"flag":"patto"},"id":"c"}]},"f0":{"t":"fight","e":"Custode d’Ossa","em":"🦴","m":1.9,"k":"e","w":"s2","l":"eDef","wfx":{"pow":12}},"s2":{"t":"scene","n":"Il santuario","x":"Su un ponte d’ossa, un giovane drago è bloccato tra le costole di un antico scheletro. Poco lontano, un altare di pietra regge un grande uovo di cristallo.","o":[{"l":"Prendere l’uovo di cristallo dall’altare","r":"L’uovo vibra di energia antica: vi dà vigore, e fa ruggire qualcosa in lontananza.","to":"f1","fx":{"pow":10},"id":"a"},{"l":"Proseguire senza distrazioni","r":"Il ponte d’ossa scricchiola ma regge: siete oltre.","to":"f1","id":"b"},{"l":"Spezzare una costola dello scheletro per liberare il passaggio","r":"","to":"eF1","id":"c"},{"l":"Liberare il giovane drago","r":"Il giovane drago, sollevato, giura di aiutarvi. La fatica vi lascia un po’ ammaccati.","to":"f1","fx":{"hp":-10,"pow":15,"flag":"alleato"},"id":"d"}]},"f1":{"t":"fight","e":"Wyrm di Roccia","em":"🐍","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al signore del luogo","x":"L’Anziano dei Draghi riposa in una caverna di cristalli. I suoi occhi sono bracieri socchiusi. Sul pavimento, ossa di eroi e una grande incisione.","o":[{"l":"Sfidare l’Anziano senza alcun accordo","r":"L’Anziano apre un occhio e alza la testa.","to":"fb","id":"a"},{"l":"Spezzare il patto e attaccare l’Anziano","r":"L’Anziano, tradito, ruggisce: la caverna trema.","to":"fb","fx":{"pow":-20,"hp":-15},"only":["patto"],"id":"b"},{"l":"Onorare il patto: consegnare all’Anziano la forza promessa","r":"L’Anziano riconosce il patto e per un istante rallenta: il suo fiato si fa meno devastante.","to":"fb","fx":{"pow":35,"flag":"oscuro"},"only":["patto"],"id":"c"},{"l":"Chiamare il giovane drago: conosce la scaglia debole dell’Anziano","r":"Il giovane indica una scaglia più sottile sul petto: il colpo preciso è decisivo.","to":"fb","fx":{"pow":20},"only":["alleato"],"id":"d"},{"l":"Inchinarsi davanti all’Anziano e chiedere una sfida onesta","r":"L’Anziano, colpito dal rispetto, rinuncia alla sua furia e concede una sfida alla pari.","to":"fb","fx":{"pow":20,"flag":"puro"},"only":["onore"],"id":"e"},{"l":"Toccare l’incisione sul pavimento","r":"","to":"eF2","id":"f"}]},"fb":{"t":"fight","e":"Anziano dei Draghi","em":"🐲","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["oscuro"],"to":"eDark"},{"if":["puro"],"to":"eBest"},{"if":["alleato"],"to":"eGood"}],"d":"eOk"},"eDark":{"t":"end","win":true,"title":"Il patto dei draghi","x":"L’Anziano cade, ma il patto è onorato e un fuoco antico vive ora in voi. Una vittoria amara, e potente.","text":"L’Anziano cade, ma il patto è onorato e un fuoco antico vive ora in voi. Una vittoria amara, e potente.","m":125},"eBest":{"t":"end","win":true,"title":"Il rispetto degli antichi","x":"L’Anziano riconosce in voi un erede e si spegne con un sorriso di fuoco. La gola canta una canzone antica.","text":"L’Anziano riconosce in voi un erede e si spegne con un sorriso di fuoco. La gola canta una canzone antica.","m":140},"eGood":{"t":"end","win":true,"title":"Le ali del giovane drago","x":"Il giovane drago vi guida fuori dalla gola in volo. La valle, per la prima volta, vi saluta.","text":"Il giovane drago vi guida fuori dalla gola in volo. La valle, per la prima volta, vi saluta.","m":115},"eOk":{"t":"end","win":true,"title":"Tra le ossa","x":"L’Anziano cade con un ultimo respiro. Uscite stanchi, senza parole.","text":"L’Anziano cade con un ultimo respiro. Uscite stanchi, senza parole.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La costola è parte di una trappola: il ponte d’ossa crolla.","text":"La costola è parte di una trappola: il ponte d’ossa crolla.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’incisione è una maledizione: il gruppo viene trasformato in polvere d’osso.","text":"L’incisione è una maledizione: il gruppo viene trasformato in polvere d’osso.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"L’Anziano vi spazza via con un solo respiro: la spedizione è fallita.","text":"L’Anziano vi spazza via con un solo respiro: la spedizione è fallita.","m":100},"_flags":{"patto":"Patto stretto","onore":"Parola d’onore","alleato":"Alleato liberato","oscuro":"Patto onorato","puro":"Fiducia ripagata"}}$j$::jsonb),
 (53, $j${"_start":"s1","s1":{"t":"scene","n":"Prima prova","x":"La prima prova: un atrio senza pareti. Tre porte fluttuano nel vuoto. Una voce che sembra provenire da nessuno dice: «Il Vuoto teme solo ciò che è pieno di luce». Davanti a voi: una lampada, una moneta, una chiave.","o":[{"l":"Raccogliere la moneta e riposarsi un attimo","r":"La moneta è calda: vi dà conforto e cura la stanchezza.","to":"f1","fx":{"hp":15},"id":"a"},{"l":"Esaminare la lampada e conservare la voce","r":"La lampada contiene una luce piccola e ferma. È ciò che il Vuoto teme.","to":"f1","fx":{"flag":"indizio","pow":5},"id":"b"},{"l":"Aprire la porta più lontana","r":"","to":"eF1","id":"c"}]},"f1":{"t":"fight","e":"Ombre Dimenticate","em":"🌫️","m":1.0,"k":"n","w":"s2","l":"eDef"},"s2":{"t":"scene","n":"Seconda prova","x":"La seconda prova: un corridoio che si piega su sé stesso. Cavalieri assenti vi sbarrano la strada. Una scala sale a destra, un burrone si apre a sinistra.","o":[{"l":"Aggirare i cavalieri con prudenza","r":"Il corridoio si piega e vi lascia passare, ma i nervi sono tesi.","to":"f2","fx":{"hp":-5},"id":"a"},{"l":"Saltare nel burrone","r":"","to":"eF2","id":"b"},{"l":"Affrontare i cavalieri con decisione","r":"I cavalieri svaniscono ad ogni colpo, ma voi siete concentrati: ne uscite stanchi ma carichi.","to":"f2","fx":{"pow":12,"hp":-20},"id":"c"}]},"f2":{"t":"fight","e":"Cavalieri Assenti","em":"🛡️","m":1.15,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"La prova finale","x":"Il cuore della fortezza: una sfera nera pulsa al centro. La Sentinella del Vuoto vi osserva senza occhi. Intorno, quattro fonti: una lampada, un tamburo, uno specchio, una clessidra.","o":[{"l":"Capovolgere la clessidra","r":"Il tempo si svuota: la Sentinella è più forte che mai.","to":"fb","fx":{"pow":-25},"id":"a"},{"l":"Suonare il tamburo","r":"Il rumore riempie il vuoto, ma lo nutre: la Sentinella cresce.","to":"fb","fx":{"pow":-25},"id":"b"},{"l":"Accendere la lampada davanti alla Sentinella","r":"La luce riempie il vuoto: la Sentinella urla senza voce e si indebolisce a vista d’occhio.","to":"fb","fx":{"pow":35,"flag":"punto"},"id":"c"},{"l":"Guardare nello specchio","r":"","to":"eF3","id":"d"}],"h":{"if":"indizio","t":"Ricordate la voce: il Vuoto teme solo ciò che è pieno di luce. La lampada contiene una luce piccola e ferma."}},"fb":{"t":"fight","e":"Sentinella del Vuoto","em":"🌌","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["punto","indizio"],"to":"eBest"},{"if":["punto"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"Il vuoto riempito","x":"Con la luce, il Vuoto non ha più dove nascondersi. La Sentinella svanisce, e la fortezza collassa in una luce pallida.","text":"Con la luce, il Vuoto non ha più dove nascondersi. La Sentinella svanisce, e la fortezza collassa in una luce pallida.","m":140},"eGood":{"t":"end","win":true,"title":"Un’assenza in meno","x":"La Sentinella cade, e con lei la fortezza si sgretola piano. Siete di nuovo nel mondo.","text":"La Sentinella cade, e con lei la fortezza si sgretola piano. Siete di nuovo nel mondo.","m":115},"eOk":{"t":"end","win":true,"title":"Un respiro dal nulla","x":"La Sentinella si dissolve, ma portate con voi un po’ del suo silenzio.","text":"La Sentinella si dissolve, ma portate con voi un po’ del suo silenzio.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La porta lontana si apre sul nulla: il gruppo scompare senza lasciare traccia.","text":"La porta lontana si apre sul nulla: il gruppo scompare senza lasciare traccia.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"Il burrone non ha fondo: il gruppo cade per sempre.","text":"Il burrone non ha fondo: il gruppo cade per sempre.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Lo specchio non riflette: vi dimentica, e voi dimenticate di esistere.","text":"Lo specchio non riflette: vi dimentica, e voi dimenticate di esistere.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"La Sentinella vi svuota di ogni forza: la spedizione svanisce nel nulla.","text":"La Sentinella vi svuota di ogni forza: la spedizione svanisce nel nulla.","m":100},"_flags":{"indizio":"Indizio decifrato","punto":"Punto debole colpito"}}$j$::jsonb),
 (54, $j${"_start":"s1","s1":{"t":"scene","n":"Ingresso","x":"Nel grande atrio, uno scaffale ruota lentamente su sé stesso. Un cartello: «Chi legge nell’ordine non si perde». Ogni volume ha un numero sul dorso: 7, 3, 9, 1, 5.","o":[{"l":"Strappare l’ultima pagina del volume numero 9","r":"","to":"eF1","id":"a"},{"l":"Leggere i volumi in ordine crescente: 1, 3, 5, 7, 9","r":"I libri si accendono uno dopo l’altro e lo scaffale si apre su un passaggio. Sul muro, una frase.","to":"s2","fx":{"pow":8,"flag":"indizio"},"id":"b"},{"l":"Prendere il volume più vicino e sfogliarlo di corsa","r":"Il volume si rivela un trabocchetto: pagine taglienti vi colpiscono e un cronista vi nota.","to":"f1e","fx":{"hp":-20,"pow":6},"id":"c"}]},"s2":{"t":"scene","n":"La chiave","x":"La frase sul muro dice: «La penna che riscrive dorme dove l’inchiostro è secco». Tre scrittoi: uno con un calamaio pieno, uno con un calamaio asciutto, uno con un calamaio rotto.","o":[{"l":"Versare il calamaio pieno sul libro aperto","r":"","to":"eF2","id":"a"},{"l":"Frugare nel cassetto del calamaio asciutto","r":"Nel cassetto brilla la Penna d’Oro: scrive solo ciò che è vero. Il cronista, sentendola, si sveglia.","to":"f1w","fx":{"pow":8,"flag":"key"},"id":"b"},{"l":"Ignorare gli scrittoi e proseguire","r":"Senza penna, ma con meno rumore, proseguite.","to":"f1","fx":{"hp":-12},"id":"c"}]},"f1w":{"t":"fight","e":"Pagine Vaganti","em":"📜","m":0.85,"k":"n","w":"s3","l":"eDef"},"f1":{"t":"fight","e":"Pagine Vaganti","em":"📜","m":1.0,"k":"n","w":"s3","l":"eDef"},"f1e":{"t":"fight","e":"Cronista Senza Volto","em":"🖋️","m":1.3,"k":"e","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Il bivio finale","x":"Il Tessitore del Fato siede al centro di un telaio di fili d’argento che salgono verso il soffitto. A destra, una lampada d’olio. A sinistra, un libro aperto con le pagine bianche.","o":[{"l":"Sedersi a leggere accanto alla lampada d’olio","r":"La lettura cura, ma il Tessitore ha già tessuto la vostra trappola.","to":"fb","fx":{"hp":35,"pow":-12},"id":"a"},{"l":"Strappare un filo dal telaio","r":"","to":"eF3","id":"b"},{"l":"Scrivere la sconfitta del Tessitore con la Penna d’Oro","r":"La penna scrive ciò che è vero: il Tessitore vede il proprio destino e vacilla.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"c"},{"l":"Sfidare il Tessitore senza altri aiuti","r":"Il Tessitore intreccia un filo e il suo telaio si anima.","to":"fb","id":"d"}]},"fb":{"t":"fight","e":"Tessitore del Fato","em":"🕸️","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"L’ultima pagina riscritta","x":"La Penna d’Oro scrive la sua fine: il Tessitore si dissolve in un ultimo filo. La biblioteca, finalmente, ha un epilogo.","text":"La Penna d’Oro scrive la sua fine: il Tessitore si dissolve in un ultimo filo. La biblioteca, finalmente, ha un epilogo.","m":140},"eGood":{"t":"end","win":true,"title":"Un nuovo capitolo","x":"Il Tessitore cade e i libri riprendono a respirare. Ogni destino torna a chi lo vive.","text":"Il Tessitore cade e i libri riprendono a respirare. Ogni destino torna a chi lo vive.","m":115},"eOk":{"t":"end","win":true,"title":"Un finale aperto","x":"Il Tessitore si ritira nelle ombre. Uscite con un segnalibro e molte ferite.","text":"Il Tessitore si ritira nelle ombre. Uscite con un segnalibro e molte ferite.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"L’ultima pagina era l’epilogo di tutto il gruppo: la biblioteca lo chiude per sempre.","text":"L’ultima pagina era l’epilogo di tutto il gruppo: la biblioteca lo chiude per sempre.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"L’inchiostro prende vita e vi trascina dentro il libro: siete ora i suoi personaggi.","text":"L’inchiostro prende vita e vi trascina dentro il libro: siete ora i suoi personaggi.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"Il filo è collegato a tutti i destini: ne rompi uno, ed è il vostro.","text":"Il filo è collegato a tutti i destini: ne rompi uno, ed è il vostro.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Tessitore riscrive il vostro finale: la spedizione si chiude con una parola, FINE.","text":"Il Tessitore riscrive il vostro finale: la spedizione si chiude con una parola, FINE.","m":100},"_flags":{"indizio":"Indizio","key":"Penna d’Oro","sigillo":"Sigillo spezzato"}}$j$::jsonb),
 (55, $j${"_start":"s1","s1":{"t":"scene","n":"Due strade","x":"L’ultima sala si divide in due. A sinistra, un’arena con carte che volano in formazione: i campioni dei mille mazzi vi aspettano. A destra, un corridoio d’ombra che porta a un tavolo da gioco nascosto. Sul muro: «La mano migliore non è la più forte, ma la più giusta».","o":[{"l":"Imboccare il corridoio d’ombra verso il tavolo nascosto","r":"Il corridoio è silenzioso: nessuno vi ha visti entrare.","to":"sp","id":"a"},{"l":"Entrare nell’arena e sfidare le carte evocate","r":"Le carte si schierano: la partita comincia.","to":"f1","fx":{"flag":"forza"},"id":"b"},{"l":"Pescare la carta in cima al mazzo dell’arena","r":"","to":"eF1","id":"c"}]},"f1":{"t":"fight","e":"Carte Evocate","em":"🃏","m":1.1,"k":"n","w":"f2","l":"eDef"},"f2":{"t":"fight","e":"Campione dei Mille Mazzi","em":"🎴","m":1.2,"k":"e","w":"ss","l":"eDef"},"ss":{"t":"scene","n":"Il bottino","x":"Tra le carte abbattute: un deck box d’oro con una carta scintillante, una bevanda dell’ultima notte di gara, una carta con scritto «NON GIOCARE».","o":[{"l":"Bere la bevanda dell’ultima notte di gara","r":"Il liquido cura le ferite e ridà lucidità.","to":"s3","fx":{"hp":30},"id":"a"},{"l":"Giocare la carta con scritto «NON GIOCARE»","r":"","to":"eF3","id":"b"},{"l":"Inserire la carta scintillante nel proprio deck","r":"La carta vi dà un vantaggio inatteso: ogni colpo vale doppio.","to":"s3","fx":{"pow":15},"id":"c"}]},"sp":{"t":"scene","n":"Il passaggio nascosto","x":"Sul tavolo nascosto, tre carte coperte: una con un bordo dorato, una con un bordo nero, una con un bordo trasparente. Un biglietto: «La carta decisiva è quella che nessuno guarda».","o":[{"l":"Scoprire la carta con il bordo nero","r":"","to":"eF2","id":"a"},{"l":"Scoprire la carta con il bordo trasparente","r":"La Carta Decisiva è vostra: nessuno l’aveva mai notata, e solo voi sapete cosa fa.","to":"s3","fx":{"hp":10,"flag":"key"},"id":"b"},{"l":"Scoprire la carta con il bordo dorato","r":"La carta evoca un campione dal nulla: dovete affrontarlo.","to":"f3","fx":{"hp":-25},"id":"c"}]},"f3":{"t":"fight","e":"Carte Evocate","em":"🃏","m":1.0,"k":"n","w":"s3","l":"eDef"},"s3":{"t":"scene","n":"Davanti al covo","x":"Davanti a voi, il Duellante Primordiale, immobile dietro un tavolo da gioco infinito. A destra, un orologio di sabbia. A sinistra, un mazzo che cambia forma. Al centro, un solo slot vuoto.","o":[{"l":"Giocare la Carta Decisiva nello slot vuoto","r":"Lo slot si accende: il Duellante vede la carta che non aveva previsto, e sorride per la prima volta.","to":"fb","fx":{"pow":25,"flag":"sigillo"},"req":["key"],"id":"a"},{"l":"Sfidare il Duellante a viso aperto","r":"Il Duellante pesca la sua mano: la partita comincia.","to":"fb","id":"b"},{"l":"Prendere un momento per mescolare e ricentrarvi","r":"Il riposo cura, ma il Duellante ha visto ogni vostra intenzione.","to":"fb","fx":{"hp":25,"pow":-8},"id":"c"}]},"fb":{"t":"fight","e":"Il Duellante Primordiale","em":"🎴","m":1.0,"k":"b","w":"rw","l":"eDef"},"rw":{"t":"route","c":[{"if":["sigillo"],"to":"eBest"},{"if":["forza"],"to":"eGood"},{"if":["key"],"to":"eGood"}],"d":"eOk"},"eBest":{"t":"end","win":true,"title":"La mano decisiva","x":"Il Duellante Primordiale posa le carte e vi tende la mano: nessuno aveva mai giocato la carta giusta. Siete voi, ora, i custodi della partita.","text":"Il Duellante Primordiale posa le carte e vi tende la mano: nessuno aveva mai giocato la carta giusta. Siete voi, ora, i custodi della partita.","m":140},"eGood":{"t":"end","win":true,"title":"Vittoria per punti","x":"Il Duellante cade tra un vortice di carte. La partita finale è vostra: la leggenda può cominciare.","text":"Il Duellante cade tra un vortice di carte. La partita finale è vostra: la leggenda può cominciare.","m":115},"eOk":{"t":"end","win":true,"title":"Pareggio sul filo","x":"Il Duellante rinuncia a un’ultima mossa. Uscite con la testa alta, ma senza la certezza di aver giocato bene.","text":"Il Duellante rinuncia a un’ultima mossa. Uscite con la testa alta, ma senza la certezza di aver giocato bene.","m":85},"eF1":{"t":"end","win":false,"title":"Un passo falso","x":"La carta in cima era l’ultima del mazzo: evoca un campione che non potete battere.","text":"La carta in cima era l’ultima del mazzo: evoca un campione che non potete battere.","m":100},"eF2":{"t":"end","win":false,"title":"Una scelta fatale","x":"La carta nera è un contratto: firmandolo, perdete la partita prima di iniziarla.","text":"La carta nera è un contratto: firmandolo, perdete la partita prima di iniziarla.","m":100},"eF3":{"t":"end","win":false,"title":"L'ultimo errore","x":"La carta «NON GIOCARE» si attiva da sola: la partita finisce prima di cominciare.","text":"La carta «NON GIOCARE» si attiva da sola: la partita finisce prima di cominciare.","m":100},"eDef":{"t":"end","win":false,"title":"Sconfitta","x":"Il Duellante Primordiale gioca la mano perfetta: la partita finale è sua, e la spedizione è fallita.","text":"Il Duellante Primordiale gioca la mano perfetta: la partita finale è sua, e la spedizione è fallita.","m":100},"_flags":{"forza":"Via dei mostri","key":"Carta Decisiva","sigillo":"Accesso segreto"}}$j$::jsonb)
on conflict (dungeon_no) do update set graph = excluded.graph;

-- ---------- funzioni interne ----------
-- un solo scontro (con le stesse regole dei dungeon classici, ma gruppi più equi): p_pow = bonus/malus in % ai danni inflitti
create or replace function public._game_dng_clash(p_members jsonb, p_e jsonb, p_pow numeric, p_diff numeric, p_ref integer) returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare n integer := jsonb_array_length(p_members); j integer; k integer; rounds integer := 0; alive integer; tank integer; tgt integer; pick integer; heal_t integer; atk_n integer; ok boolean;
  ids text[]; rl text[]; hp numeric[]; mx numeric[]; sf numeric[]; sd numeric[]; ss numeric[]; sr numeric[]; lv numeric[]; dealt numeric[]; taken numeric[]; healed numeric[];
  ref_p numeric := 20 + 3 * (p_ref - 1); ref_for numeric := 5 + 0.4 * (20 + 3 * (p_ref - 1)) * p_ref; ref_hp numeric := 50 + 12 * (5 + 0.3 * (20 + 3 * (p_ref - 1)) * p_ref);
  mult numeric := coalesce((p_e->>'m')::numeric, 1); hits numeric := (p_e->>'hits')::numeric; apct numeric := (p_e->>'apct')::numeric;
  pw numeric := greatest(0.3, 1 + p_pow / 100.0); e_max numeric; e_hp numeric; e_atk numeric; dmg numeric; best numeric; amt numeric; crit boolean; mem jsonb := '[]'::jsonb;
begin
  for j in 1..n loop
    ids[j] := p_members->(j-1)->>'user_id'; rl[j] := p_members->(j-1)->>'role';
    hp[j] := (p_members->(j-1)->>'hp')::numeric; mx[j] := (p_members->(j-1)->>'mx')::numeric;
    sf[j] := (p_members->(j-1)->>'s_for')::numeric; sd[j] := (p_members->(j-1)->>'s_des')::numeric; ss[j] := (p_members->(j-1)->>'s_spi')::numeric; sr[j] := (p_members->(j-1)->>'s_frt')::numeric;
    lv[j] := (p_members->(j-1)->>'level')::numeric; dealt[j] := 0; taken[j] := 0; healed[j] := 0;
  end loop;
  e_max := hits * 3 * ref_for * (1 + 1.0 * (n - 1)) * p_diff * mult; e_hp := e_max;
  e_atk := ref_hp * apct * p_diff * mult;
  atk_n := 1 + n / 2;      -- attacchi del nemico per round: 1 giocatore 1; 2-3 giocatori 2; 4 giocatori 3
  loop
    rounds := rounds + 1;
    exit when rounds > 60;
    for j in 1..n loop
      if hp[j] > 0 then
        crit := random() < least(0.6, 0.05 + 0.4 * sd[j] / (5 + 10 * lv[j]));
        dmg := sf[j] * 3 * pw * (0.85 + 0.3 * random()) * (case when crit then 1.6 else 1 end) * (case rl[j] when 'dps' then 1.4 when 'tank' then 0.7 else 0.5 end);
        e_hp := e_hp - dmg; dealt[j] := dealt[j] + dmg;
        if rl[j] = 'support' then
          heal_t := null; best := 2;
          for k in 1..n loop if hp[k] > 0 and hp[k] / mx[k] < best then best := hp[k] / mx[k]; heal_t := k; end if; end loop;
          if heal_t is not null and best < 1 then
            amt := least(mx[heal_t] - hp[heal_t], ss[j] * 1.0 * (0.9 + 0.2 * random()));
            hp[heal_t] := hp[heal_t] + amt; healed[j] := healed[j] + amt;
          end if;
        end if;
      end if;
    end loop;
    exit when e_hp <= 0;
    for k in 1..atk_n loop
      alive := 0; tank := null;
      for j in 1..n loop if hp[j] > 0 then alive := alive + 1; if rl[j] = 'tank' then tank := j; end if; end if; end loop;
      exit when alive = 0;
      if tank is not null and random() < 0.6 then tgt := tank;
      else
        pick := 1 + floor(random() * alive)::integer; tgt := null;
        for j in 1..n loop if hp[j] > 0 then pick := pick - 1; if pick = 0 then tgt := j; exit; end if; end if; end loop;
      end if;
      if not (random() < least(0.5, 0.03 + 0.35 * sr[tgt] / (5 + 10 * lv[tgt]))) then
        dmg := e_atk * (0.9 + 0.2 * random()) * case when rl[tgt] = 'tank' then 0.7 else 1 end;
        hp[tgt] := greatest(0, hp[tgt] - dmg); taken[tgt] := taken[tgt] + dmg;
      end if;
    end loop;
    ok := false; for j in 1..n loop if hp[j] > 0 then ok := true; end if; end loop;
    exit when not ok;
  end loop;
  for j in 1..n loop
    mem := mem || jsonb_build_array(jsonb_build_object('user_id', ids[j], 'hp', hp[j], 'dealt', round(dealt[j]), 'taken', round(taken[j]), 'healed', round(healed[j]), 'ko', hp[j] <= 0));
  end loop;
  return jsonb_build_object('win', e_hp <= 0, 'rounds', rounds, 'enemy_hp', round(e_max), 'members', mem);
end $$;

-- effetto di una scelta: potenza del gruppo (%), PV (% dei massimi, mai letale), oggetti/indizi (flag)
create or replace function public._game_dng_fx(p_state jsonb, p_fx jsonb) returns jsonb language plpgsql immutable set search_path = public as $$
declare st jsonb := p_state; mem jsonb := '[]'::jsonb; x jsonb; f text; pct numeric;
begin
  if p_fx is null or p_fx = 'null'::jsonb then return st; end if;
  if p_fx ? 'pow' then st := jsonb_set(st, '{pow}', to_jsonb(greatest(-50, least(100, (st->>'pow')::integer + (p_fx->>'pow')::integer)))); end if;
  if p_fx ? 'hp' then
    pct := (p_fx->>'hp')::numeric;
    for x in select * from jsonb_array_elements(st->'members') loop
      if (x->>'hp')::numeric > 0 or pct > 0 then
        x := jsonb_set(x, '{hp}', to_jsonb(round(greatest(1, least((x->>'mx')::numeric, (x->>'hp')::numeric + (x->>'mx')::numeric * pct / 100.0)), 2)));
      end if;
      mem := mem || jsonb_build_array(x);
    end loop;
    st := jsonb_set(st, '{members}', mem);
  end if;
  if p_fx ? 'flag' then
    f := p_fx->>'flag';
    if not (st->'flags') @> to_jsonb(f) then st := jsonb_set(st, '{flags}', (st->'flags') || to_jsonb(f)); end if;
  end if;
  return st;
end $$;

-- fa avanzare la storia: risolve da sola bivi automatici, scontri e finali; si ferma alla prossima scelta oppure alla fine
create or replace function public._game_dng_advance(p_state jsonb, p_graph jsonb, p_no integer) returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare d public.game_dungeons%rowtype; st jsonb := p_state; nd jsonb; t text; guard integer := 0; diff numeric; res jsonb; fl text[]; c jsonb; hit text; mem jsonb; x jsonb; y jsonb; j integer;
  w boolean; kind text; hits numeric; apct numeric; rm jsonb; mm jsonb;
begin
  select * into d from public.game_dungeons where no = p_no;
  diff := d.diff * (0.8 + 0.55 * (1 - exp(-(d.ref_level - 1) / 25.0))) * greatest(10, public._setting('game_dng_difficulty')) / 100.0;
  loop
    guard := guard + 1;
    if guard > 40 then raise exception 'Percorso del dungeon non valido'; end if;
    nd := p_graph->(st->>'node');
    if nd is null then raise exception 'Percorso del dungeon non valido'; end if;
    t := nd->>'t';
    if t = 'scene' then return jsonb_build_object('state', st, 'end', null); end if;
    if t = 'end' then return jsonb_build_object('state', st, 'end', nd || jsonb_build_object('id', st->>'node')); end if;
    select coalesce(array_agg(f), '{}') into fl from jsonb_array_elements_text(st->'flags') f;
    if t = 'route' then
      hit := nd->>'d';
      for c in select * from jsonb_array_elements(nd->'c') loop
        if coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(c->'if') f), true) then hit := c->>'to'; exit; end if;
      end loop;
      st := jsonb_set(st, '{node}', to_jsonb(hit));
    elsif t = 'fight' then
      kind := coalesce(nd->>'k', 'n');
      hits := case kind when 'b' then 20 when 'e' then 16 else 12 end;
      apct := case kind when 'b' then 0.125 when 'e' then 0.11 else 0.09 end;
      res := public._game_dng_clash(st->'members', jsonb_build_object('m', coalesce((nd->>'m')::numeric, 1), 'hits', hits, 'apct', apct), (st->>'pow')::numeric, diff, d.ref_level);
      w := (res->>'win')::boolean;
      mem := '[]'::jsonb; mm := '[]'::jsonb;
      for j in 0..jsonb_array_length(st->'members') - 1 loop
        x := st->'members'->j; y := res->'members'->j;
        x := x || jsonb_build_object('dealt', (x->>'dealt')::numeric + (y->>'dealt')::numeric, 'taken', (x->>'taken')::numeric + (y->>'taken')::numeric, 'healed', (x->>'healed')::numeric + (y->>'healed')::numeric);
        mm := mm || jsonb_build_array(jsonb_build_object('user_id', x->>'user_id', 'nickname', x->>'nickname', 'role', x->>'role', 'dealt', (y->>'dealt')::numeric, 'taken', (y->>'taken')::numeric,
                                                          'healed', (y->>'healed')::numeric, 'hp', round((y->>'hp')::numeric), 'max_hp', round((x->>'mx')::numeric), 'ko', (y->>'ko')::boolean));
        if w then   -- dopo una vittoria il gruppo si riposa: +25% dei PV massimi (chi era KO torna con il 25%)
          x := jsonb_set(x, '{hp}', to_jsonb(round(case when (y->>'hp')::numeric <= 0 then 0.25 * (x->>'mx')::numeric else least((x->>'mx')::numeric, (y->>'hp')::numeric + 0.25 * (x->>'mx')::numeric) end, 2)));
        else
          x := jsonb_set(x, '{hp}', to_jsonb(round((y->>'hp')::numeric, 2)));
        end if;
        mem := mem || jsonb_build_array(x);
      end loop;
      st := jsonb_set(st, '{members}', mem);
      st := jsonb_set(st, '{rooms}', (st->'rooms') || jsonb_build_array(jsonb_build_object('no', jsonb_array_length(st->'rooms') + 1, 'name', nd->>'e', 'emoji', nd->>'em', 'boss', kind = 'b', 'cleared', w,
                                                                                         'rounds', (res->>'rounds')::integer, 'enemy_hp', (res->>'enemy_hp')::bigint, 'members', mm)));
      st := jsonb_set(st, '{log}', (st->'log') || jsonb_build_array(jsonb_build_object('k', 'f', 'e', nd->>'e', 'em', nd->>'em', 'boss', kind = 'b', 'win', w, 'rounds', (res->>'rounds')::integer)));
      if w then
        st := public._game_dng_fx(st, nd->'wfx');
        st := jsonb_set(st, '{node}', to_jsonb(nd->>'w'));
      else
        st := jsonb_set(st, '{node}', to_jsonb(nd->>'l'));
      end if;
    else
      raise exception 'Percorso del dungeon non valido';
    end if;
  end loop;
end $$;

-- ciò che il giocatore vede: scena corrente, opzioni (senza svelare gli effetti), gruppo, indizi, cronaca
create or replace function public._game_dng_view(p_run uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare r public.game_runs%rowtype; g jsonb; nd jsonb; st jsonb; fl text[]; opts jsonb := '[]'::jsonb; o jsonb; txt text; lock_ boolean; hint text; lbl jsonb;
begin
  select * into r from public.game_runs where id = p_run;
  if not found or r.state is null then return null; end if;
  st := r.state;
  select graph into g from public.game_dungeon_graphs where dungeon_no = r.dungeon_no;
  nd := g->(st->>'node');
  select coalesce(array_agg(f), '{}') into fl from jsonb_array_elements_text(st->'flags') f;
  lbl := coalesce(g->'_flags', '{}'::jsonb);
  if nd is not null and nd->>'t' = 'scene' then
    txt := nd->>'x';
    if nd ? 'h' and (nd->'h'->>'if') = any(fl) then txt := txt || E'\n\n' || (nd->'h'->>'t'); end if;
    for o in select * from jsonb_array_elements(nd->'o') loop
      continue when o ? 'only' and not coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(o->'only') f), true);
      lock_ := o ? 'req' and not coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(o->'req') f), true);
      hint := null;
      if lock_ then hint := 'Ti serve: ' || (select string_agg(coalesce(lbl->>f, f), ', ') from jsonb_array_elements_text(o->'req') f); end if;
      opts := opts || jsonb_build_array(jsonb_build_object('id', o->>'id', 'label', o->>'l', 'locked', lock_, 'hint', hint));
    end loop;
  end if;
  return jsonb_build_object('run_id', r.id, 'dungeon_no', r.dungeon_no, 'status', r.status, 'leader_id', r.leader_id, 'pow', (st->>'pow')::integer,
    'flags', coalesce((select jsonb_agg(jsonb_build_object('id', f, 'label', coalesce(lbl->>f, f))) from jsonb_array_elements_text(st->'flags') f), '[]'::jsonb),
    'members', coalesce((select jsonb_agg(jsonb_build_object('user_id', x->>'user_id', 'nickname', x->>'nickname', 'role', x->>'role', 'level', (x->>'level')::integer, 'hp', round((x->>'hp')::numeric), 'max_hp', round((x->>'mx')::numeric)))
                         from jsonb_array_elements(st->'members') x), '[]'::jsonb),
    'scene', case when txt is null then null else jsonb_build_object('id', st->>'node', 'title', nd->>'n', 'text', txt, 'options', opts) end,
    'step', jsonb_array_length(st->'log'), 'log', st->'log',
    'last_move_at', r.last_move_at, 'expires_at', r.last_move_at + make_interval(mins => greatest(1, public._setting('game_dng_path_minutes'))));
end $$;

-- premi e chiusura (vittoria o sconfitta). La resa dipende dal FINALE raggiunto (campo m, in %).
create or replace function public._game_dng_settle(p_run uuid, p_win boolean, p_end jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare r public.game_runs%rowtype; d public.game_dungeons%rowtype; m record; n integer; bonus numeric; res jsonb; outm jsonb := '[]'::jsonb; its jsonb; v_bc integer; v_xp bigint; first_ boolean;
  pr public.game_dungeon_progress%rowtype; rw jsonb; v_it text; v_cleared integer; milestone boolean; v_lvl integer; mult numeric := coalesce((p_end->>'m')::numeric, 100) / 100.0; st jsonb;
  v_cost integer := public._game_dng_cost(); v_found integer; v_total integer;
begin
  select * into r from public.game_runs where id = p_run for update;
  select * into d from public.game_dungeons where no = r.dungeon_no;
  st := r.state;
  select count(*) into n from public.game_run_members where run_id = p_run;
  bonus := 1 + public._setting('game_dng_party_bonus_pct') / 100.0 * (n - 1);
  for m in select gm.user_id, gm.role, p.nickname from public.game_run_members gm join public.profiles p on p.id = gm.user_id where gm.run_id = p_run order by gm.joined_at, gm.user_id loop
    its := '[]'::jsonb; v_bc := 0; milestone := false; v_it := null;
    if p_win then
      select * into pr from public.game_dungeon_progress where user_id = m.user_id and dungeon_no = d.no;
      first_ := not found or pr.clears = 0;
      v_bc := round(d.bc * bonus * mult * case when first_ then 1 else public._setting('game_dng_replay_bc_pct') / 100.0 end)::integer;
      v_xp := round(d.xp * mult * case when first_ then 1 else public._setting('game_dng_replay_xp_pct') / 100.0 end)::bigint;
      if first_ then
        if not exists (select 1 from public.game_inventory where user_id = m.user_id and item_id = d.item_id) then
          insert into public.game_inventory (user_id, item_id, source) values (m.user_id, d.item_id, 'dungeon');
          select jsonb_build_object('id', i.id, 'name', i.name, 'rarity', i.rarity, 'slot', i.slot, 'exclusive', true) into rw from public.game_items i where i.id = d.item_id;
          its := its || jsonb_build_array(rw);
        end if;
        if random() * 100 < public._setting('game_dng_drop_extra_pct') then v_it := public._game_dng_pool_item(m.user_id, d.no::integer); end if;
      else
        if random() * 100 < public._setting('game_dng_drop_replay_pct') then v_it := public._game_dng_pool_item(m.user_id, d.no::integer); end if;
      end if;
      if v_it is not null then
        insert into public.game_inventory (user_id, item_id, source) values (m.user_id, v_it, 'dungeon') on conflict do nothing;
        select jsonb_build_object('id', i.id, 'name', i.name, 'rarity', i.rarity, 'slot', i.slot, 'exclusive', false) into rw from public.game_items i where i.id = v_it;
        its := its || jsonb_build_array(rw);
      end if;
      if v_bc > 0 then
        perform public._ledger_move(m.user_id, v_bc, 'game_dungeon_reward', 'game_run', p_run, 'gamedng:' || p_run::text || ':' || m.user_id::text, 'La guerra degli Eroi: dungeon «' || d.name || '» completato');
      end if;
      insert into public.game_dungeon_progress (user_id, dungeon_no, clears, first_clear_at, last_clear_at) values (m.user_id, d.no, 1, now(), now())
        on conflict (user_id, dungeon_no) do update set clears = public.game_dungeon_progress.clears + 1, last_clear_at = now(),
                                                       first_clear_at = coalesce(public.game_dungeon_progress.first_clear_at, now());
      select count(*) into v_cleared from public.game_dungeon_progress where user_id = m.user_id and clears > 0;
      milestone := first_ and v_cleared % 5 = 0;
    else
      first_ := false; v_xp := round(d.xp * public._setting('game_dng_fail_xp_pct') / 100.0)::bigint;
    end if;
    insert into public.game_dungeon_endings (user_id, dungeon_no, ending)
      select m.user_id, d.no, p_end->>'id' where exists (select 1 from public.game_dungeon_graphs gg where gg.dungeon_no = d.no and gg.graph->(p_end->>'id')->>'t' = 'end') on conflict do nothing;   -- la resa e l'abbandono non sono finali della storia
    rw := public._game_add_xp(m.user_id, v_xp);
    select level into v_lvl from public.game_heroes where user_id = m.user_id;
    select count(*) into v_found from public.game_dungeon_endings where user_id = m.user_id and dungeon_no = d.no;
    outm := outm || jsonb_build_array(jsonb_build_object('user_id', m.user_id, 'nickname', m.nickname, 'role', m.role, 'first', first_, 'bc', v_bc, 'xp', (rw->>'xp')::bigint, 'levels', (rw->>'levels')::integer,
                                                        'level', v_lvl, 'items', its, 'milestone', milestone, 'endings_found', v_found));
  end loop;
  select count(*) into v_total from jsonb_each(coalesce((select graph from public.game_dungeon_graphs where dungeon_no = d.no), '{}'::jsonb)) e where e.value->>'t' = 'end';
  res := jsonb_build_object('path', true, 'win', p_win, 'rooms', st->'rooms', 'rooms_cleared', (select count(*) from jsonb_array_elements(st->'rooms') x where (x->>'cleared')::boolean),
                            'rooms_total', jsonb_array_length(st->'rooms'), 'members', outm, 'dropped', '[]'::jsonb, 'party_bonus', round((bonus - 1) * 100), 'cost', v_cost,
                            'story', st->'log', 'endings_total', v_total,
                            'ending', jsonb_build_object('id', p_end->>'id', 'title', p_end->>'title', 'text', p_end->>'text', 'm', round(mult * 100), 'win', p_win));
  update public.game_runs set status = case when p_win then 'cleared' else 'failed' end, finished_at = clock_timestamp(), result = res where id = p_run;
  return res;
end $$;

-- i dungeon a scelte lasciati a metà (nessuno decide più) vengono dati per falliti, con la consolazione prevista
create or replace function public._game_dng_expire_active() returns void language plpgsql security definer set search_path = public as $$
declare r record;
begin
  for r in select id from public.game_runs where status = 'active' and last_move_at < now() - make_interval(mins => greatest(1, public._setting('game_dng_path_minutes'))) order by id for update loop
    perform public._game_dng_settle(r.id, false, jsonb_build_object('id', 'abbandono', 'title', 'Spedizione abbandonata', 'text', 'Nessuno ha più preso una decisione: il gruppo si è disperso nel buio e la spedizione è fallita.', 'm', 100));
  end loop;
end $$;

-- chi è già dentro un dungeon a scelte non può aprirne o raggiungerne un altro
create or replace function public._game_dng_check(p_user uuid, p_no integer, p_role text) returns void language plpgsql security definer set search_path = public as $$
declare h public.game_heroes%rowtype; d public.game_dungeons%rowtype;
begin
  if p_role is null or p_role not in ('tank','dps','support') then raise exception 'Scegli un ruolo: Tank, Danni o Supporto'; end if;
  select * into d from public.game_dungeons where no = p_no;
  if not found then raise exception 'Dungeon inesistente'; end if;
  select * into h from public.game_heroes where user_id = p_user;
  if not h.stats_set then raise exception 'Prima assegna i tuoi punti abilità'; end if;
  if not public._game_dng_open(p_user, p_no) then raise exception 'Dungeon bloccato: completa prima il precedente'; end if;
  if h.level < d.min_level then raise exception 'Serve il livello % per questo dungeon', d.min_level; end if;
  if public._game_energy_of(p_user) < public._game_dng_cost() then raise exception 'Energia insufficiente: per un dungeon ne servono % (ora %)', public._game_dng_cost(), floor(public._game_energy_of(p_user)); end if;
  if exists (select 1 from public.game_run_members m join public.game_runs r on r.id = m.run_id where m.user_id = p_user and r.status = 'lobby') then raise exception 'Sei già in una lobby: esci prima'; end if;
  if exists (select 1 from public.game_run_members m join public.game_runs r on r.id = m.run_id where m.user_id = p_user and r.status = 'active') then raise exception 'Hai un dungeon in corso: finiscilo prima'; end if;
end $$;

-- ---------- funzioni pubbliche ----------
-- la partenza dei dungeon classici resta quella di prima (rinominata), quella dei dungeon a scelte è nuova
do $$
begin
  if not exists (select 1 from pg_proc where proname = '_game_dng_start_classic' and pronamespace = 'public'::regnamespace) then
    alter function public.game_dungeon_start(uuid) rename to _game_dng_start_classic;
  end if;
  if not exists (select 1 from pg_proc where proname = '_game_dng_state_base' and pronamespace = 'public'::regnamespace) then
    alter function public.game_dungeon_state() rename to _game_dng_state_base;
  end if;
end $$;

create or replace function public.game_dungeon_start(p_run uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare v uuid := public._need_role(array['user','organizer','moderator','admin']::public.app_role[]); r public.game_runs%rowtype; d public.game_dungeons%rowtype; m record; c record;
  v_cost integer := public._game_dng_cost(); mem jsonb := '[]'::jsonb; dropped jsonb := '[]'::jsonb; g jsonb; st jsonb; adv jsonb; n integer;
begin
  perform public._require_module('heroes');
  select * into r from public.game_runs where id = p_run;
  if not found or r.status <> 'lobby' then raise exception 'Questa lobby non esiste più o è già partita'; end if;
  select * into d from public.game_dungeons where no = r.dungeon_no;
  if d.kind <> 'path' then return public._game_dng_start_classic(p_run); end if;
  select * into r from public.game_runs where id = p_run for update;
  if r.status <> 'lobby' then raise exception 'Questa lobby non esiste più o è già partita'; end if;
  if r.leader_id <> v then raise exception 'Solo il capo della lobby può far partire il dungeon'; end if;
  perform public._game_dng_expire();
  if (select status from public.game_runs where id = p_run) <> 'lobby' then raise exception 'La lobby è scaduta: creane una nuova'; end if;
  select graph into g from public.game_dungeon_graphs where dungeon_no = d.no;
  if g is null then raise exception 'Dungeon non disponibile'; end if;
  for m in select gm.user_id from public.game_run_members gm where gm.run_id = p_run order by gm.user_id loop perform 1 from public.game_heroes where user_id = m.user_id for update; end loop;
  for m in select gm.user_id, p.nickname, p.suspended from public.game_run_members gm join public.profiles p on p.id = gm.user_id where gm.run_id = p_run order by gm.joined_at, gm.user_id loop
    if m.suspended or public._game_energy_of(m.user_id) < v_cost then
      if m.user_id = v then raise exception 'Energia insufficiente: per un dungeon ne servono % (ora %)', v_cost, floor(public._game_energy_of(v)); end if;
      delete from public.game_run_members where run_id = p_run and user_id = m.user_id;
      dropped := dropped || jsonb_build_array(m.nickname);
    end if;
  end loop;
  for m in select gm.user_id, gm.role, p.nickname from public.game_run_members gm join public.profiles p on p.id = gm.user_id where gm.run_id = p_run order by gm.joined_at, gm.user_id loop
    select * into c from public._game_calc(m.user_id);
    update public.game_heroes set energy = greatest(0, public._game_energy_of(m.user_id) - v_cost), energy_at = now(), last_active_at = now(), fights_total = fights_total + 1 where user_id = m.user_id;
    mem := mem || jsonb_build_array(jsonb_build_object('user_id', m.user_id, 'nickname', m.nickname, 'role', m.role, 'level', c.level,
        'mx', round(c.max_hp * case when m.role = 'tank' then 1.3 else 1 end, 2), 'hp', round(c.max_hp * case when m.role = 'tank' then 1.3 else 1 end, 2),
        's_for', c.s_for, 's_des', c.s_des, 's_spi', c.s_spi, 's_frt', c.s_frt, 'dealt', 0, 'taken', 0, 'healed', 0));
  end loop;
  st := jsonb_build_object('node', g->>'_start', 'pow', 0, 'flags', '[]'::jsonb, 'members', mem, 'log', '[]'::jsonb, 'rooms', '[]'::jsonb, 'dropped', dropped);
  adv := public._game_dng_advance(st, g, d.no::integer);
  update public.game_runs set status = 'active', started_at = clock_timestamp(), last_move_at = clock_timestamp(), state = adv->'state' where id = p_run;
  return jsonb_build_object('run_id', p_run, 'dungeon_no', d.no, 'status', 'active', 'view', public._game_dng_view(p_run));
end $$;

-- una scelta del capo gruppo
create or replace function public.game_dungeon_choose(p_run uuid, p_option text) returns jsonb language plpgsql security definer set search_path = public as $$
declare v uuid := public._need_role(array['user','organizer','moderator','admin']::public.app_role[]); r public.game_runs%rowtype; g jsonb; st jsonb; nd jsonb; o jsonb; fl text[]; adv jsonb; e jsonb; res jsonb;
begin
  perform public._require_module('heroes');
  select * into r from public.game_runs where id = p_run for update;
  if not found or r.status <> 'active' then raise exception 'Questo dungeon non è in corso'; end if;
  if r.last_move_at < now() - make_interval(mins => greatest(1, public._setting('game_dng_path_minutes'))) then
    perform public._game_dng_expire_active();
    return jsonb_build_object('run_id', p_run, 'dungeon_no', r.dungeon_no, 'status', 'failed', 'expired', true);
  end if;
  if r.leader_id <> v then raise exception 'Solo il capo gruppo può scegliere'; end if;
  select graph into g from public.game_dungeon_graphs where dungeon_no = r.dungeon_no;
  st := r.state; nd := g->(st->>'node');
  if nd is null or nd->>'t' <> 'scene' then raise exception 'Non c’è nessuna scelta da fare'; end if;
  select coalesce(array_agg(f), '{}') into fl from jsonb_array_elements_text(st->'flags') f;
  select x into o from jsonb_array_elements(nd->'o') x where x->>'id' = p_option;
  if o is null then raise exception 'Scelta non valida'; end if;
  if o ? 'only' and not coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(o->'only') f), true) then raise exception 'Scelta non valida'; end if;
  if o ? 'req' and not coalesce((select bool_and(f = any(fl)) from jsonb_array_elements_text(o->'req') f), true) then raise exception 'Questa scelta non è ancora disponibile'; end if;
  st := public._game_dng_fx(st, o->'fx');
  st := jsonb_set(st, '{log}', (st->'log') || jsonb_build_array(jsonb_build_object('k', 'c', 'n', nd->>'n', 'l', o->>'l', 'r', coalesce(o->>'r', ''))));
  st := jsonb_set(st, '{node}', to_jsonb(o->>'to'));
  adv := public._game_dng_advance(st, g, r.dungeon_no::integer);
  st := adv->'state'; e := adv->'end';
  update public.game_runs set state = st, last_move_at = clock_timestamp() where id = p_run;
  if e is not null and e <> 'null'::jsonb then
    res := public._game_dng_settle(p_run, coalesce((e->>'win')::boolean, false), e);
    return jsonb_build_object('run_id', p_run, 'dungeon_no', r.dungeon_no, 'status', case when (res->>'win')::boolean then 'cleared' else 'failed' end, 'result', res);
  end if;
  return jsonb_build_object('run_id', p_run, 'dungeon_no', r.dungeon_no, 'status', 'active', 'view', public._game_dng_view(p_run));
end $$;

-- il capo gruppo si arrende: spedizione fallita (consolazione prevista dal dungeon)
create or replace function public.game_dungeon_abandon(p_run uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare v uuid := public._need_role(array['user','organizer','moderator','admin']::public.app_role[]); r public.game_runs%rowtype; res jsonb;
begin
  perform public._require_module('heroes');
  select * into r from public.game_runs where id = p_run for update;
  if not found or r.status <> 'active' then raise exception 'Questo dungeon non è in corso'; end if;
  if r.leader_id <> v then raise exception 'Solo il capo gruppo può arrendersi'; end if;
  res := public._game_dng_settle(p_run, false, jsonb_build_object('id', 'resa', 'title', 'Ritirata', 'text', 'Il capo gruppo ha dato l’ordine di ritirarsi: la spedizione è finita qui.', 'm', 100));
  return jsonb_build_object('run_id', p_run, 'dungeon_no', r.dungeon_no, 'status', 'failed', 'result', res);
end $$;

-- stato: quello di prima più il dungeon in corso, il tipo di ogni dungeon e i finali scoperti
create or replace function public.game_dungeon_state() returns jsonb language plpgsql security definer set search_path = public as $$
declare v uuid := public._need_role(array['user','organizer','moderator','admin']::public.app_role[]); b jsonb; act uuid; cleared integer; total integer;
begin
  perform public._require_module('heroes');
  perform public._game_dng_expire_active();
  b := public._game_dng_state_base();
  select m.run_id into act from public.game_run_members m join public.game_runs r on r.id = m.run_id where m.user_id = v and r.status = 'active' order by r.started_at desc limit 1;
  cleared := (b->>'cleared')::integer; total := (b->>'total')::integer;
  b := jsonb_set(b, '{next_epic_in}', to_jsonb(case when cleared >= total then 0 else 5 - (cleared % 5) end));
  b := jsonb_set(b, '{dungeons}', coalesce((select jsonb_agg(e || jsonb_build_object('kind', d.kind,
          'endings_total', coalesce((select count(*) from jsonb_each(gg.graph) x where x.value->>'t' = 'end'), 0),
          'endings_found', (select count(*) from public.game_dungeon_endings en where en.user_id = v and en.dungeon_no = d.no),
          'forks', coalesce((select count(*) from jsonb_each(gg.graph) x where x.value->>'t' = 'scene'), 0)) order by d.no)
        from jsonb_array_elements(b->'dungeons') e join public.game_dungeons d on d.no = (e->>'no')::smallint left join public.game_dungeon_graphs gg on gg.dungeon_no = d.no), '[]'::jsonb));
  return b || jsonb_build_object('active', case when act is null then null else public._game_dng_view(act) end, 'path_minutes', public._setting('game_dng_path_minutes'));
end $$;

-- ---------- permessi ----------
alter table public.game_dungeon_graphs enable row level security;
alter table public.game_dungeon_endings enable row level security;
drop policy if exists game_dungeon_endings_read on public.game_dungeon_endings;
create policy game_dungeon_endings_read on public.game_dungeon_endings for select to authenticated using (user_id = auth.uid() and (public._module_on('heroes') or public.is_admin()));
revoke all on public.game_dungeon_graphs, public.game_dungeon_endings from public, anon, authenticated;
grant select on public.game_dungeon_endings to authenticated;
revoke all on function public._game_dng_clash(jsonb, jsonb, numeric, numeric, integer), public._game_dng_fx(jsonb, jsonb), public._game_dng_advance(jsonb, jsonb, integer), public._game_dng_view(uuid),
                public._game_dng_settle(uuid, boolean, jsonb), public._game_dng_expire_active(), public._game_dng_check(uuid, integer, text), public._game_dng_start_classic(uuid), public._game_dng_state_base()
  from public, anon, authenticated;
revoke all on function public.game_dungeon_start(uuid), public.game_dungeon_choose(uuid, text), public.game_dungeon_abandon(uuid), public.game_dungeon_state() from public, anon;
grant execute on function public.game_dungeon_start(uuid), public.game_dungeon_choose(uuid, text), public.game_dungeon_abandon(uuid), public.game_dungeon_state() to authenticated;

commit;
